package services

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"labsystem/internal/models"
	"sync"
	"time"
)

type EventService struct {
	DB      *sql.DB
	subMu   sync.RWMutex
	clients map[chan models.RealtimeEvent]bool
}

func NewEventService(db *sql.DB) *EventService {
	return &EventService{
		DB:      db,
		clients: make(map[chan models.RealtimeEvent]bool),
	}
}

func (s *EventService) Broadcast(eventType, entityType, entityID string, payload map[string]interface{}) (*models.RealtimeEvent, error) {
	if payload == nil {
		payload = map[string]interface{}{}
	}
	payloadJSON, err := json.Marshal(payload)
	if err != nil {
		payloadJSON = []byte("{}")
	}

	now := time.Now().UTC()
	var id int64
	err = s.DB.QueryRow(`
		INSERT INTO realtime_events (type, entity_type, entity_id, payload, created_at)
		VALUES ($1, $2, $3, $4::jsonb, $5)
		RETURNING id
	`, eventType, entityType, entityID, string(payloadJSON), now).Scan(&id)
	if err != nil {
		return nil, fmt.Errorf("failed to persist realtime event: %w", err)
	}

	event := models.RealtimeEvent{
		ID:         id,
		Type:       eventType,
		EntityType: entityType,
		EntityID:   entityID,
		Payload:    payload,
		CreatedAt:  models.FormatTime(now),
	}

	s.subMu.RLock()
	for ch := range s.clients {
		select {
		case ch <- event:
		default:
		}
	}
	s.subMu.RUnlock()

	return &event, nil
}

func (s *EventService) Subscribe() chan models.RealtimeEvent {
	ch := make(chan models.RealtimeEvent, 100)
	s.subMu.Lock()
	s.clients[ch] = true
	s.subMu.Unlock()
	return ch
}

func (s *EventService) Unsubscribe(ch chan models.RealtimeEvent) {
	s.subMu.Lock()
	delete(s.clients, ch)
	close(ch)
	s.subMu.Unlock()
}

func (s *EventService) GetEventsAfter(afterID int64, limit int) ([]models.RealtimeEvent, int64, error) {
	if limit <= 0 {
		limit = 100
	}
	rows, err := s.DB.Query(`
		SELECT id, type, entity_type, entity_id, payload, created_at
		FROM realtime_events
		WHERE id > $1
		ORDER BY id ASC
		LIMIT $2
	`, afterID, limit)
	if err != nil {
		return nil, 0, err
	}
	defer rows.Close()

	var events []models.RealtimeEvent
	var maxID int64 = afterID
	for rows.Next() {
		var id int64
		var evType, eType, eID string
		var payloadRaw []byte
		var createdAt time.Time

		if err := rows.Scan(&id, &evType, &eType, &eID, &payloadRaw, &createdAt); err != nil {
			return nil, 0, err
		}

		var payload map[string]interface{}
		_ = json.Unmarshal(payloadRaw, &payload)
		if payload == nil {
			payload = map[string]interface{}{}
		}

		events = append(events, models.RealtimeEvent{
			ID:         id,
			Type:       evType,
			EntityType: eType,
			EntityID:   eID,
			Payload:    payload,
			CreatedAt:  models.FormatTime(createdAt),
		})
		if id > maxID {
			maxID = id
		}
	}
	if events == nil {
		events = []models.RealtimeEvent{}
	}

	return events, maxID, nil
}

