	s.AuditService.LogAudit(actor.ID, actor.ActiveRole, "user.update_access", "user", targetUserID, true, map[string]interface{}{
		"roles":  roles,
		"quals":  quals,
		"active": active,
	})

	s.EventService.Broadcast("user.updated", "user", targetUserID, map[string]interface{}{
		"userId": targetUserID,
		"roles":  roles,
		"active": active,
	})

	return &models.User{
		UserID:         targetUserID,
		Username:       username,
		Email:          emailPtr,
		FullName:       fullNamePtr,
		Phone:          phonePtr,
		Roles:          roles,
		Qualifications: quals,
		Certifications: certs,
		Active:         active,
	}, nil
}

func (s *AuthService) GetUser(userID string) (*models.User, error) {
	var u models.User
	var email, fullName, phone sql.NullString
	var roles, quals pq.StringArray
	var certsRaw []byte

	err := s.DB.QueryRow(`
		SELECT id, username, email, full_name, phone, roles, qualifications, certifications, active
		FROM users
		WHERE id = $1
	`, userID).Scan(&u.UserID, &u.Username, &email, &fullName, &phone, &roles, &quals, &certsRaw, &u.Active)

	if err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return nil, ErrUserNotFound
		}
		return nil, err
	}

	u.Roles = []string(roles)
	u.Qualifications = []string(quals)
	if email.Valid {
		u.Email = &email.String
	}
	if fullName.Valid {
		u.FullName = &fullName.String
	}
	if phone.Valid {
		u.Phone = &phone.String
	}
	_ = json.Unmarshal(certsRaw, &u.Certifications)
	if u.Certifications == nil {
		u.Certifications = []models.Certification{}
	}

	return &u, nil
}
"}

