package services

import (
	"container/heap"
	"database/sql"
	"encoding/json"
	"errors"
	"fmt"
	"labsystem/internal/models"
	"math"
	"sync"
	"time"

	"github.com/google/uuid"
)

func Haversine(lat1, lon1, lat2, lon2 float64) float64 {
	const earthRadiusKm = 6371.0
	dLat := (lat2 - lat1) * (math.Pi / 180.0)
	dLon := (lon2 - lon1) * (math.Pi / 180.0)
	rLat1 := lat1 * (math.Pi / 180.0)
	rLat2 := lat2 * (math.Pi / 180.0)

	a := math.Sin(dLat/2)*math.Sin(dLat/2) +
		math.Cos(rLat1)*math.Cos(rLat2)*math.Sin(dLon/2)*math.Sin(dLon/2)
	c := 2 * math.Atan2(math.Sqrt(a), math.Sqrt(1-a))
	return earthRadiusKm * c
}

type ServiceabilityService struct {
	DB           *sql.DB
	AuditService *AuditService
	mu           sync.RWMutex
}

func NewServiceabilityService(db *sql.DB, audit *AuditService) *ServiceabilityService {
	return &ServiceabilityService{
		DB:           db,
		AuditService: audit,
	}
}

type ServiceabilityResult struct {
	Serviceable            bool
	Reason                 string
	TargetLaboratoryID     *string
	EstimatedArrivalAt     *string
	ServiceabilityVersion  int
	OriginCollectionNodeID *string
	RoutePath              []string
	TotalTravelMinutes     int
	TotalHandlingMinutes   int
	TotalCostUnits         float64
}

type NodeItem struct {
	LocationID      string
	Name            string
	Latitude        float64
	Longitude       float64
	CoverageKM      float64
	HandlingMinutes int
	Active          bool
	IsCollection    bool
	IsTransfer      bool
	IsHub           bool
	IsLaboratory    bool
	CapacityUnits   int
	ReservedUnits   int
	CooledCapacity  int
	CooledReserved  int
}

type EdgeItem struct {
	FromLocationID string
	ToLocationID   string
	TravelMinutes  int
	CostUnits      float64
	Cooled         bool
	Active         bool
	CapacityUnits  int
	ReservedUnits  int
	CooledCapacity int
	CooledReserved int
}

// Priority Queue for Dijkstra
type PathNode struct {
	LocationID   string
	TotalMinutes int
	TotalCost    float64
	Path         []string
	index        int
}

type PriorityQueue []*PathNode

func (pq PriorityQueue) Len() int           { return len(pq) }
func (pq PriorityQueue) Less(i, j int) bool { return pq[i].TotalMinutes < pq[j].TotalMinutes }
func (pq PriorityQueue) Swap(i, j int)      { pq[i], pq[j] = pq[j], pq[i]; pq[i].index = i; pq[j].index = j }
func (pq *PriorityQueue) Push(x interface{}) {
	n := len(*pq)
	item := x.(*PathNode)
	item.index = n
	*pq = append(*pq, item)
}
func (pq *PriorityQueue) Pop() interface{} {
	old := *pq
	n := len(old)
	item := old[n-1]
	old[n-1] = nil
	item.index = -1
	*pq = old[0 : n-1]
	return item
}

func (s *ServiceabilityService) GetCurrentVersion() (int, error) {
	var v int
	err := s.DB.QueryRow(`SELECT COALESCE(MAX(version), 1) FROM serviceability_snapshots WHERE status = 'complete'`).Scan(&v)
	if err != nil {
		return 1, err
	}
	return v, nil
}

func (s *ServiceabilityService) Check(origin models.Coordinate, originType string, originNodeID *string, sampleTypeID string, requestedAt time.Time, deliveryDeadline time.Time, earliestCol *time.Time, latestCol *time.Time) (*ServiceabilityResult, error) {
	version, _ := s.GetCurrentVersion()

	// Load Sample Type
	var st models.SampleType
	var incomp pq.StringArray
	err := s.DB.QueryRow(`
		SELECT id, name, qualified_collector_required, required_qualification, container_type, temperature_min_c, temperature_max_c, incompatible_sample_types, requires_cooled_route, batching_allowed
		FROM sample_types
		WHERE id = $1
	`, sampleTypeID).Scan(
		&st.SampleTypeID, &st.Name, &st.QualifiedCollectorRequired, &st.RequiredQualification,
		&st.ContainerType, &st.TemperatureMinC, &st.TemperatureMaxC, &incomp, &st.RequiresCooledRoute, &st.BatchingAllowed,
	)
	if err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return &ServiceabilityResult{
				Serviceable:           false,
				Reason:                "handling_rules_unsatisfiable",
				ServiceabilityVersion: version,
			}, nil
		}
		return nil, err
	}

	// Load all active locations
	rows, err := s.DB.Query(`
		SELECT id, name, latitude, longitude, coverage_km, handling_minutes, functions, capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units
		FROM locations
		WHERE active = true
	`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	nodesMap := make(map[string]NodeItem)
	for rows.Next() {
		var n NodeItem
		var fnRaw []byte
		if err := rows.Scan(&n.LocationID, &n.Name, &n.Latitude, &n.Longitude, &n.CoverageKM, &n.HandlingMinutes, &fnRaw, &n.CapacityUnits, &n.ReservedUnits, &n.CooledCapacity, &n.CooledReserved); err != nil {
			return nil, err
		}
		var fn models.LocationFunctionStates
		_ = json.Unmarshal(fnRaw, &fn)
		n.Active = true
		n.IsCollection = fn.CollectionPoint
		n.IsTransfer = fn.TransferPoint
		n.IsHub = fn.Hub
		n.IsLaboratory = fn.Laboratory
		nodesMap[n.LocationID] = n
	}

	// 1. Find Nearest Active Collection Point
	var startNode *NodeItem
	minDist := 999999.0

	if originType == "node" && originNodeID != nil && *originNodeID != "" {
		if n, ok := nodesMap[*originNodeID]; ok && (n.IsCollection || n.IsTransfer || n.IsHub) {
			startNode = &n
			minDist = 0
		}
	}

	if startNode == nil {
		for _, n := range nodesMap {
			if n.IsCollection {
				dist := Haversine(origin.Latitude, origin.Longitude, n.Latitude, n.Longitude)
				cov := n.CoverageKM
				if cov > 5.0 {
					cov = 5.0
				}
				if dist <= cov && dist < minDist {
					minDist = dist
					nodeCopy := n
					startNode = &nodeCopy
				}
			}
		}
	}

	if startNode == nil {
		return &ServiceabilityResult{
			Serviceable:           false,
			Reason:                "outside_service_coverage",
			ServiceabilityVersion: version,
		}, nil
	}

	// 2. Find Accepting Active Laboratories
	labRows, err := s.DB.Query(`
		SELECT la.laboratory_id
		FROM laboratory_acceptances la
		JOIN locations l ON la.laboratory_id = l.id
		WHERE la.sample_type_id = $1 AND la.accepts = true AND l.active = true
	`, sampleTypeID)
	if err != nil {
		return nil, err
	}
	defer labRows.Close()

	acceptingLabIDs := make(map[string]bool)
	for labRows.Next() {
		var labID string
		if err := labRows.Scan(&labID); err == nil {
			if labNode, ok := nodesMap[labID]; ok && labNode.IsLaboratory {
				acceptingLabIDs[labID] = true
			}
		}
	}

	if len(acceptingLabIDs) == 0 {
		return &ServiceabilityResult{
			Serviceable:           false,
			Reason:                "no_accepting_laboratory",
			ServiceabilityVersion: version,
		}, nil
	}

	// 3. Load Active Connections
	connRows, err := s.DB.Query(`
		SELECT from_location_id, to_location_id, travel_minutes, cost_units, cooled, capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units
		FROM connections
		WHERE active = true
	`)
	if err != nil {
		return nil, err
	}
	defer connRows.Close()

	adjList := make(map[string][]EdgeItem)
	for connRows.Next() {
		var e EdgeItem
		if err := connRows.Scan(&e.FromLocationID, &e.ToLocationID, &e.TravelMinutes, &e.CostUnits, &e.Cooled, &e.CapacityUnits, &e.ReservedUnits, &e.CooledCapacity, &e.CooledReserved); err == nil {
			e.Active = true
			// Check cooled requirement
			if st.RequiresCooledRoute && !e.Cooled {
				continue
			}
			adjList[e.FromLocationID] = append(adjList[e.FromLocationID], e)
		}
	}

	// 4. Dijkstra Shortest Path Search from startNode to an Accepting Laboratory
	// If startNode itself is an accepting laboratory:
	if acceptingLabIDs[startNode.LocationID] {
		// Check lab capacity
		hasCap := true
		if st.RequiresCooledRoute {
			if startNode.CooledReserved >= startNode.CooledCapacity {
				hasCap = false
			}
		} else {
			if startNode.ReservedUnits >= startNode.CapacityUnits {
				hasCap = false
			}
		}

		if !hasCap {
			return &ServiceabilityResult{
				Serviceable:           false,
				Reason:                "insufficient_capacity",
				ServiceabilityVersion: version,
			}, nil
		}

		colTime := time.Now().UTC()
		if earliestCol != nil && earliestCol.After(colTime) {
			colTime = *earliestCol
		} else if requestedAt.After(colTime) {
			colTime = requestedAt
		}
		estimatedArrival := colTime.Add(time.Duration(startNode.HandlingMinutes) * time.Minute)

		if estimatedArrival.After(deliveryDeadline) {
			return &ServiceabilityResult{
				Serviceable:           false,
				Reason:                "deadline_unreachable",
				ServiceabilityVersion: version,
			}, nil
		}

		estStr := models.FormatTime(estimatedArrival)
		labID := startNode.LocationID
		return &ServiceabilityResult{
			Serviceable:            true,
			Reason:                 "serviceable",
			TargetLaboratoryID:     &labID,
			EstimatedArrivalAt:     &estStr,
			ServiceabilityVersion:  version,
			OriginCollectionNodeID: &startNode.LocationID,
			RoutePath:              []string{startNode.LocationID},
			TotalTravelMinutes:     0,
			TotalHandlingMinutes:   startNode.HandlingMinutes,
			TotalCostUnits:         0,
		}, nil
	}

	pq := make(PriorityQueue, 0)
	heap.Init(&pq)
	heap.Push(&pq, &PathNode{
		LocationID:   startNode.LocationID,
		TotalMinutes: startNode.HandlingMinutes,
		TotalCost:    0,
		Path:         []string{startNode.LocationID},
	})

	visited := make(map[string]int)
	var bestPath *PathNode

	for pq.Len() > 0 {
		curr := heap.Pop(&pq).(*PathNode)

		if prevMin, seen := visited[curr.LocationID]; seen && prevMin <= curr.TotalMinutes {
			continue
		}
		visited[curr.LocationID] = curr.TotalMinutes

		if acceptingLabIDs[curr.LocationID] {
			bestPath = curr
			break
		}

		for _, edge := range adjList[curr.LocationID] {
			toNode, exists := nodesMap[edge.ToLocationID]
			if !exists {
				continue
			}

			// Check capacity on connection
			if st.RequiresCooledRoute {
				if edge.CooledReserved >= edge.CooledCapacity {
					continue
				}
			} else {
				if edge.ReservedUnits >= edge.CapacityUnits {
					continue
				}
			}

			newMinutes := curr.TotalMinutes + edge.TravelMinutes + toNode.HandlingMinutes
			newCost := curr.TotalCost + edge.CostUnits
			newPath := append(append([]string{}, curr.Path...), toNode.LocationID)

			heap.Push(&pq, &PathNode{
				LocationID:   toNode.LocationID,
				TotalMinutes: newMinutes,
				TotalCost:    newCost,
				Path:         newPath,
			})
		}
	}

	if bestPath == nil {
		return &ServiceabilityResult{
			Serviceable:           false,
			Reason:                "no_route",
			ServiceabilityVersion: version,
		}, nil
	}

	targetLabID := bestPath.LocationID
	targetLabNode := nodesMap[targetLabID]

	// Check lab capacity
	if st.RequiresCooledRoute {
		if targetLabNode.CooledReserved >= targetLabNode.CooledCapacity {
			return &ServiceabilityResult{
				Serviceable:           false,
				Reason:                "insufficient_capacity",
				ServiceabilityVersion: version,
			}, nil
		}
	} else {
		if targetLabNode.ReservedUnits >= targetLabNode.CapacityUnits {
			return &ServiceabilityResult{
				Serviceable:           false,
				Reason:                "insufficient_capacity",
				ServiceabilityVersion: version,
			}, nil
		}
	}

	// Delivery deadline check
	colTime := time.Now().UTC()
	if earliestCol != nil && earliestCol.After(colTime) {
		colTime = *earliestCol
	} else if requestedAt.After(colTime) {
		colTime = requestedAt
	}

	estimatedArrival := colTime.Add(time.Duration(bestPath.TotalMinutes) * time.Minute)
	if estimatedArrival.After(deliveryDeadline) {
		return &ServiceabilityResult{
			Serviceable:           false,
			Reason:                "deadline_unreachable",
			ServiceabilityVersion: version,
		}, nil
	}

	estStr := models.FormatTime(estimatedArrival)
	return &ServiceabilityResult{
		Serviceable:            true,
		Reason:                 "serviceable",
		TargetLaboratoryID:     &targetLabID,
		EstimatedArrivalAt:     &estStr,
		ServiceabilityVersion:  version,
		OriginCollectionNodeID: &startNode.LocationID,
		RoutePath:              bestPath.Path,
		TotalTravelMinutes:     bestPath.TotalMinutes,
		TotalHandlingMinutes:   startNode.HandlingMinutes,
		TotalCostUnits:         bestPath.TotalCost,
	}, nil
}

func (s *ServiceabilityService) PublishSnapshot() error {
	s.mu.Lock()
	defer s.mu.Unlock()

	rows, err := s.DB.Query(`
		SELECT id, name, latitude, longitude, coverage_km
		FROM locations
		WHERE active = true AND (functions->>'collection_point')::boolean = true
	`)
	if err != nil {
		return err
	}
	defer rows.Close()

	var regions []models.ServiceabilityRegion
	for rows.Next() {
		var r models.ServiceabilityRegion
		if err := rows.Scan(&r.LocationID, &r.Name, &r.Latitude, &r.Longitude, &r.CoverageKM); err == nil {
			regions = append(regions, r)
		}
	}
	if regions == nil {
		regions = []models.ServiceabilityRegion{}
	}

	regionsJSON, _ := json.Marshal(regions)

	var nextVersion int
	err = s.DB.QueryRow(`SELECT COALESCE(MAX(version), 0) + 1 FROM serviceability_snapshots`).Scan(&nextVersion)
	if err != nil {
		nextVersion = 1
	}

	_, err = s.DB.Exec(`
		INSERT INTO serviceability_snapshots (version, status, computed_at, network_revision, regions, active_collection_point_count)
		VALUES ($1, 'complete', NOW(), $1, $2::jsonb, $3)
	`, nextVersion, string(regionsJSON), len(regions))
	if err != nil {
		return fmt.Errorf("failed publishing serviceability snapshot: %w", err)
	}

	return nil
}

func (s *ServiceabilityService) GetLatestSnapshot() (map[string]interface{}, error) {
	var version, revision, activeCount int
	var status string
	var computedAt time.Time
	var regionsRaw []byte

	err := s.DB.QueryRow(`
		SELECT version, status, computed_at, network_revision, regions, active_collection_point_count
		FROM serviceability_snapshots
		WHERE status = 'complete'
		ORDER BY version DESC
		LIMIT 1
	`).Scan(&version, &status, &computedAt, &revision, &regionsRaw, &activeCount)

	if err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			_ = s.PublishSnapshot()
			return s.GetLatestSnapshot()
		}
		return nil, err
	}

	var regions []models.ServiceabilityRegion
	_ = json.Unmarshal(regionsRaw, &regions)
	if regions == nil {
		regions = []models.ServiceabilityRegion{}
	}

	return map[string]interface{}{
		"version":                    version,
		"status":                     status,
		"computedAt":                 models.FormatTime(computedAt),
		"networkRevision":            revision,
		"regions":                    regions,
		"activeCollectionPointCount": activeCount,
	}, nil
}

action.file_text:
package services

import (
	"database/sql"
	"encoding/json"
	"errors"
	"fmt"
	"labsystem/internal/models"
	"time"

	"github.com/google/uuid"
	"github.com/lib/pq"
)

var (
	ErrIneligibleWorker = errors.New("ineligible_worker")
	ErrAssignmentTaken  = errors.New("assignment_taken")
	ErrOfferNotOffered  = errors.New("offer_not_offered")
	ErrOfferNotAvailable= errors.New("offer_not_available")
	ErrAssignmentInactive = errors.New("assignment_inactive")
	ErrWorkerUnavailable = errors.New("worker_unavailable")
)

type AssignmentService struct {
	DB           *sql.DB
	AuditService *AuditService
	EventService *EventService
}

func NewAssignmentService(db *sql.DB, audit *AuditService, events *EventService) *AssignmentService {
	return &AssignmentService{
		DB:           db,
		AuditService: audit,
		EventService: events,
	}
}

type CandidateWorker struct {
	ID               string
	Username         string
	ActiveWorkload   int
	TotalCompleted   int
	HasDeclinedThis  bool
}

func (s *AssignmentService) FindEligibleWorkers(kind string, requiredRole string, requiredQual string, locationID *string, assignmentID *string) ([]CandidateWorker, error) {
	query := `
		SELECT u.id, u.username, u.roles, u.qualifications, u.certifications, u.active, u.available, u.assigned_location_id,
		       COALESCE((SELECT COUNT(*) FROM assignments a WHERE a.worker_id = u.id AND a.status IN ('offered', 'accepted', 'in_progress')), 0) as active_workload,
		       COALESCE((SELECT COUNT(*) FROM assignments a WHERE a.worker_id = u.id AND a.status = 'completed'), 0) as total_completed
		FROM users u
		WHERE u.active = true AND u.available = true AND $1 = ANY(u.roles)
	`
	rows, err := s.DB.Query(query, requiredRole)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	var candidates []CandidateWorker
	for rows.Next() {
		var id, username string
		var roles, quals pq.StringArray
		var certsRaw []byte
		var active, available bool
		var assignedLoc sql.NullString
		var activeWorkload, totalCompleted int

		if err := rows.Scan(&id, &username, &roles, &quals, &certsRaw, &active, &available, &assignedLoc, &activeWorkload, &totalCompleted); err != nil {
			return nil, err
		}

		// Node / Lab assignment location check
		if (kind == "node" || kind == "laboratory") && locationID != nil && *locationID != "" {
			if !assignedLoc.Valid || assignedLoc.String != *locationID {
				continue
			}
		}

		// Qualification check for collection
		if kind == "collection" && requiredQual != "" {
			var certs []models.Certification
			_ = json.Unmarshal(certsRaw, &certs)
			hasCert := false
			for _, c := range certs {
				if c.Code == requiredQual && c.Active {
					if c.ExpiresAt == nil || *c.ExpiresAt == "" {
						hasCert = true
						break
					}
					if exp, err := time.Parse(time.RFC3339, *c.ExpiresAt); err == nil && exp.After(time.Now().UTC()) {
						hasCert = true
						break
					}
				}
			}
			if !hasCert {
				for _, q := range quals {
					if q == requiredQual {
						hasCert = true
						break
					}
				}
			}
			if !hasCert {
				continue
			}
		}

		// Check if declined this assignment
		hasDeclined := false
		if assignmentID != nil && *assignmentID != "" {
			var declinedCount int
			_ = s.DB.QueryRow(`SELECT COUNT(*) FROM assignments WHERE id = $1 AND declined_by = $2`, *assignmentID, id).Scan(&declinedCount)
			if declinedCount > 0 {
				hasDeclined = true
			}
		}

		candidates = append(candidates, CandidateWorker{
			ID:              id,
			Username:        username,
			ActiveWorkload:  activeWorkload,
			TotalCompleted:  totalCompleted,
			HasDeclinedThis: hasDeclined,
		})
	}

	// Sort candidates:
	// 1. Not declined first
	// 2. Active workload ASC
	// 3. Total completed ASC
	for i := 0; i < len(candidates); i++ {
		for j := i + 1; j < len(candidates); j++ {
			c1 := candidates[i]
			c2 := candidates[j]
			swap := false
			if c1.HasDeclinedThis && !c2.HasDeclinedThis {
				swap = true
			} else if c1.HasDeclinedThis == c2.HasDeclinedThis {
				if c1.ActiveWorkload > c2.ActiveWorkload {
					swap = true
				} else if c1.ActiveWorkload == c2.ActiveWorkload {
					if c1.TotalCompleted > c2.TotalCompleted {
						swap = true
					}
				}
			}
			if swap {
				candidates[i], candidates[j] = candidates[j], candidates[i]
			}
		}
	}

	return candidates, nil
}

func (s *AssignmentService) OfferAssignmentToBestWorker(assignmentID string, kind string, requiredRole string, requiredQual string, locationID *string) (string, error) {
	candidates, err := s.FindEligibleWorkers(kind, requiredRole, requiredQual, locationID, &assignmentID)
	if err != nil {
		return "", err
	}

	if len(candidates) == 0 {
		return "", nil
	}

	best := candidates[0]
	expiresAt := time.Now().UTC().Add(15 * time.Minute)

	_, err = s.DB.Exec(`
		UPDATE assignments
		SET worker_id = $1, status = 'offered', offer_expires_at = $2, updated_at = NOW()
		WHERE id = $3
	`, best.ID, expiresAt, assignmentID)
	if err != nil {
		return "", err
	}

	s.AuditService.LogAudit(best.ID, requiredRole, "assignment.offer", "assignment", assignmentID, true, map[string]interface{}{
		"workerId":       best.ID,
		"kind":           kind,
		"offerExpiresAt": models.FormatTime(expiresAt),
	})

	s.EventService.Broadcast("assignment.offered", "assignment", assignmentID, map[string]interface{}{
		"assignmentId": assignmentID,
		"workerId":     best.ID,
		"kind":         kind,
	})

	return best.ID, nil
}

func (s *AssignmentService) AcceptAssignment(assignmentID, workerID string) error {
	var currentStatus string
	var assignedWorker sql.NullString
	var sampleID, journeyID, kind string
	err := s.DB.QueryRow(`
		SELECT status, worker_id, sample_id, journey_id, kind
		FROM assignments
		WHERE id = $1
	`, assignmentID).Scan(&currentStatus, &assignedWorker, &sampleID, &journeyID, &kind)

	if err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return ErrAssignmentInactive
		}
		return err
	}

	if !assignedWorker.Valid || assignedWorker.String != workerID {
		return ErrIneligibleWorker
	}

	if currentStatus == "accepted" {
		return nil // idempotent
	}

	if currentStatus != "offered" && currentStatus != "pending" {
		return ErrAssignmentInactive
	}

	_, err = s.DB.Exec(`
		UPDATE assignments
		SET status = 'accepted', updated_at = NOW()
		WHERE id = $1
	`, assignmentID)
	if err != nil {
		return err
	}

	// Update sample status
	sampleStatus := "scheduled"
	if kind == "collection" {
		sampleStatus = "collection_scheduled"
	} else if kind == "transport" {
		sampleStatus = "in_transit"
	}
	_, _ = s.DB.Exec(`UPDATE samples SET status = $1, updated_at = NOW() WHERE id = $2`, sampleStatus, sampleID)

	s.AuditService.LogTimeline("assignment.accepted", workerID, kind, "assignment", assignmentID, true, map[string]interface{}{
		"workerId": workerID,
		"sampleId": sampleID,
		"status":   "accepted",
	})

	s.AuditService.LogTimeline("sample.status_changed", workerID, kind, "sample", sampleID, true, map[string]interface{}{
		"newStatus": sampleStatus,
	})

	s.AuditService.LogAudit(workerID, kind, "assignment.accept", "assignment", assignmentID, true, map[string]interface{}{
		"workerId": workerID,
		"sampleId": sampleID,
		"status":   "accepted",
	})

	s.EventService.Broadcast("assignment.accepted", "assignment", assignmentID, map[string]interface{}{
		"assignmentId": assignmentID,
		"workerId":     workerID,
