{"file_text": "package services

import (
	"database/sql"
	"encoding/json"
	"errors"
	"fmt"
	"labsystem/internal/models"
	"time"

	"github.com/google/uuid"
	"github.com/lib/pq"
)

type OperationsService struct {
	DB                    *sql.DB
	AuditService          *AuditService
	EventService          *EventService
	ServiceabilityService *ServiceabilityService
}

func NewOperationsService(db *sql.DB, audit *AuditService, events *EventService, svc *ServiceabilityService) *OperationsService {
	return &OperationsService{
		DB:                    db,
		AuditService:          audit,
		EventService:          events,
		ServiceabilityService: svc,
	}
}

func (s *OperationsService) GetOperationsState() (*models.OperationsState, error) {
	now := time.Now().UTC()
	staleThreshold := now.Add(-10 * time.Minute)

	// 1. Samples
	sampleRows, err := s.DB.Query(`
		SELECT s.id, s.request_id, s.status, cr.origin_lat, cr.origin_lng, cr.delivery_deadline,
		       s.current_holder_id, s.active_journey_id, s.latest_lat, s.latest_lng, s.location_recorded_at
		FROM samples s
		JOIN collection_requests cr ON s.request_id = cr.id
	`)
	if err != nil {
		return nil, err
	}
	defer sampleRows.Close()

	var samples []map[string]interface{}
	for sampleRows.Next() {
		var sID, reqID, status string
		var oLat, oLng float64
		var deadline time.Time
		var holder, jID sql.NullString
		var lLat, lLng sql.NullFloat64
		var locRecordedAt sql.NullTime

		if err := sampleRows.Scan(&sID, &reqID, &status, &oLat, &oLng, &deadline, &holder, &jID, &lLat, &lLng, &locRecordedAt); err == nil {
			isStale := true
			if locRecordedAt.Valid && locRecordedAt.Time.After(staleThreshold) {
				isStale = false
			}

			sMap := map[string]interface{}{
				"sampleId":         sID,
				"sample_id":        sID,
				"requestId":        reqID,
				"status":           status,
				"origin":           models.Coordinate{Latitude: oLat, Longitude: oLng},
				"deliveryDeadline": models.FormatTime(deadline),
				"locationStale":    isStale,
			}
			if holder.Valid {
				sMap["currentHolderId"] = holder.String
			}
			if jID.Valid {
				sMap["activeJourneyId"] = jID.String
			}
			if lLat.Valid && lLng.Valid {
				sMap["latestLocation"] = models.Coordinate{Latitude: lLat.Float64, Longitude: lLng.Float64}
			}
			if locRecordedAt.Valid {
				sMap["locationRecordedAt"] = models.FormatTime(locRecordedAt.Time)
			}
			samples = append(samples, sMap)
		}
	}
	if samples == nil {
		samples = []map[string]interface{}{}
	}

	// 2. Workers
	workerRows, err := s.DB.Query(`
		SELECT u.id, u.full_name, u.roles, u.available, u.capacity_units, u.latest_location, u.location_recorded_at,
		       COALESCE((SELECT COUNT(*) FROM assignments a WHERE a.worker_id = u.id AND a.status IN ('offered', 'accepted', 'in_progress')), 0) as active_count
		FROM users u
		WHERE 'collection_professional' = ANY(u.roles) OR 'delivery_partner' = ANY(u.roles) OR 'node_handler' = ANY(u.roles) OR 'laboratory_team' = ANY(u.roles)
	`)
	if err != nil {
		return nil, err
	}
	defer workerRows.Close()

	var workers []map[string]interface{}
	minCount := 999999
	maxCount := 0

	for workerRows.Next() {
		var wID string
		var fullName sql.NullString
		var roles pq.StringArray
		var available bool
		var capUnits, activeCount int
		var latestLocRaw []byte
		var locRecordedAt sql.NullTime

		if err := workerRows.Scan(&wID, &fullName, &roles, &available, &capUnits, &latestLocRaw, &locRecordedAt, &activeCount); err == nil {
			statusStr := "available"
			if !available {
				statusStr = "unavailable"
			}

			isStale := true
			if locRecordedAt.Valid && locRecordedAt.Time.After(staleThreshold) {
				isStale = false
			}

			if activeCount < minCount {
				minCount = activeCount
			}
			if activeCount > maxCount {
				maxCount = activeCount
			}

			wMap := map[string]interface{}{
				"workerId":        wID,
				"worker_id":       wID,
				"fullName":        fullName.String,
				"roles":           []string(roles),
				"available":       available,
				"status":          statusStr,
				"capacityUnits":   capUnits,
				"assignmentCount": activeCount,
				"locationStale":   isStale,
			}

			if len(latestLocRaw) > 0 {
				var coord models.Coordinate
				if err := json.Unmarshal(latestLocRaw, &coord); err == nil {
					wMap["latestLocation"] = coord
					wMap["latest_location"] = coord
				}
			}
			if locRecordedAt.Valid {
				wMap["locationRecordedAt"] = models.FormatTime(locRecordedAt.Time)
			}
			workers = append(workers, wMap)
		}
	}
	if workers == nil {
		workers = []map[string]interface{}{}
		minCount = 0
	}
	spread := maxCount - minCount
	if spread < 0 {
		spread = 0
	}

	// Ineligible / unassigned count
	var ineligibleCount int
	_ = s.DB.QueryRow(`SELECT COUNT(*) FROM assignments WHERE status = 'pending' OR (status = 'offered' AND worker_id IS NULL)`).Scan(&ineligibleCount)

	// 3. Locations
	locRows, err := s.DB.Query(`
		SELECT id, name, latitude, longitude, coverage_km, handling_minutes, active, functions,
		       capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units
		FROM locations
	`)
	if err != nil {
		return nil, err
	}
	defer locRows.Close()

	var locations []models.OperationsLocation
	for locRows.Next() {
		var l models.OperationsLocation
		var fnRaw []byte
		var capUnits, resUnits, cooledCap, cooledRes int
		if err := locRows.Scan(&l.ID, &l.Name, &l.Coordinate.Latitude, &l.Coordinate.Longitude, &l.CoverageKM, &l.HandlingMinutes, &l.Active, &fnRaw, &capUnits, &resUnits, &cooledCap, &cooledRes); err == nil {
			l.LocationID = l.ID
			_ = json.Unmarshal(fnRaw, &l.Functions)
			l.Capacity = &models.Capacity{
				CapacityUnits:        capUnits,
				ReservedUnits:        resUnits,
				AvailableUnits:       capUnits - resUnits,
				CooledCapacityUnits:  cooledCap,
				CooledReservedUnits:  cooledRes,
				CooledAvailableUnits: cooledCap - cooledRes,
			}

			// Fetch accepted sample types
			var acceptedIDs []string
			accRows, _ := s.DB.Query(`SELECT sample_type_id FROM laboratory_acceptances WHERE laboratory_id = $1 AND accepts = true`, l.ID)
			if accRows != nil {
				for accRows.Next() {
					var stID string
					if err := accRows.Scan(&stID); err == nil {
						acceptedIDs = append(acceptedIDs, stID)
					}
				}
				accRows.Close()
			}
			l.AcceptedSampleTypeIDs = acceptedIDs
			locations = append(locations, l)
		}
	}
	if locations == nil {
		locations = []models.OperationsLocation{}
	}

	// 4. Connections
	connRows, err := s.DB.Query(`
		SELECT id, from_location_id, to_location_id, travel_minutes, cost_units, cooled, active,
		       capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units
		FROM connections
	`)
	if err != nil {
		return nil, err
	}
	defer connRows.Close()

	var connections []models.OperationsConnection
	for connRows.Next() {
		var c models.OperationsConnection
		var capUnits, resUnits, cooledCap, cooledRes int
		if err := connRows.Scan(&c.ID, &c.FromLocationID, &c.ToLocationID, &c.TravelMinutes, &c.CostUnits, &c.Cooled, &c.Active, &capUnits, &resUnits, &cooledCap, &cooledRes); err == nil {
			c.ConnectionID = c.ID
			c.Capacity = &models.Capacity{
				CapacityUnits:        capUnits,
				ReservedUnits:        resUnits,
				AvailableUnits:       capUnits - resUnits,
				CooledCapacityUnits:  cooledCap,
				CooledReservedUnits:  cooledRes,
				CooledAvailableUnits: cooledCap - cooledRes,
			}
			connections = append(connections, c)
		}
	}
	if connections == nil {
		connections = []models.OperationsConnection{}
	}

	// 5. Routes, Handoffs, Delays, Exceptions
	var handoffs []map[string]interface{}
	hRows, _ := s.DB.Query(`SELECT id, sample_id, sender_id, receiver_id, status, initiated_at, confirmed_at FROM handoffs`)
	if hRows != nil {
		defer hRows.Close()
		for hRows.Next() {
			var hID, sID, sendID, recID, status string
			var initAt time.Time
			var confAt sql.NullTime
			if err := hRows.Scan(&hID, &sID, &sendID, &recID, &status, &initAt, &confAt); err == nil {
				hMap := map[string]interface{}{
					"handoffId":   hID,
					"sampleId":    sID,
					"senderId":    sendID,
					"receiverId":  recID,
					"status":      status,
					"initiatedAt": models.FormatTime(initAt),
				}
				if confAt.Valid {
					hMap["confirmedAt"] = models.FormatTime(confAt.Time)
				}
				handoffs = append(handoffs, hMap)
			}
		}
	}
	if handoffs == nil {
		handoffs = []map[string]interface{}{}
	}

	var exceptions []map[string]interface{}
	excRows, _ := s.DB.Query(`SELECT id, request_id, status, exception FROM samples WHERE exception IS NOT NULL OR status = 'exception'`)
	if excRows != nil {
		defer excRows.Close()
		for excRows.Next() {
			var sID, reqID, status string
			var excRaw []byte
			if err := excRows.Scan(&sID, &reqID, &status, &excRaw); err == nil {
				var exc map[string]interface{}
				_ = json.Unmarshal(excRaw, &exc)
				exceptions = append(exceptions, map[string]interface{}{
					"sampleId":  sID,
					"requestId": reqID,
					"status":    status,
					"exception": exc,
				})
			}
		}
	}
	if exceptions == nil {
		exceptions = []map[string]interface{}{}
	}

	routes := []map[string]interface{}{}
	delays := []map[string]interface{}{}

	return &models.OperationsState{
		Samples:                   samples,
		Workers:                   workers,
		Locations:                 locations,
		Connections:               connections,
		Routes:                    routes,
		Handoffs:                  handoffs,
		Delays:                    delays,
		Exceptions:                exceptions,
		AssignmentCountSpread:     spread,
		IneligibleAssignmentCount: ineligibleCount,
	}, nil
}

func (s *OperationsService) ConfigureCapacity(resourceID string, capUnits, cooledUnits int) error {
	// Try updating Location first
	res, err := s.DB.Exec(`
		UPDATE locations
		SET capacity_units = $1, cooled_capacity_units = $2, updated_at = NOW()
		WHERE id = $3
	`, capUnits, cooledUnits, resourceID)
	if err == nil {
		if rows, _ := res.RowsAffected(); rows > 0 {
			_ = s.ServiceabilityService.PublishSnapshot()
			return nil
		}
	}

	// Try updating Connection
	res, err = s.DB.Exec(`
		UPDATE connections
		SET capacity_units = $1, cooled_capacity_units = $2, updated_at = NOW()
		WHERE id = $3
	`, capUnits, cooledUnits, resourceID)
	if err == nil {
		if rows, _ := res.RowsAffected(); rows > 0 {
			_ = s.ServiceabilityService.PublishSnapshot()
			return nil
		}
	}

	return errors.New("not_found")
}

func (s *OperationsService) ConfigureLabAcceptance(labID, stID string, accepts bool) (string, error) {
	var id string
	err := s.DB.QueryRow(`
		INSERT INTO laboratory_acceptances (id, laboratory_id, sample_type_id, accepts)
		VALUES ($1, $2, $3, $4)
		ON CONFLICT (laboratory_id, sample_type_id) DO UPDATE SET accepts = EXCLUDED.accepts
		RETURNING id
	`, uuid.New(), labID, stID, accepts).Scan(&id)
	if err != nil {
		return "", err
	}

	_ = s.ServiceabilityService.PublishSnapshot()
	return id, nil
}

func (s *OperationsService) CreateLocation(name string, coord models.Coordinate, covKM float64, handMin int, active bool, fn models.LocationFunctionStates) (*models.Location, error) {
	locID := uuid.New().String()
	if covKM <= 0 || covKM > 5 {
		covKM = 5.0
	}
	if handMin <= 0 {
		handMin = 15
	}
	fnJSON, _ := json.Marshal(fn)

	_, err := s.DB.Exec(`
		INSERT INTO locations (id, name, latitude, longitude, coverage_km, handling_minutes, active, functions)
		VALUES ($1, $2, $3, $4, $5, $6, $7, $8::jsonb)
	`, locID, name, coord.Latitude, coord.Longitude, covKM, handMin, active, string(fnJSON))
	if err != nil {
		return nil, err
	}

	_ = s.ServiceabilityService.PublishSnapshot()

	return &models.Location{
		LocationID:      locID,
		Name:            name,
		Coordinate:      coord,
		CoverageKM:      covKM,
		HandlingMinutes: handMin,
		Active:          active,
		Functions:       fn,
	}, nil
}

func (s *OperationsService) UpdateLocation(locID string, name string, coord models.Coordinate, covKM *float64, handMin *int, fn *models.LocationFunctionStates) (*models.Location, error) {
	covVal := 5.0
	if covKM != nil {
		covVal = *covKM
	}
	handVal := 15
	if handMin != nil {
		handVal = *handMin
	}

	var fnJSON []byte
	if fn != nil {
		fnJSON, _ = json.Marshal(fn)
	} else {
		fnJSON = []byte(`{"collection_point":true,"transfer_point":true,"hub":false,"laboratory":false}`)
	}

	_, err := s.DB.Exec(`
		UPDATE locations
		SET name = $1, latitude = $2, longitude = $3, coverage_km = $4, handling_minutes = $5, functions = $6::jsonb, updated_at = NOW()
		WHERE id = $7
	`, name, coord.Latitude, coord.Longitude, covVal, handVal, string(fnJSON), locID)
	if err != nil {
		return nil, err
	}

	_ = s.ServiceabilityService.PublishSnapshot()

	var fnStates models.LocationFunctionStates
	_ = json.Unmarshal(fnJSON, &fnStates)

	return &models.Location{
		LocationID:      locID,
		Name:            name,
		Coordinate:      coord,
		CoverageKM:      covVal,
		HandlingMinutes: handVal,
		Active:          true,
		Functions:       fnStates,
	}, nil
}

func (s *OperationsService) SetLocationStatus(locID string, active bool) error {
	res, err := s.DB.Exec(`UPDATE locations SET active = $1, updated_at = NOW() WHERE id = $2`, active, locID)
	if err != nil {
		return err
	}
	if rows, _ := res.RowsAffected(); rows == 0 {
		return errors.New("not_found")
	}
	_ = s.ServiceabilityService.PublishSnapshot()
	return nil
}

func (s *OperationsService) SetLocationFunctionStatus(locID string, function string, active bool) (*models.LocationFunctionStates, error) {
	var fnRaw []byte
	err := s.DB.QueryRow(`SELECT functions FROM locations WHERE id = $1`, locID).Scan(&fnRaw)
	if err != nil {
		return nil, errors.New("not_found")
	}

	var fn models.LocationFunctionStates
	_ = json.Unmarshal(fnRaw, &fn)

	switch function {
	case "collection_point":
		fn.CollectionPoint = active
	case "transfer_point":
		fn.TransferPoint = active
	case "hub":
		fn.Hub = active
	case "laboratory":
		fn.Laboratory = active
	default:
		return nil, errors.New("invalid_location_function")
	}

	newFnJSON, _ := json.Marshal(fn)
	_, err = s.DB.Exec(`UPDATE locations SET functions = $1::jsonb, updated_at = NOW() WHERE id = $2`, string(newFnJSON), locID)
	if err != nil {
		return nil, err
	}

	_ = s.ServiceabilityService.PublishSnapshot()
	return &fn, nil
}

