)

func GetUserFromContext(ctx context.Context) *services.AuthUser {
	if val := ctx.Value(UserContextKey); val != nil {
		if u, ok := val.(*services.AuthUser); ok {
			return u
		}
	}
	return nil
}

func JSON(w http.ResponseWriter, status int, data interface{}) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(map[string]interface{}{
		"data": data,
	})
}

func Error(w http.ResponseWriter, status int, errStr, code string) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(models.ErrorEnvelope{
		Error: errStr,
		Code:  code,
	})
}

func CheckIdempotency(db *sql.DB, key string) (int, []byte, bool) {
	if key == "" {
		return 0, nil, false
	}
	var code int
	var bodyRaw []byte
	err := db.QueryRow(`SELECT response_code, response_body FROM idempotency_keys WHERE key = $1`, key).Scan(&code, &bodyRaw)
	if err == nil {
		return code, bodyRaw, true
	}
	return 0, nil, false
}

func SaveIdempotency(db *sql.DB, key, op string, code int, data interface{}) {
	if key == "" {
		return
	}
	bodyJSON, err := json.Marshal(map[string]interface{}{"data": data})
	if err != nil {
		return
	}
	_, _ = db.Exec(`
		INSERT INTO idempotency_keys (key, operation, request_hash, response_code, response_body)
		VALUES ($1, $2, '', $3, $4::jsonb)
		ON CONFLICT (key) DO NOTHING
	`, key, op, code, string(bodyJSON))
}

func RequireAuth(authService *services.AuthService, next http.HandlerFunc) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		authHeader := r.Header.Get("Authorization")
		var token string
		if strings.HasPrefix(authHeader, "Bearer ") {
			token = strings.TrimPrefix(authHeader, "Bearer ")
		} else {
			token = r.URL.Query().Get("token")
		}

		if token == "" {
			Error(w, http.StatusUnauthorized, "Missing authentication token", "unauthorized")
			return
		}

		user, err := authService.ValidateSession(token)
		if err != nil {
			Error(w, http.StatusUnauthorized, "Invalid or expired session", "unauthorized")
			return
		}

		ctx := context.WithValue(r.Context(), UserContextKey, user)
		next.ServeHTTP(w, r.WithContext(ctx))
	}
}

