package handlers

import (
	"database/sql"
	"encoding/json"
	"errors"
	"labsystem/internal/models"
	"labsystem/internal/services"
	"net/http"
	"strings"
	"time"

	"github.com/go-chi/chi/v5"
)

type AuthHandler struct {
	DB           *sql.DB
	AuthService  *services.AuthService
	OpsService   *services.OperationsService
	AuditService *services.AuditService
}

func NewAuthHandler(db *sql.DB, auth *services.AuthService, ops *services.OperationsService, audit *services.AuditService) *AuthHandler {
	return &AuthHandler{
		DB:           db,
		AuthService:  auth,
		OpsService:   ops,
		AuditService: audit,
	}
}

func (h *AuthHandler) AuthenticateUser(w http.ResponseWriter, r *http.Request) {
	var req struct {
		Username string `json:"username"`
		Password string `json:"password"`
	}

	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		Error(w, http.StatusBadRequest, "Invalid JSON payload", "invalid_json")
		return
	}

	if req.Username == "" || req.Password == "" {
		Error(w, http.StatusUnauthorized, "Invalid credentials", "invalid_credentials")
		return
	}

	token, user, err := h.AuthService.Authenticate(req.Username, req.Password)
	if err != nil {
		if errors.Is(err, services.ErrInvalidCredentials) {
			Error(w, http.StatusUnauthorized, "Invalid username or password", "invalid_credentials")
			return
		}
		Error(w, http.StatusInternalServerError, "Authentication failed", "internal_error")
		return
	}

	JSON(w, http.StatusOK, map[string]interface{}{
		"sessionToken": token,
		"userId":       user.ID,
		"roles":        user.Roles,
		"activeRole":   user.ActiveRole,
	})
}

func (h *AuthHandler) SelectActiveRole(w http.ResponseWriter, r *http.Request) {
	var req struct {
		Role string `json:"role"`
	}

	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		Error(w, http.StatusBadRequest, "Invalid JSON payload", "invalid_json")
		return
	}

	if req.Role == "" {
		Error(w, http.StatusBadRequest, "Role is required", "invalid_role")
		return
	}

	authHeader := r.Header.Get("Authorization")
	token := strings.TrimPrefix(authHeader, "Bearer ")

	activeRole, roles, err := h.AuthService.SelectActiveRole(token, req.Role)
	if err != nil {
		if errors.Is(err, services.ErrRoleNotHeld) {
			Error(w, http.StatusForbidden, "Role not held by user", "role_not_held")
			return
		}
		if errors.Is(err, services.ErrUnauthorized) {
			Error(w, http.StatusUnauthorized, "Unauthorized", "unauthorized")
			return
		}
		Error(w, http.StatusInternalServerError, "Failed to select active role", "internal_error")
		return
	}

	JSON(w, http.StatusOK, map[string]interface{}{
		"activeRole": activeRole,
		"roles":      roles,
	})
}

func (h *AuthHandler) CreateUser(w http.ResponseWriter, r *http.Request) {
	actor := GetUserFromContext(r.Context())
	if actor == nil || actor.ActiveRole != "administrator" {
		Error(w, http.StatusForbidden, "Administrator role required", "forbidden")
		return
	}

	var req struct {
		Username           string                 `json:"username"`
		InitialPassword    string                 `json:"initialPassword"`
		Email              *string                `json:"email"`
		FullName           *string                `json:"fullName"`
		Phone              *string                `json:"phone"`
		Roles              []string               `json:"roles"`
		Qualifications     []string               `json:"qualifications"`
		Certifications     []models.Certification `json:"certifications"`
		Active             bool                   `json:"active"`
		AssignedLocationID *string                `json:"assignedLocationId"`
	}

	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		Error(w, http.StatusBadRequest, "Invalid JSON payload", "invalid_json")
		return
	}

	if req.Username == "" || req.InitialPassword == "" || len(req.Roles) == 0 {
		Error(w, http.StatusBadRequest, "Missing required fields", "invalid_user")
		return
	}

	createdUser, err := h.AuthService.CreateUser(actor, req.Username, req.InitialPassword, req.Email, req.FullName, req.Phone, req.Roles, req.Qualifications, req.Certifications, req.Active, req.AssignedLocationID)
	if err != nil {
		if errors.Is(err, services.ErrUsernameExists) {
			Error(w, http.StatusConflict, "Username already exists", "username_exists")
			return
		}
		Error(w, http.StatusInternalServerError, err.Error(), "internal_error")
		return
	}

	JSON(w, http.StatusCreated, createdUser)
}

func (h *AuthHandler) UpdateUserAccess(w http.ResponseWriter, r *http.Request) {
	actor := GetUserFromContext(r.Context())
	if actor == nil || actor.ActiveRole != "administrator" {
		Error(w, http.StatusForbidden, "Administrator role required", "forbidden")
		return
	}

	var req struct {
		UserID             string                 `json:"userId"`
		Roles              []string               `json:"roles"`
		Qualifications     []string               `json:"qualifications"`
		Certifications     []models.Certification `json:"certifications"`
		Active             bool                   `json:"active"`
		AssignedLocationID *string                `json:"assignedLocationId"`
	}

	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		Error(w, http.StatusBadRequest, "Invalid JSON payload", "invalid_json")
		return
	}

	if req.UserID == "" {
		Error(w, http.StatusBadRequest, "User ID is required", "invalid_json")
		return
	}

	updatedUser, err := h.AuthService.UpdateUserAccess(actor, req.UserID, req.Roles, req.Qualifications, req.Certifications, req.Active, req.AssignedLocationID)
	if err != nil {
		if errors.Is(err, services.ErrUserNotFound) {
			Error(w, http.StatusNotFound, "User not found", "not_found")
			return
		}
		Error(w, http.StatusInternalServerError, err.Error(), "internal_error")
		return
	}

	JSON(w, http.StatusCreated, updatedUser)
}

func (h *AuthHandler) ReadUser(w http.ResponseWriter, r *http.Request) {
	userID := chi.URLParam(r, "userId")
	if userID == "" {
		Error(w, http.StatusNotFound, "User not found", "not_found")
		return
	}

	user, err := h.AuthService.GetUser(userID)
	if err != nil {
		if errors.Is(err, services.ErrUserNotFound) {
			Error(w, http.StatusNotFound, "User not found", "not_found")
			return
		}
		Error(w, http.StatusInternalServerError, err.Error(), "internal_error")
		return
	}

	JSON(w, http.StatusOK, user)
}

func (h *AuthHandler) ReadUIBootstrap(w http.ResponseWriter, r *http.Request) {
	actor := GetUserFromContext(r.Context())
	if actor == nil {
		Error(w, http.StatusUnauthorized, "Unauthorized", "unauthorized")
		return
	}

	fullName := actor.Username
	if actor.FullName != nil && *actor.FullName != "" {
		fullName = *actor.FullName
	}

	userObj := map[string]interface{}{
		"userId":                actor.ID,
		"username":              actor.Username,
		"fullName":              fullName,
		"roles":                 actor.Roles,
		"activeRole":            actor.ActiveRole,
		"roleSelectionRequired": false,
	}

	serverTime := models.FormatTime(time.Now().UTC())

	// Fetch requester samples if role is requester or admin
	var reqSamples []map[string]interface{}
	rows, err := h.DB.Query(`
		SELECT s.id, s.request_id, s.status, s.sealed, cr.origin_lat, cr.origin_lng, cr.delivery_deadline,
		       s.current_holder_id, s.active_journey_id, s.latest_lat, s.latest_lng, s.location_recorded_at
		FROM samples s
		JOIN collection_requests cr ON s.request_id = cr.id
		WHERE cr.requester_id = $1 OR $2 = 'administrator' OR $2 = 'dispatcher'
		ORDER BY s.created_at DESC
	`, actor.ID, actor.ActiveRole)

	if err == nil {
		defer rows.Close()
		for rows.Next() {
			var sID, reqID, status string
			var sealed bool
			var oLat, oLng float64
			var deadline time.Time
			var holder, jID sql.NullString
			var lLat, lLng sql.NullFloat64
			var locRecordedAt sql.NullTime

			if err := rows.Scan(&sID, &reqID, &status, &sealed, &oLat, &oLng, &deadline, &holder, &jID, &lLat, &lLng, &locRecordedAt); err == nil {
				isStale := true
				if locRecordedAt.Valid && locRecordedAt.Time.After(time.Now().UTC().Add(-10*time.Minute)) {
					isStale = false
				}
				sMap := map[string]interface{}{
					"sampleId":         sID,
					"requestId":        reqID,
					"status":           status,
					"sealed":           sealed,
					"origin":           models.Coordinate{Latitude: oLat, Longitude: oLng},
					"deliveryDeadline": models.FormatTime(deadline),
					"locationStale":    isStale,
				}
				if holder.Valid {
					sMap["currentHolderId"] = holder.String
				}
				if jID.Valid {
					sMap["activeJourneyId"] = jID.String
				}
				if lLat.Valid && lLng.Valid {
					sMap["latestLocation"] = models.Coordinate{Latitude: lLat.Float64, Longitude: lLng.Float64}
				}
				if locRecordedAt.Valid {
					sMap["locationRecordedAt"] = models.FormatTime(locRecordedAt.Time)
				}
				reqSamples = append(reqSamples, sMap)
			}
		}
	}
	if reqSamples == nil {
		reqSamples = []map[string]interface{}{}
	}

	data := map[string]interface{}{
		"user":             userObj,
		"serverTime":       serverTime,
		"requesterSamples": reqSamples,
	}

	if actor.ActiveRole == "administrator" || actor.ActiveRole == "dispatcher" {
		ops, err := h.OpsService.GetOperationsState()
		if err == nil {
			data["operations"] = ops
		}
	}

	JSON(w, http.StatusOK, data)
}

