	reqAt, err := time.Parse(time.RFC3339, req.RequestedAt)
	if err != nil {
		Error(w, http.StatusBadRequest, "Invalid requestedAt format", "invalid_time")
		return
	}

	dl, err := time.Parse(time.RFC3339, req.DeliveryDeadline)
	if err != nil {
		Error(w, http.StatusBadRequest, "Invalid deliveryDeadline format", "invalid_deadline")
		return
	}

	if dl.Before(reqAt) {
		Error(w, http.StatusBadRequest, "Delivery deadline cannot be before requested time", "invalid_deadline")
		return
	}

	var earCol, latCol *time.Time
	if req.EarliestCollectionAt != nil && *req.EarliestCollectionAt != "" {
		if t, err := time.Parse(time.RFC3339, *req.EarliestCollectionAt); err == nil {
			earCol = &t
		}
	}
	if req.LatestCollectionAt != nil && *req.LatestCollectionAt != "" {
		if t, err := time.Parse(time.RFC3339, *req.LatestCollectionAt); err == nil {
			latCol = &t
		}
	}

	if earCol != nil && latCol != nil && latCol.Before(*earCol) {
		Error(w, http.StatusBadRequest, "Latest collection cannot be before earliest collection", "invalid_collection_window")
		return
	}

	originType := "home"
	if req.OriginType != "" {
		originType = req.OriginType
	}

	res, err := h.ServiceabilityService.Check(req.Origin, originType, req.OriginNodeID, req.SampleTypeID, reqAt, dl, earCol, latCol)
	if err != nil {
		Error(w, http.StatusInternalServerError, err.Error(), "internal_error")
		return
	}

	data := map[string]interface{}{
		"serviceable":           res.Serviceable,
		"reason":                res.Reason,
		"serviceabilityVersion": res.ServiceabilityVersion,
	}
	if res.TargetLaboratoryID != nil {
		data["targetLaboratoryId"] = *res.TargetLaboratoryID
	}
	if res.EstimatedArrivalAt != nil {
		data["estimatedArrivalAt"] = *res.EstimatedArrivalAt
	}

	JSON(w, http.StatusOK, data)
}

func (h *ServiceabilityHandler) ReadServiceabilitySnapshot(w http.ResponseWriter, r *http.Request) {
	snapshot, err := h.ServiceabilityService.GetLatestSnapshot()
	if err != nil {
		Error(w, http.StatusInternalServerError, err.Error(), "internal_error")
		return
	}

	JSON(w, http.StatusOK, snapshot)
}

