package handlers

import (
	"database/sql"
	"encoding/json"
	"errors"
	"labsystem/internal/models"
	"labsystem/internal/services"
	"net/http"
	"time"

	"github.com/go-chi/chi/v5"
	"github.com/lib/pq"
)

type RequestsSamplesHandler struct {
	DB           *sql.DB
	JourneyService *services.JourneyService
	OpsService     *services.OperationsService
	AuditService   *services.AuditService
}

func NewRequestsSamplesHandler(db *sql.DB, js *services.JourneyService, ops *services.OperationsService, audit *services.AuditService) *RequestsSamplesHandler {
	return &RequestsSamplesHandler{
		DB:             db,
		JourneyService: js,
		OpsService:     ops,
		AuditService:   audit,
	}
}

func (h *RequestsSamplesHandler) CreateCollectionRequest(w http.ResponseWriter, r *http.Request) {
	actor := GetUserFromContext(r.Context())
	if actor == nil {
		Error(w, http.StatusUnauthorized, "Unauthorized", "unauthorized")
		return
	}

	var req struct {
		RequesterID             *string           `json:"requesterId"`
		Origin                  models.Coordinate `json:"origin"`
		OriginType              string            `json:"originType"`
		OriginNodeID            *string           `json:"originNodeId"`
		RequestedAt             string            `json:"requestedAt"`
		DeliveryDeadline        string            `json:"deliveryDeadline"`
		EarliestCollectionAt    *string           `json:"earliestCollectionAt"`
		LatestCollectionAt      *string           `json:"latestCollectionAt"`
		SampleTypeID            string            `json:"sampleTypeId"`
		ContainerType           string            `json:"containerType"`
		TemperatureMinC         float64           `json:"temperatureMinC"`
		TemperatureMaxC         float64           `json:"temperatureMaxC"`
		IncompatibleSampleTypes []string          `json:"incompatibleSampleTypes"`
		IdempotencyKey          string            `json:"idempotencyKey"`
	}

	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		Error(w, http.StatusBadRequest, "Invalid JSON payload", "invalid_json")
		return
	}

	if req.IdempotencyKey != "" {
		if code, body, found := CheckIdempotency(h.DB, req.IdempotencyKey); found {
			w.Header().Set("Content-Type", "application/json")
			w.WriteHeader(code)
			w.Write(body)
			return
		}
	}

	if req.SampleTypeID == "" || req.RequestedAt == "" || req.DeliveryDeadline == "" {
		Error(w, http.StatusBadRequest, "Missing required fields", "invalid_json")
		return
	}

	reqAt, err := time.Parse(time.RFC3339, req.RequestedAt)
	if err != nil {
		Error(w, http.StatusBadRequest, "Invalid requestedAt format", "invalid_time")
		return
	}

	dl, err := time.Parse(time.RFC3339, req.DeliveryDeadline)
	if err != nil {
		Error(w, http.StatusBadRequest, "Invalid deliveryDeadline format", "invalid_deadline")
		return
	}

	if dl.Before(reqAt) {
		Error(w, http.StatusBadRequest, "Delivery deadline cannot be before requested time", "invalid_deadline")
		return
	}

	var earCol, latCol *time.Time
	if req.EarliestCollectionAt != nil && *req.EarliestCollectionAt != "" {
		if t, err := time.Parse(time.RFC3339, *req.EarliestCollectionAt); err == nil {
			earCol = &t
		}
	}
	if req.LatestCollectionAt != nil && *req.LatestCollectionAt != "" {
		if t, err := time.Parse(time.RFC3339, *req.LatestCollectionAt); err == nil {
			latCol = &t
		}
	}

	if earCol != nil && latCol != nil && latCol.Before(*earCol) {
		Error(w, http.StatusBadRequest, "Latest collection cannot be before earliest collection", "invalid_collection_window")
		return
	}

	requesterID := actor.ID
	if req.RequesterID != nil && *req.RequesterID != "" && (actor.ActiveRole == "administrator" || actor.ActiveRole == "dispatcher") {
		requesterID = *req.RequesterID
	}

	originType := "home"
	if req.OriginType != "" {
		originType = req.OriginType
	}

	res, err := h.JourneyService.CreateRequest(services.CreateRequestParams{
		RequesterID:             requesterID,
		Origin:                  req.Origin,
		OriginType:              originType,
		OriginNodeID:            req.OriginNodeID,
		RequestedAt:             reqAt,
		DeliveryDeadline:        dl,
		EarliestCollectionAt:    earCol,
		LatestCollectionAt:      latCol,
		SampleTypeID:            req.SampleTypeID,
		ContainerType:           req.ContainerType,
		TemperatureMinC:         req.TemperatureMinC,
		TemperatureMaxC:         req.TemperatureMaxC,
		IncompatibleSampleTypes: req.IncompatibleSampleTypes,
		AlreadySealed:           false,
	})

	if err != nil {
		if errors.Is(err, services.ErrInvalidOrigin) {
			Error(w, http.StatusBadRequest, "Origin is outside coverage", "invalid_origin")
			return
		}
		if errors.Is(err, services.ErrDeadlineExceeded) {
			Error(w, http.StatusConflict, "Sample cannot meet delivery deadline", "deadline_exceeded")
			return
		}
		if errors.Is(err, services.ErrCapacityExhausted) {
			Error(w, http.StatusConflict, "Insufficient capacity on route", "capacity_exhausted")
			return
		}
		if errors.Is(err, services.ErrNoValidRoute) {
			Error(w, http.StatusConflict, "No valid route available", "no_valid_route")
			return
		}
		Error(w, http.StatusBadRequest, err.Error(), "invalid_json")
		return
	}

	SaveIdempotency(h.DB, req.IdempotencyKey, "create_collection_request", http.StatusCreated, res)
	JSON(w, http.StatusCreated, res)
}

func (h *RequestsSamplesHandler) IngestPresealedSample(w http.ResponseWriter, r *http.Request) {
	actor := GetUserFromContext(r.Context())
	if actor == nil {
		Error(w, http.StatusUnauthorized, "Unauthorized", "unauthorized")
		return
	}

	var req struct {
		RequesterID             *string           `json:"requesterId"`
		Origin                  models.Coordinate `json:"origin"`
		OriginType              string            `json:"originType"`
		OriginNodeID            *string           `json:"originNodeId"`
		RequestedAt             string            `json:"requestedAt"`
		DeliveryDeadline        string            `json:"deliveryDeadline"`
		EarliestCollectionAt    *string           `json:"earliestCollectionAt"`
		LatestCollectionAt      *string           `json:"latestCollectionAt"`
		SampleTypeID            string            `json:"sampleTypeId"`
		ContainerType           string            `json:"containerType"`
		TemperatureMinC         float64           `json:"temperatureMinC"`
		TemperatureMaxC         float64           `json:"temperatureMaxC"`
		IncompatibleSampleTypes []string          `json:"incompatibleSampleTypes"`
		IdempotencyKey          string            `json:"idempotencyKey"`
	}

	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		Error(w, http.StatusBadRequest, "Invalid JSON payload", "invalid_json")
		return
	}

	if req.IdempotencyKey != "" {
		if code, body, found := CheckIdempotency(h.DB, req.IdempotencyKey); found {
			w.Header().Set("Content-Type", "application/json")
			w.WriteHeader(code)
			w.Write(body)
			return
		}
	}

	if req.OriginType == "home" {
		Error(w, http.StatusBadRequest, "Pre-sealed sample origin cannot be a home", "invalid_origin_type")
		return
	}

	originType := "clinic"
	if req.OriginType != "" {
		originType = req.OriginType
	}

	reqAt, _ := time.Parse(time.RFC3339, req.RequestedAt)
	dl, _ := time.Parse(time.RFC3339, req.DeliveryDeadline)
	var earCol, latCol *time.Time
	if req.EarliestCollectionAt != nil && *req.EarliestCollectionAt != "" {
		if t, err := time.Parse(time.RFC3339, *req.EarliestCollectionAt); err == nil {
			earCol = &t
		}
	}
	if req.LatestCollectionAt != nil && *req.LatestCollectionAt != "" {
		if t, err := time.Parse(time.RFC3339, *req.LatestCollectionAt); err == nil {
			latCol = &t
		}
	}

	requesterID := actor.ID
	if req.RequesterID != nil && *req.RequesterID != "" {
		requesterID = *req.RequesterID
	}

	holderID := actor.ID

	res, err := h.JourneyService.CreateRequest(services.CreateRequestParams{
		RequesterID:             requesterID,
		Origin:                  req.Origin,
		OriginType:              originType,
		OriginNodeID:            req.OriginNodeID,
		RequestedAt:             reqAt,
		DeliveryDeadline:        dl,
		EarliestCollectionAt:    earCol,
		LatestCollectionAt:      latCol,
		SampleTypeID:            req.SampleTypeID,
		ContainerType:           req.ContainerType,
		TemperatureMinC:         req.TemperatureMinC,
		TemperatureMaxC:         req.TemperatureMaxC,
		IncompatibleSampleTypes: req.IncompatibleSampleTypes,
		AlreadySealed:           true,
		CurrentHolderID:         &holderID,
	})

	if err != nil {
		if errors.Is(err, services.ErrNoValidRoute) {
			Error(w, http.StatusConflict, "No valid route available", "no_valid_route")
			return
		}
		Error(w, http.StatusBadRequest, err.Error(), "invalid_json")
		return
	}

	SaveIdempotency(h.DB, req.IdempotencyKey, "ingest_presealed_sample", http.StatusCreated, res)
	JSON(w, http.StatusCreated, res)
}

func (h *RequestsSamplesHandler) CollectAndSealSample(w http.ResponseWriter, r *http.Request) {
	actor := GetUserFromContext(r.Context())
	if actor == nil {
		Error(w, http.StatusUnauthorized, "Unauthorized", "unauthorized")
		return
	}

	var req struct {
		SampleID             string  `json:"sampleId"`
		AssignmentID         string  `json:"assignmentId"`
		CollectedAt          string  `json:"collectedAt"`
		ContainerType        string  `json:"containerType"`
		ObservedTemperatureC float64 `json:"observedTemperatureC"`
		IdempotencyKey       string  `json:"idempotencyKey"`
	}

	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		Error(w, http.StatusBadRequest, "Invalid JSON payload", "invalid_json")
		return
	}

	if req.IdempotencyKey != "" {
		if code, body, found := CheckIdempotency(h.DB, req.IdempotencyKey); found {
			w.Header().Set("Content-Type", "application/json")
			w.WriteHeader(code)
			w.Write(body)
			return
		}
	}

	if req.SampleID == "" || req.AssignmentID == "" || req.CollectedAt == "" {
		Error(w, http.StatusBadRequest, "Missing required fields", "invalid_json")
		return
	}

	colAt, err := time.Parse(time.RFC3339, req.CollectedAt)
	if err != nil {
		Error(w, http.StatusBadRequest, "Invalid collectedAt format", "invalid_time")
		return
	}

	compliant, err := h.JourneyService.CollectAndSeal(req.SampleID, req.AssignmentID, actor.ID, colAt, req.ContainerType, req.ObservedTemperatureC)
	if err != nil {
		Error(w, http.StatusInternalServerError, err.Error(), "internal_error")
		return
	}

	status := "sealed"
	if !compliant {
		status = "exception"
	}

	res := map[string]interface{}{
		"sampleId":          req.SampleID,
		"status":            status,
		"currentHolderId":   actor.ID,
		"sealedAt":          models.FormatTime(colAt),
		"handlingCompliant": compliant,
	}

	SaveIdempotency(h.DB, req.IdempotencyKey, "collect_and_seal_sample", http.StatusCreated, res)
	JSON(w, http.StatusCreated, res)
}

func (h *RequestsSamplesHandler) ReadSampleState(w http.ResponseWriter, r *http.Request) {
	sampleID := chi.URLParam(r, "sampleId")
	if sampleID == "" {
		Error(w, http.StatusNotFound, "Sample not found", "not_found")
		return
	}

	var state models.SampleState
	var oLat, oLng float64
	var reqAt, dl time.Time
	var incomp pq.StringArray
	var holder, targetLab, jID sql.NullString
	var lLat, lLng sql.NullFloat64
	var locRecordedAt sql.NullTime

	err := h.DB.QueryRow(`
		SELECT s.id, s.request_id, cr.requester_id, cr.origin_lat, cr.origin_lng, cr.origin_type,
		       cr.requested_at, cr.delivery_deadline, s.sample_type_id, cr.container_type,
		       cr.temperature_min_c, cr.temperature_max_c, cr.incompatible_sample_types,
		       cr.serviceability, s.status, s.active_journey_id, s.target_laboratory_id,
		       s.latest_lat, s.latest_lng, s.location_recorded_at
		FROM samples s
		JOIN collection_requests cr ON s.request_id = cr.id
		WHERE s.id = $1
	`, sampleID).Scan(
		&state.SampleID, &state.RequestID, &state.RequesterID, &oLat, &oLng, &state.OriginType,
		&reqAt, &dl, &state.SampleTypeID, &state.ContainerType,
		&state.TemperatureMinC, &state.TemperatureMaxC, &incomp,
		&state.Serviceability, &holder, &jID, &targetLab,
		&lLat, &lLng, &locRecordedAt,
	)

	if err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			Error(w, http.StatusNotFound, "Sample not found", "not_found")
			return
		}
		Error(w, http.StatusInternalServerError, err.Error(), "internal_error")
		return
	}

	state.Origin = models.Coordinate{Latitude: oLat, Longitude: oLng}
	state.RequestedAt = models.FormatTime(reqAt)
	state.DeliveryDeadline = models.FormatTime(dl)
	state.IncompatibleSampleTypes = []string(incomp)
	if incomp == nil {
		state.IncompatibleSampleTypes = []string{}
	}

	var curStatus string
	_ = h.DB.QueryRow(`SELECT status FROM samples WHERE id = $1`, sampleID).Scan(&curStatus)
	state.State = map[string]interface{}{"status": curStatus}

	if jID.Valid {
		state.ActiveJourneyID = &jID.String
	}
	if targetLab.Valid {
		state.TargetLaboratoryID = &targetLab.String
	}
	if lLat.Valid && lLng.Valid {
		state.LatestLocation = &models.Coordinate{Latitude: lLat.Float64, Longitude: lLng.Float64}
	}
	if locRecordedAt.Valid {
		tStr := models.FormatTime(locRecordedAt.Time)
		state.LocationRecordedAt = &tStr
		state.LocationStale = locRecordedAt.Time.Before(time.Now().UTC().Add(-10 * time.Minute))
	} else {
		state.LocationStale = true
	}

	// Fetch active assignments
	var assignIDs []string
	rows, _ := h.DB.Query(`SELECT id FROM assignments WHERE sample_id = $1 AND status IN ('offered', 'accepted', 'in_progress')`, sampleID)
	if rows != nil {
		for rows.Next() {
			var aID string
			if err := rows.Scan(&aID); err == nil {
				assignIDs = append(assignIDs, aID)
			}
		}
		rows.Close()
	}
	if assignIDs == nil {
		assignIDs = []string{}
	}
	state.ActiveAssignmentIDs = assignIDs

	// Fetch timeline
	timeline, _ := h.AuditService.GetTimelineForEntity("sample", sampleID)
	state.Timeline = timeline

	JSON(w, http.StatusOK, state)
}

func (h *RequestsSamplesHandler) ReadSampleLifecycle(w http.ResponseWriter, r *http.Request) {
	var req struct {
		SampleID string `json:"sampleId"`
	}

	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		Error(w, http.StatusBadRequest, "Invalid JSON payload", "invalid_json")
		return
	}

	var lc models.SampleLifecycle
	var holder, targetLab, jID sql.NullString
	var excRaw []byte
	var lLat, lLng sql.NullFloat64
	var locRecordedAt sql.NullTime
	var compLegs, replPlans pq.StringArray

	err := h.DB.QueryRow(`
		SELECT id, status, sealed, completed_leg_ids, active_replacement_plan_ids,
		       active_journey_id, current_holder_id, received_laboratory_id, exception,
		       latest_lat, latest_lng, location_recorded_at
		FROM samples
		WHERE id = $1
	`, req.SampleID).Scan(
		&lc.SampleID, &lc.Status, &lc.Sealed, &compLegs, &replPlans,
		&jID, &holder, &targetLab, &excRaw,
		&lLat, &lLng, &locRecordedAt,
	)

	if err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			Error(w, http.StatusNotFound, "Sample not found", "not_found")
			return
		}
		Error(w, http.StatusInternalServerError, err.Error(), "internal_error")
		return
	}

	lc.CompletedLegIDs = []string(compLegs)
	if lc.CompletedLegIDs == nil {
		lc.CompletedLegIDs = []string{}
	}
	lc.ActiveReplacementPlanIDs = []string(replPlans)
	if lc.ActiveReplacementPlanIDs == nil {
		lc.ActiveReplacementPlanIDs = []string{}
	}

	if jID.Valid {
		lc.ActiveJourneyID = &jID.String
	}
	if holder.Valid {
		lc.CurrentHolderID = &holder.String
	}
	if targetLab.Valid {
		lc.ReceivedLaboratoryID = &targetLab.String
	}
	if len(excRaw) > 0 {
		_ = json.Unmarshal(excRaw, &lc.Exception)
	}
	if lLat.Valid && lLng.Valid {
		lc.LatestLocation = &models.Coordinate{Latitude: lLat.Float64, Longitude: lLng.Float64}
	}
	if locRecordedAt.Valid {
		tStr := models.FormatTime(locRecordedAt.Time)
		lc.LocationRecordedAt = &tStr
		lc.LocationStale = locRecordedAt.Time.Before(time.Now().UTC().Add(-10 * time.Minute))
	} else {
		lc.LocationStale = true
	}

	// Pending handoff check
	var pID, pSender, pRec string
	var pInitAt time.Time
	err = h.DB.QueryRow(`
		SELECT id, sender_id, receiver_id, initiated_at
		FROM handoffs
		WHERE sample_id = $1 AND status = 'pending'
		LIMIT 1
	`, req.SampleID).Scan(&pID, &pSender, &pRec, &pInitAt)
	if err == nil {
		lc.PendingHandoffID = &pID
		lc.PendingHandoff = map[string]interface{}{
			"handoffId":   pID,
			"senderId":    pSender,
			"receiverId":  pRec,
			"initiatedAt": models.FormatTime(pInitAt),
		}
	}

	timeline, _ := h.AuditService.GetTimelineForEntity("sample", req.SampleID)
	lc.Timeline = timeline

	JSON(w, http.StatusOK, lc)
}

func (h *RequestsSamplesHandler) RecordHandlingCheckpoint(w http.ResponseWriter, r *http.Request) {
	actor := GetUserFromContext(r.Context())
	if actor == nil {
		Error(w, http.StatusUnauthorized, "Unauthorized", "unauthorized")
		return
	}

	var req struct {
		SampleID             string  `json:"sampleId"`
		AssignmentID         string  `json:"assignmentId"`
		LocationID           *string `json:"locationId"`
		ContainerType        string  `json:"containerType"`
		ObservedTemperatureC float64 `json:"observedTemperatureC"`
		RecordedAt           string  `json:"recordedAt"`
		IdempotencyKey       string  `json:"idempotencyKey"`
	}

	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		Error(w, http.StatusBadRequest, "Invalid JSON payload", "invalid_json")
		return
	}

	if req.IdempotencyKey != "" {
		if code, body, found := CheckIdempotency(h.DB, req.IdempotencyKey); found {
			w.Header().Set("Content-Type", "application/json")
			w.WriteHeader(code)
			w.Write(body)
			return
		}
	}

	if req.SampleID == "" || req.AssignmentID == "" || req.RecordedAt == "" {
		Error(w, http.StatusBadRequest, "Missing required fields", "invalid_json")
		return
	}

	recAt, err := time.Parse(time.RFC3339, req.RecordedAt)
	if err != nil {
		Error(w, http.StatusBadRequest, "Invalid recordedAt format", "invalid_time")
		return
	}

	chkID, compliant, sampleStatus, err := h.OpsService.RecordCheckpoint(req.SampleID, req.AssignmentID, req.LocationID, req.ContainerType, req.ObservedTemperatureC, recAt, actor.ID)
	if err != nil {
		Error(w, http.StatusInternalServerError, err.Error(), "internal_error")
		return
	}

	res := map[string]interface{}{
		"checkpointId": chkID,
		"sampleId":     req.SampleID,
		"compliant":    compliant,
		"sampleStatus": sampleStatus,
	}

	SaveIdempotency(h.DB, req.IdempotencyKey, "record_handling_checkpoint", http.StatusCreated, res)
	JSON(w, http.StatusCreated, res)
}

