	}

	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		Error(w, http.StatusBadRequest, "Invalid JSON payload", "invalid_json")
		return
	}

	if req.IdempotencyKey != "" {
		if code, body, found := CheckIdempotency(h.DB, req.IdempotencyKey); found {
			w.Header().Set("Content-Type", "application/json")
			w.WriteHeader(code)
			w.Write(body)
			return
		}
	}

	if req.SampleTypeID == "" || req.RequestedAt == "" || req.DeliveryDeadline == "" {
		Error(w, http.StatusBadRequest, "Missing required fields", "invalid_json")
		return
	}

	reqAt, err := time.Parse(time.RFC3339, req.RequestedAt)
	if err != nil {
		Error(w, http.StatusBadRequest, "Invalid requestedAt format", "invalid_time")
		return
	}

	dl, err := time.Parse(time.RFC3339, req.DeliveryDeadline)
	if err != nil {
		Error(w, http.StatusBadRequest, "Invalid deliveryDeadline format", "invalid_deadline")
		return
	}

	if dl.Before(reqAt) {
		Error(w, http.StatusBadRequest, "Delivery deadline cannot be before requested time", "invalid_deadline")
		return
	}

	var earCol, latCol *time.Time
	if req.EarliestCollectionAt != nil && *req.EarliestCollectionAt != "" {
		if t, err := time.Parse(time.RFC3339, *req.EarliestCollectionAt); err == nil {
			earCol = &t
		}
	}
	if req.LatestCollectionAt != nil && *req.LatestCollectionAt != "" {
		if t, err := time.Parse(time.RFC3339, *req.LatestCollectionAt); err == nil {
			latCol = &t
		}
	}

	if earCol != nil && latCol != nil && latCol.Before(*earCol) {
		Error(w, http.StatusBadRequest, "Latest collection cannot be before earliest collection", "invalid_collection_window")
		return
	}

	requesterID := actor.ID
	if req.RequesterID != nil && *req.RequesterID != "" && (actor.ActiveRole == "administrator" || actor.ActiveRole == "dispatcher") {
		requesterID = *req.RequesterID
	}

	originType := "home"
	if req.OriginType != "" {
		originType = req.OriginType
	}

	res, err := h.JourneyService.CreateRequest(services.CreateRequestParams{
		RequesterID:             requesterID,
		Origin:                  req.Origin,
		OriginType:              originType,
		OriginNodeID:            req.OriginNodeID,
