			Error(w, http.StatusConflict, "Sample cannot meet delivery deadline", "deadline_exceeded")
			return
		}
		if errors.Is(err, services.ErrCapacityExhausted) {
			Error(w, http.StatusConflict, "Insufficient capacity on route", "capacity_exhausted")
			return
		}
		if errors.Is(err, services.ErrNoValidRoute) {
			Error(w, http.StatusConflict, "No valid route available", "no_valid_route")
			return
		}
		Error(w, http.StatusBadRequest, err.Error(), "invalid_json")
		return
	}

	SaveIdempotency(h.DB, req.IdempotencyKey, "create_collection_request", http.StatusCreated, res)
	JSON(w, http.StatusCreated, res)
}

func (h *RequestsSamplesHandler) IngestPresealedSample(w http.ResponseWriter, r *http.Request) {
	actor := GetUserFromContext(r.Context())
	if actor == nil {
		Error(w, http.StatusUnauthorized, "Unauthorized", "unauthorized")
		return
	}

	var req struct {
		RequesterID             *string           `json:"requesterId"`
		Origin                  models.Coordinate `json:"origin"`
		OriginType              string            `json:"originType"`
		OriginNodeID            *string           `json:"originNodeId"`
		RequestedAt             string            `json:"requestedAt"`
		DeliveryDeadline        string            `json:"deliveryDeadline"`
		EarliestCollectionAt    *string           `json:"earliestCollectionAt"`
		LatestCollectionAt      *string           `json:"latestCollectionAt"`
		SampleTypeID            string            `json:"sampleTypeId"`
		ContainerType           string            `json:"containerType"`
		TemperatureMinC         float64           `json:"temperatureMinC"`
		TemperatureMaxC         float64           `json:"temperatureMaxC"`
		IncompatibleSampleTypes []string          `json:"incompatibleSampleTypes"`
		IdempotencyKey          string            `json:"idempotencyKey"`
	}

	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		Error(w, http.StatusBadRequest, "Invalid JSON payload", "invalid_json")
		return
	}

	if req.IdempotencyKey != "" {
		if code, body, found := CheckIdempotency(h.DB, req.IdempotencyKey); found {
			w.Header().Set("Content-Type", "application/json")
			w.WriteHeader(code)
			w.Write(body)
			return
		}
	}

	if req.OriginType == "home" {
		Error(w, http.StatusBadRequest, "Pre-sealed sample origin cannot be a home", "invalid_origin_type")
		return
	}

	originType := "clinic"
	if req.OriginType != "" {
		originType = req.OriginType
	}

	reqAt, _ := time.Parse(time.RFC3339, req.RequestedAt)
	dl, _ := time.Parse(time.RFC3339, req.DeliveryDeadline)
	var earCol, latCol *time.Time
	if req.EarliestCollectionAt != nil && *req.EarliestCollectionAt != "" {
		if t, err := time.Parse(time.RFC3339, *req.EarliestCollectionAt); err == nil {
			earCol = &t
		}
	}
	if req.LatestCollectionAt != nil && *req.LatestCollectionAt != "" {
		if t, err := time.Parse(time.RFC3339, *req.LatestCollectionAt); err == nil {
			latCol = &t
		}
	}

	requesterID := actor.ID
	if req.RequesterID != nil && *req.RequesterID != "" {
		requesterID = *req.RequesterID
	}

	holderID := actor.ID

	res, err := h.JourneyService.CreateRequest(services.CreateRequestParams{
		RequesterID:             requesterID,
		Origin:                  req.Origin,
		OriginType:              originType,
		OriginNodeID:            req.OriginNodeID,
		RequestedAt:             reqAt,
		DeliveryDeadline:        dl,
		EarliestCollectionAt:    earCol,
		LatestCollectionAt:      latCol,
		SampleTypeID:            req.SampleTypeID,
		ContainerType:           req.ContainerType,
		TemperatureMinC:         req.TemperatureMinC,
		TemperatureMaxC:         req.TemperatureMaxC,
		IncompatibleSampleTypes: req.IncompatibleSampleTypes,
		AlreadySealed:           true,
		CurrentHolderID:         &holderID,
	})

	if err != nil {
		if errors.Is(err, services.ErrNoValidRoute) {
			Error(w, http.StatusConflict, "No valid route available", "no_valid_route")
			return
		}
		Error(w, http.StatusBadRequest, err.Error(), "invalid_json")
		return
	}

	SaveIdempotency(h.DB, req.IdempotencyKey, "ingest_presealed_sample", http.StatusCreated, res)
	JSON(w, http.StatusCreated, res)
}

func (h *RequestsSamplesHandler) CollectAndSealSample(w http.ResponseWriter, r *http.Request) {
	actor := GetUserFromContext(r.Context())
	if actor == nil {
		Error(w, http.StatusUnauthorized, "Unauthorized", "unauthorized")
		return
	}

	var req struct {
		SampleID             string  `json:"sampleId"`
		AssignmentID         string  `json:"assignmentId"`
		CollectedAt          string  `json:"collectedAt"`
		ContainerType        string  `json:"containerType"`
		ObservedTemperatureC float64 `json:"observedTemperatureC"`
		IdempotencyKey       string  `json:"idempotencyKey"`
	}

	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		Error(w, http.StatusBadRequest, "Invalid JSON payload", "invalid_json")
		return
	}

	if req.IdempotencyKey != "" {
		if code, body, found := CheckIdempotency(h.DB, req.IdempotencyKey); found {
			w.Header().Set("Content-Type", "application/json")
			w.WriteHeader(code)
			w.Write(body)
			return
		}
	}

	if req.SampleID == "" || req.AssignmentID == "" || req.CollectedAt == "" {
		Error(w, http.StatusBadRequest, "Missing required fields", "invalid_json")
		return
	}

	colAt, err := time.Parse(time.RFC3339, req.CollectedAt)
	if err != nil {
		Error(w, http.StatusBadRequest, "Invalid collectedAt format", "invalid_time")
		return
	}

	compliant, err := h.JourneyService.CollectAndSeal(req.SampleID, req.AssignmentID, actor.ID, colAt, req.ContainerType, req.ObservedTemperatureC)
	if err != nil {
		Error(w, http.StatusInternalServerError, err.Error(), "internal_error")
