	}

	SaveIdempotency(h.DB, req.IdempotencyKey, "collect_and_seal_sample", http.StatusCreated, res)
	JSON(w, http.StatusCreated, res)
}

func (h *RequestsSamplesHandler) ReadSampleState(w http.ResponseWriter, r *http.Request) {
	sampleID := chi.URLParam(r, "sampleId")
	if sampleID == "" {
		Error(w, http.StatusNotFound, "Sample not found", "not_found")
		return
	}

	var state models.SampleState
	var oLat, oLng float64
	var reqAt, dl time.Time
	var incomp pq.StringArray
	var holder, targetLab, jID sql.NullString
	var lLat, lLng sql.NullFloat64
	var locRecordedAt sql.NullTime

	err := h.DB.QueryRow(`
		SELECT s.id, s.request_id, cr.requester_id, cr.origin_lat, cr.origin_lng, cr.origin_type,
		       cr.requested_at, cr.delivery_deadline, s.sample_type_id, cr.container_type,
		       cr.temperature_min_c, cr.temperature_max_c, cr.incompatible_sample_types,
		       cr.serviceability, s.status, s.active_journey_id, s.target_laboratory_id,
		       s.latest_lat, s.latest_lng, s.location_recorded_at
		FROM samples s
		JOIN collection_requests cr ON s.request_id = cr.id
		WHERE s.id = $1
	`, sampleID).Scan(
		&state.SampleID, &state.RequestID, &state.RequesterID, &oLat, &oLng, &state.OriginType,
		&reqAt, &dl, &state.SampleTypeID, &state.ContainerType,
		&state.TemperatureMinC, &state.TemperatureMaxC, &incomp,
		&state.Serviceability, &holder, &jID, &targetLab,
		&lLat, &lLng, &locRecordedAt,
	)

	if err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			Error(w, http.StatusNotFound, "Sample not found", "not_found")
			return
		}
		Error(w, http.StatusInternalServerError, err.Error(), "internal_error")
		return
	}

	state.Origin = models.Coordinate{Latitude: oLat, Longitude: oLng}
	state.RequestedAt = models.FormatTime(reqAt)
	state.DeliveryDeadline = models.FormatTime(dl)
	state.IncompatibleSampleTypes = []string(incomp)
	if incomp == nil {
		state.IncompatibleSampleTypes = []string{}
	}

	var curStatus string
	_ = h.DB.QueryRow(`SELECT status FROM samples WHERE id = $1`, sampleID).Scan(&curStatus)
	state.State = map[string]interface{}{"status": curStatus}

	if jID.Valid {
		state.ActiveJourneyID = &jID.String
	}
	if targetLab.Valid {
		state.TargetLaboratoryID = &targetLab.String
	}
	if lLat.Valid && lLng.Valid {
		state.LatestLocation = &models.Coordinate{Latitude: lLat.Float64, Longitude: lLng.Float64}
	}
	if locRecordedAt.Valid {
		tStr := models.FormatTime(locRecordedAt.Time)
		state.LocationRecordedAt = &tStr
		state.LocationStale = locRecordedAt.Time.Before(time.Now().UTC().Add(-10 * time.Minute))
	} else {
		state.LocationStale = true
	}

	// Fetch active assignments
	var assignIDs []string
	rows, _ := h.DB.Query(`SELECT id FROM assignments WHERE sample_id = $1 AND status IN ('offered', 'accepted', 'in_progress')`, sampleID)
	if rows != nil {
		for rows.Next() {
			var aID string
			if err := rows.Scan(&aID); err == nil {
				assignIDs = append(assignIDs, aID)
			}
		}
		rows.Close()
	}
	if assignIDs == nil {
		assignIDs = []string{}
	}
	state.ActiveAssignmentIDs = assignIDs

	// Fetch timeline
	timeline, _ := h.AuditService.GetTimelineForEntity("sample", sampleID)
	state.Timeline = timeline

	JSON(w, http.StatusOK, state)
}

func (h *RequestsSamplesHandler) ReadSampleLifecycle(w http.ResponseWriter, r *http.Request) {
	var req struct {
		SampleID string `json:"sampleId"`
	}

	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		Error(w, http.StatusBadRequest, "Invalid JSON payload", "invalid_json")
		return
	}

	var lc models.SampleLifecycle
	var holder, targetLab, jID sql.NullString
	var excRaw []byte
	var lLat, lLng sql.NullFloat64
	var locRecordedAt sql.NullTime
	var compLegs, replPlans pq.StringArray

	err := h.DB.QueryRow(`
		SELECT id, status, sealed, completed_leg_ids, active_replacement_plan_ids,
		       active_journey_id, current_holder_id, received_laboratory_id, exception,
		       latest_lat, latest_lng, location_recorded_at
		FROM samples
		WHERE id = $1
	`, req.SampleID).Scan(
		&lc.SampleID, &lc.Status, &lc.Sealed, &compLegs, &replPlans,
		&jID, &holder, &targetLab, &excRaw,
		&lLat, &lLng, &locRecordedAt,
	)

	if err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			Error(w, http.StatusNotFound, "Sample not found", "not_found")
			return
		}
		Error(w, http.StatusInternalServerError, err.Error(), "internal_error")
		return
	}

	lc.CompletedLegIDs = []string(compLegs)
	if lc.CompletedLegIDs == nil {
		lc.CompletedLegIDs = []string{}
	}
	lc.ActiveReplacementPlanIDs = []string(replPlans)
	if lc.ActiveReplacementPlanIDs == nil {
		lc.ActiveReplacementPlanIDs = []string{}
	}

	if jID.Valid {
		lc.ActiveJourneyID = &jID.String
	}
	if holder.Valid {
		lc.CurrentHolderID = &holder.String
	}
	if targetLab.Valid {
		lc.ReceivedLaboratoryID = &targetLab.String
	}
	if len(excRaw) > 0 {
		_ = json.Unmarshal(excRaw, &lc.Exception)
	}
	if lLat.Valid && lLng.Valid {
		lc.LatestLocation = &models.Coordinate{Latitude: lLat.Float64, Longitude: lLng.Float64}
	}
	if locRecordedAt.Valid {
		tStr := models.FormatTime(locRecordedAt.Time)
		lc.LocationRecordedAt = &tStr
		lc.LocationStale = locRecordedAt.Time.Before(time.Now().UTC().Add(-10 * time.Minute))
	} else {
		lc.LocationStale = true
	}

	// Pending handoff check
	var pID, pSender, pRec string
	var pInitAt time.Time
	err = h.DB.QueryRow(`
		SELECT id, sender_id, receiver_id, initiated_at
		FROM handoffs
		WHERE sample_id = $1 AND status = 'pending'
		LIMIT 1
	`, req.SampleID).Scan(&pID, &pSender, &pRec, &pInitAt)
	if err == nil {
		lc.PendingHandoffID = &pID
		lc.PendingHandoff = map[string]interface{}{
			"handoffId":   pID,
			"senderId":    pSender,
			"receiverId":  pRec,
			"initiatedAt": models.FormatTime(pInitAt),
		}
	}

	timeline, _ := h.AuditService.GetTimelineForEntity("sample", req.SampleID)
	lc.Timeline = timeline

	JSON(w, http.StatusOK, lc)
}

func (h *RequestsSamplesHandler) RecordHandlingCheckpoint(w http.ResponseWriter, r *http.Request) {
	actor := GetUserFromContext(r.Context())
	if actor == nil {
		Error(w, http.StatusUnauthorized, "Unauthorized", "unauthorized")
