		LocationID           *string `json:"locationId"`
		ContainerType        string  `json:"containerType"`
		ObservedTemperatureC float64 `json:"observedTemperatureC"`
		RecordedAt           string  `json:"recordedAt"`
		IdempotencyKey       string  `json:"idempotencyKey"`
	}

	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		Error(w, http.StatusBadRequest, "Invalid JSON payload", "invalid_json")
		return
	}

	if req.IdempotencyKey != "" {
		if code, body, found := CheckIdempotency(h.DB, req.IdempotencyKey); found {
			w.Header().Set("Content-Type", "application/json")
			w.WriteHeader(code)
			w.Write(body)
			return
		}
	}

	if req.SampleID == "" || req.AssignmentID == "" || req.RecordedAt == "" {
		Error(w, http.StatusBadRequest, "Missing required fields", "invalid_json")
		return
	}

	recAt, err := time.Parse(time.RFC3339, req.RecordedAt)
	if err != nil {
		Error(w, http.StatusBadRequest, "Invalid recordedAt format", "invalid_time")
		return
	}

	chkID, compliant, sampleStatus, err := h.OpsService.RecordCheckpoint(req.SampleID, req.AssignmentID, req.LocationID, req.ContainerType, req.ObservedTemperatureC, recAt, actor.ID)
	if err != nil {
		Error(w, http.StatusInternalServerError, err.Error(), "internal_error")
		return
	}

	res := map[string]interface{}{
		"checkpointId": chkID,
		"sampleId":     req.SampleID,
		"compliant":    compliant,
		"sampleStatus": sampleStatus,
	}

	SaveIdempotency(h.DB, req.IdempotencyKey, "record_handling_checkpoint", http.StatusCreated, res)
	JSON(w, http.StatusCreated, res)
}

