package handlers

import (
	"database/sql"
	"encoding/json"
	"errors"
	"labsystem/internal/models"
	"labsystem/internal/services"
	"net/http"
	"time"
)

type AssignmentsHandoffsHandler struct {
	DB                *sql.DB
	AssignmentService *services.AssignmentService
	HandoffService    *services.HandoffService
	AuditService      *services.AuditService
}

func NewAssignmentsHandoffsHandler(db *sql.DB, assign *services.AssignmentService, handoff *services.HandoffService, audit *services.AuditService) *AssignmentsHandoffsHandler {
	return &AssignmentsHandoffsHandler{
		DB:                db,
		AssignmentService: assign,
		HandoffService:    handoff,
		AuditService:      audit,
	}
}

func (h *AssignmentsHandoffsHandler) AcceptAssignment(w http.ResponseWriter, r *http.Request) {
	actor := GetUserFromContext(r.Context())
	if actor == nil {
		Error(w, http.StatusUnauthorized, "Unauthorized", "unauthorized")
		return
	}

	var req struct {
		AssignmentID   string `json:"assignmentId"`
		IdempotencyKey string `json:"idempotencyKey"`
	}

	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		Error(w, http.StatusBadRequest, "Invalid JSON payload", "invalid_json")
		return
	}

	if req.IdempotencyKey != "" {
		if code, body, found := CheckIdempotency(h.DB, req.IdempotencyKey); found {
			w.Header().Set("Content-Type", "application/json")
			w.WriteHeader(code)
			w.Write(body)
			return
		}
	}

	if req.AssignmentID == "" {
		Error(w, http.StatusBadRequest, "Assignment ID required", "invalid_json")
		return
	}

	err := h.AssignmentService.AcceptAssignment(req.AssignmentID, actor.ID)
	if err != nil {
		if errors.Is(err, services.ErrIneligibleWorker) {
			Error(w, http.StatusForbidden, "Assignment is not offered to you", "ineligible_worker")
			return
		}
		if errors.Is(err, services.ErrAssignmentInactive) {
			Error(w, http.StatusConflict, "Assignment is no longer available", "assignment_inactive")
			return
		}
		Error(w, http.StatusBadRequest, err.Error(), "invalid_json")
		return
	}

	res := map[string]interface{}{
		"assignmentId": req.AssignmentID,
		"workerId":     actor.ID,
		"status":       "accepted",
	}

	SaveIdempotency(h.DB, req.IdempotencyKey, "accept_assignment", http.StatusCreated, res)
	JSON(w, http.StatusCreated, res)
}

func (h *AssignmentsHandoffsHandler) DeclineAssignment(w http.ResponseWriter, r *http.Request) {
	actor := GetUserFromContext(r.Context())
	if actor == nil {
		Error(w, http.StatusUnauthorized, "Unauthorized", "unauthorized")
		return
	}

	var req struct {
		AssignmentID   string  `json:"assignmentId"`
		Reason         *string `json:"reason"`
		DeclinedAt     *string `json:"declinedAt"`
		IdempotencyKey string  `json:"idempotencyKey"`
	}

	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		Error(w, http.StatusBadRequest, "Invalid JSON payload", "invalid_json")
		return
	}

	if req.IdempotencyKey != "" {
		if code, body, found := CheckIdempotency(h.DB, req.IdempotencyKey); found {
			w.Header().Set("Content-Type", "application/json")
			w.WriteHeader(code)
			w.Write(body)
			return
		}
	}

	if req.AssignmentID == "" {
		Error(w, http.StatusBadRequest, "Assignment ID required", "invalid_json")
		return
	}

	decTime := time.Now().UTC()
	if req.DeclinedAt != nil && *req.DeclinedAt != "" {
		if t, err := time.Parse(time.RFC3339, *req.DeclinedAt); err == nil {
			decTime = t
		}
	}

	reasonStr := ""
	if req.Reason != nil {
		reasonStr = *req.Reason
	}

	reofferedTo, err := h.AssignmentService.DeclineAssignment(req.AssignmentID, actor.ID, reasonStr, decTime)
	if err != nil {
		if errors.Is(err, services.ErrIneligibleWorker) {
			Error(w, http.StatusForbidden, "Assignment is not offered to you", "forbidden")
			return
		}
		if errors.Is(err, services.ErrOfferNotAvailable) {
			Error(w, http.StatusConflict, "Offer no longer available", "offer_not_available")
			return
		}
		Error(w, http.StatusBadRequest, err.Error(), "invalid_json")
		return
	}

	res := map[string]interface{}{
		"assignmentId": req.AssignmentID,
		"status":       "pending",
		"declinedBy":   actor.ID,
		"declinedAt":   models.FormatTime(decTime),
	}
	if reofferedTo != "" {
		res["reofferedTo"] = reofferedTo
	}

	SaveIdempotency(h.DB, req.IdempotencyKey, "decline_assignment", http.StatusCreated, res)
	JSON(w, http.StatusCreated, res)
}

func (h *AssignmentsHandoffsHandler) UpdateAssignmentProgress(w http.ResponseWriter, r *http.Request) {
