func (h *AssignmentsHandoffsHandler) ListRoleWork(w http.ResponseWriter, r *http.Request) {
	actor := GetUserFromContext(r.Context())
	if actor == nil {
		Error(w, http.StatusUnauthorized, "Unauthorized", "unauthorized")
		return
	}

	var req struct {
		Role   *string `json:"role"`
		Status *string `json:"status"`
	}
	_ = json.NewDecoder(r.Body).Decode(&req)

	targetRole := actor.ActiveRole
	if req.Role != nil && *req.Role != "" {
		targetRole = *req.Role
	}

	roleWork := models.RoleWork{
		Pending:    []interface{}{},
		InProgress: []interface{}{},
		Completed:  []interface{}{},
	}

	if targetRole == "requester" {
		rows, err := h.DB.Query(`
			SELECT s.id, s.request_id, s.status, cr.serviceability, cr.requested_at, cr.delivery_deadline,
			       cr.earliest_collection_at, cr.latest_collection_at, s.active_journey_id, s.target_laboratory_id,
			       s.current_holder_id, cr.requester_id, s.location_recorded_at
			FROM samples s
			JOIN collection_requests cr ON s.request_id = cr.id
			WHERE cr.requester_id = $1
			ORDER BY cr.requested_at DESC
		`, actor.ID)

		if err == nil {
			defer rows.Close()
			for rows.Next() {
				var wi models.SampleWorkItem
				var reqAt, dl, earCol, latCol time.Time
				var jID, labID, holder sql.NullString
				var locRecAt sql.NullTime
				var serv sql.NullString

				if err := rows.Scan(&wi.SampleID, &wi.RequestID, &wi.Status, &serv, &reqAt, &dl, &earCol, &latCol, &jID, &labID, &holder, &wi.RequesterID, &locRecAt); err == nil {
					wi.Kind = "sample"
					wi.Sample_ID = wi.SampleID
					if serv.Valid {
						wi.Serviceability = serv.String
					}
					wi.RequestedAt = models.FormatTime(reqAt)
					wi.DeliveryDeadline = models.FormatTime(dl)
					wi.EarliestCollectionAt = models.FormatTime(earCol)
					wi.LatestCollectionAt = models.FormatTime(latCol)
					if jID.Valid {
						wi.JourneyID = &jID.String
						wi.ActiveJourneyID = &jID.String
					}
					if labID.Valid {
						wi.LaboratoryID = &labID.String
					}
					if holder.Valid {
						wi.CurrentHolderID = &holder.String
					}
					if locRecAt.Valid {
						tStr := models.FormatTime(locRecAt.Time)
						wi.LocationRecordedAt = &tStr
						wi.LocationStale = locRecAt.Time.Before(time.Now().UTC().Add(-10 * time.Minute))
					} else {
						wi.LocationStale = true
					}

					timeline, _ := h.AuditService.GetTimelineForEntity("sample", wi.SampleID)
					wi.History = timeline

					if wi.Status == "completed" || wi.Status == "delivered" || wi.Status == "received" || wi.Status == "cancelled" {
						roleWork.Completed = append(roleWork.Completed, wi)
					} else if wi.Status == "requested" {
						roleWork.Pending = append(roleWork.Pending, wi)
					} else {
						roleWork.InProgress = append(roleWork.InProgress, wi)
					}
				}
			}
		}
	} else if targetRole == "administrator" || targetRole == "dispatcher" {
		// List journeys
		rows, err := h.DB.Query(`
			SELECT id, status, route_mode, plan_version, sample_ids, estimated_delivery_at
			FROM journeys
			ORDER BY created_at DESC
		`)
		if err == nil {
			defer rows.Close()
			for rows.Next() {
				var j models.JourneyWorkItem
				var sampleIDs pq.StringArray
				var estDel sql.NullTime
				if err := rows.Scan(&j.JourneyID, &j.Status, &j.RouteMode, &j.PlanVersion, &sampleIDs, &estDel); err == nil {
					j.Kind = "journey"
					j.Journey_ID = j.JourneyID
					j.SampleIDs = []string(sampleIDs)
					if estDel.Valid {
						tStr := models.FormatTime(estDel.Time)
						j.EstimatedDeliveryAt = &tStr
					}

					var assignCount int
					_ = h.DB.QueryRow(`SELECT COUNT(*) FROM assignments WHERE journey_id = $1`, j.JourneyID).Scan(&assignCount)
					j.AssignmentCount = assignCount

					timeline, _ := h.AuditService.GetTimelineForEntity("journey", j.JourneyID)
					j.History = timeline

					if j.Status == "completed" || j.Status == "cancelled" {
						roleWork.Completed = append(roleWork.Completed, j)
					} else if j.Status == "planned" {
						roleWork.Pending = append(roleWork.Pending, j)
					} else {
						roleWork.InProgress = append(roleWork.InProgress, j)
					}
				}
			}
		}
	} else {
		// Worker assignments (collection_professional, delivery_partner, node_handler, laboratory_team)
		kindFilter := "collection"
		if targetRole == "delivery_partner" {
			kindFilter = "transport"
		} else if targetRole == "node_handler" {
			kindFilter = "node"
		} else if targetRole == "laboratory_team" {
			kindFilter = "laboratory"
		}

		rows, err := h.DB.Query(`
			SELECT id, kind, sample_id, status, journey_id, from_location_id, to_location_id, sequence,
			       offer_expires_at, node_id, laboratory_id, expected_sample_type_id
			FROM assignments
			WHERE (worker_id = $1 OR (status = 'offered' AND worker_id = $1)) AND kind = $2
			ORDER BY created_at DESC
		`, actor.ID, kindFilter)

		if err == nil {
			defer rows.Close()
			for rows.Next() {
				var wi models.AssignmentWorkItem
				var fromLoc, toLoc, nodeID, labID, expST sql.NullString
				var expAt sql.NullTime

				if err := rows.Scan(&wi.AssignmentID, &wi.Kind, &wi.SampleID, &wi.Status, &wi.JourneyID, &fromLoc, &toLoc, &wi.Sequence, &expAt, &nodeID, &labID, &expST); err == nil {
					wi.Assignment_ID = wi.AssignmentID
					wi.Sample_ID = wi.SampleID
					if fromLoc.Valid {
						wi.FromLocationID = &fromLoc.String
					}
					if toLoc.Valid {
						wi.ToLocationID = &toLoc.String
					}
					if nodeID.Valid {
						wi.NodeID = &nodeID.String
					}
					if labID.Valid {
						wi.LaboratoryID = &labID.String
					}
					if expST.Valid {
						wi.ExpectedSampleTypeID = &expST.String
					}
					if expAt.Valid {
						tStr := models.FormatTime(expAt.Time)
						wi.OfferExpiresAt = &tStr
					}

					timeline, _ := h.AuditService.GetTimelineForEntity("assignment", wi.AssignmentID)
					wi.History = timeline

					if wi.Status == "completed" || wi.Status == "declined" || wi.Status == "cancelled" {
						roleWork.Completed = append(roleWork.Completed, wi)
					} else if wi.Status == "offered" || wi.Status == "pending" {
						roleWork.Pending = append(roleWork.Pending, wi)
					} else {
						roleWork.InProgress = append(roleWork.InProgress, wi)
					}
				}
			}
		}
	}

	JSON(w, http.StatusOK, roleWork)
}

