package handlers

import (
	"database/sql"
	"encoding/json"
	"errors"
	"labsystem/internal/models"
	"labsystem/internal/services"
	"net/http"
	"time"

	"github.com/google/uuid"
	"github.com/lib/pq"
)

type JourneysDisruptionsHandler struct {
	DB             *sql.DB
	JourneyService *services.JourneyService
	AuditService   *services.AuditService
}

func NewJourneysDisruptionsHandler(db *sql.DB, js *services.JourneyService, audit *services.AuditService) *JourneysDisruptionsHandler {
	return &JourneysDisruptionsHandler{
		DB:             db,
		JourneyService: js,
		AuditService:   audit,
	}
}

func (h *JourneysDisruptionsHandler) ReadJourneyPlan(w http.ResponseWriter, r *http.Request) {
	actor := GetUserFromContext(r.Context())
	if actor == nil {
		Error(w, http.StatusUnauthorized, "Unauthorized", "unauthorized")
		return
	}

	var req struct {
		JourneyID string `json:"journeyId"`
	}

	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		Error(w, http.StatusBadRequest, "Invalid JSON payload", "invalid_json")
		return
	}

	if req.JourneyID == "" {
		Error(w, http.StatusBadRequest, "Journey ID required", "invalid_json")
		return
	}

	fullPlan, err := h.JourneyService.GetFullJourneyPlan(req.JourneyID)
	if err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			Error(w, http.StatusNotFound, "Journey not found", "not_found")
			return
		}
		Error(w, http.StatusInternalServerError, err.Error(), "internal_error")
		return
	}

	if actor.ActiveRole == "administrator" || actor.ActiveRole == "dispatcher" {
		JSON(w, http.StatusOK, fullPlan)
		return
	}

	if actor.ActiveRole == "requester" {
		var legs []map[string]interface{}
		for _, l := range fullPlan.Legs {
			legs = append(legs, map[string]interface{}{
				"sequence": l.Sequence,
				"status":   l.Status,
			})
		}
		if legs == nil {
			legs = []map[string]interface{}{}
		}

		requesterPlan := models.RequesterJourneyPlan{
			JourneyID:           fullPlan.JourneyID,
			ParentJourneyID:     fullPlan.ParentJourneyID,
			PlanVersion:         fullPlan.PlanVersion,
			RouteMode:           fullPlan.RouteMode,
			Status:              fullPlan.Status,
			EstimatedDeliveryAt: fullPlan.EstimatedDeliveryAt,
			TotalCostUnits:      fullPlan.TotalCostUnits,
			SampleIDs:           fullPlan.SampleIDs,
			OrderedStops:        fullPlan.OrderedStops,
			Legs:                legs,
		}
		JSON(w, http.StatusOK, requesterPlan)
		return
	}

	// Worker view
	var myAssignmentIDs []string
	var myLegs []models.JourneyLeg
	for _, l := range fullPlan.Legs {
		if l.WorkerID != nil && *l.WorkerID == actor.ID {
			myAssignmentIDs = append(myAssignmentIDs, l.AssignmentID)
			myLegs = append(myLegs, l)
		}
	}
	if myAssignmentIDs == nil {
		myAssignmentIDs = []string{}
	}
	if myLegs == nil {
		myLegs = []models.JourneyLeg{}
	}

	workerPlan := models.WorkerJourneyPlan{
		JourneyID:               fullPlan.JourneyID,
		ParentJourneyID:         fullPlan.ParentJourneyID,
		PlanVersion:             fullPlan.PlanVersion,
		RouteMode:               fullPlan.RouteMode,
		Status:                  fullPlan.Status,
		EstimatedDeliveryAt:     fullPlan.EstimatedDeliveryAt,
		Scope:                   "assigned_legs",
		AssignmentIDs:           myAssignmentIDs,
		SampleIDs:               fullPlan.SampleIDs,
		Legs:                    myLegs,
		OrderedStops:            fullPlan.OrderedStops,
		CollectionAssignmentIDs: fullPlan.CollectionAssignmentIDs,
		NodeAssignmentIDs:       fullPlan.NodeAssignmentIDs,
		LaboratoryAssignmentIDs: fullPlan.LaboratoryAssignmentIDs,
		AssignedWorkerIDs:       fullPlan.AssignedWorkerIDs,
	}
	JSON(w, http.StatusOK, workerPlan)
}

func (h *JourneysDisruptionsHandler) EditActivePlan(w http.ResponseWriter, r *http.Request) {
	actor := GetUserFromContext(r.Context())
	if actor == nil {
		Error(w, http.StatusUnauthorized, "Unauthorized", "unauthorized")
		return
	}

	var req struct {
		JourneyID           string                 `json:"journeyId"`
		ExpectedPlanVersion int                    `json:"expectedPlanVersion"`
		ChangeType          string                 `json:"changeType"`
		Changes             map[string]interface{} `json:"changes"`
		IdempotencyKey      string                 `json:"idempotencyKey"`
	}

	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		Error(w, http.StatusBadRequest, "Invalid JSON payload", "invalid_json")
		return
	}

	if req.IdempotencyKey != "" {
		if code, body, found := CheckIdempotency(h.DB, req.IdempotencyKey); found {
			w.Header().Set("Content-Type", "application/json")
			w.WriteHeader(code)
			w.Write(body)
			return
		}
	}

	var curVersion int
	err := h.DB.QueryRow(`SELECT plan_version FROM journeys WHERE id = $1`, req.JourneyID).Scan(&curVersion)
	if err != nil {
		Error(w, http.StatusNotFound, "Journey not found", "not_found")
		return
	}

	if curVersion != req.ExpectedPlanVersion {
		Error(w, http.StatusConflict, "Plan version has changed", "stale_plan")
		return
	}

	newVersion := curVersion + 1
	_, err = h.DB.Exec(`UPDATE journeys SET plan_version = $1, updated_at = NOW() WHERE id = $2`, newVersion, req.JourneyID)
	if err != nil {
		Error(w, http.StatusInternalServerError, err.Error(), "internal_error")
		return
	}

	plan, err := h.JourneyService.GetFullJourneyPlan(req.JourneyID)
	if err != nil {
		Error(w, http.StatusInternalServerError, err.Error(), "internal_error")
		return
	}

	sDetails := req.Changes
	if sDetails == nil {
		sDetails = map[string]interface{}{}
	}
	sDetails["changeType"] = req.ChangeType

	h.AuditService.LogTimeline("journey.plan_edited", actor.ID, actor.ActiveRole, "journey", req.JourneyID, true, sDetails)
	h.AuditService.LogAudit(actor.ID, actor.ActiveRole, "journey.edit_plan", "journey", req.JourneyID, true, sDetails)

	SaveIdempotency(h.DB, req.IdempotencyKey, "edit_active_plan", http.StatusCreated, plan)
	JSON(w, http.StatusCreated, plan)
}

func (h *JourneysDisruptionsHandler) SplitJourney(w http.ResponseWriter, r *http.Request) {
	actor := GetUserFromContext(r.Context())
	if actor == nil {
		Error(w, http.StatusUnauthorized, "Unauthorized", "unauthorized")
		return
	}

	var req struct {
		JourneyID           string   `json:"journeyId"`
		ExpectedPlanVersion int      `json:"expectedPlanVersion"`
		SampleIDs           []string `json:"sampleIds"`
		IdempotencyKey      string   `json:"idempotencyKey"`
	}

	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		Error(w, http.StatusBadRequest, "Invalid JSON payload", "invalid_json")
		return
	}

	if req.IdempotencyKey != "" {
		if code, body, found := CheckIdempotency(h.DB, req.IdempotencyKey); found {
			w.Header().Set("Content-Type", "application/json")
			w.WriteHeader(code)
			w.Write(body)
			return
		}
	}

	var curVersion int
	var existingSamples pq.StringArray
	err := h.DB.QueryRow(`SELECT plan_version, sample_ids FROM journeys WHERE id = $1`, req.JourneyID).Scan(&curVersion, &existingSamples)
	if err != nil {
		Error(w, http.StatusNotFound, "Journey not found", "not_found")
		return
	}

	if curVersion != req.ExpectedPlanVersion {
		Error(w, http.StatusConflict, "Plan version has changed", "stale_plan")
		return
	}

	// Create split journey
	splitJourneyID := uuid.New().String()
	newVersion := curVersion + 1

	// Remaining samples
	splitSet := make(map[string]bool)
	for _, s := range req.SampleIDs {
		splitSet[s] = true
	}
	var remaining []string
	for _, s := range existingSamples {
		if !splitSet[s] {
			remaining = append(remaining, s)
		}
	}

	_, _ = h.DB.Exec(`
		UPDATE journeys
		SET plan_version = $1, sample_ids = $2, updated_at = NOW()
		WHERE id = $3
	`, newVersion, pq.Array(remaining), req.JourneyID)

	_, _ = h.DB.Exec(`
		INSERT INTO journeys (id, parent_journey_id, plan_version, route_mode, status, sample_ids, valid, replan_status)
		VALUES ($1, $2, 1, 'direct', 'planned', $3, true, 'not_required')
	`, splitJourneyID, req.JourneyID, pq.Array(req.SampleIDs))

	for _, sid := range req.SampleIDs {
		_, _ = h.DB.Exec(`UPDATE samples SET active_journey_id = $1 WHERE id = $2`, splitJourneyID, sid)
	}

	origPlan, _ := h.JourneyService.GetFullJourneyPlan(req.JourneyID)
	splitPlan, _ := h.JourneyService.GetFullJourneyPlan(splitJourneyID)

	res := map[string]interface{}{
		"journey":      origPlan,
		"splitJourney": splitPlan,
	}

	h.AuditService.LogAudit(actor.ID, actor.ActiveRole, "journey.split", "journey", req.JourneyID, true, map[string]interface{}{
		"splitJourneyId": splitJourneyID,
		"splitSampleIds": req.SampleIDs,
	})

	SaveIdempotency(h.DB, req.IdempotencyKey, "split_journey", http.StatusCreated, res)
	JSON(w, http.StatusCreated, res)
}

func (h *JourneysDisruptionsHandler) MergeJourneys(w http.ResponseWriter, r *http.Request) {
	actor := GetUserFromContext(r.Context())
	if actor == nil {
		Error(w, http.StatusUnauthorized, "Unauthorized", "unauthorized")
		return
	}

	var req struct {
		TargetJourneyID     string   `json:"targetJourneyId"`
		ExpectedPlanVersion int      `json:"expectedPlanVersion"`
		SourceJourneyIDs    []string `json:"sourceJourneyIds"`
		IdempotencyKey      string   `json:"idempotencyKey"`
	}

	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		Error(w, http.StatusBadRequest, "Invalid JSON payload", "invalid_json")
		return
	}

	if req.IdempotencyKey != "" {
		if code, body, found := CheckIdempotency(h.DB, req.IdempotencyKey); found {
			w.Header().Set("Content-Type", "application/json")
			w.WriteHeader(code)
			w.Write(body)
			return
		}
	}

	var curVersion int
	var targetSamples pq.StringArray
	err := h.DB.QueryRow(`SELECT plan_version, sample_ids FROM journeys WHERE id = $1`, req.TargetJourneyID).Scan(&curVersion, &targetSamples)
	if err != nil {
		Error(w, http.StatusNotFound, "Target journey not found", "not_found")
		return
	}

	if curVersion != req.ExpectedPlanVersion {
		Error(w, http.StatusConflict, "Plan version has changed", "stale_plan")
		return
	}

	allSamples := []string(targetSamples)
	for _, sjID := range req.SourceJourneyIDs {
		var srcSamples pq.StringArray
		_ = h.DB.QueryRow(`SELECT sample_ids FROM journeys WHERE id = $1`, sjID).Scan(&srcSamples)
		for _, sid := range srcSamples {
			allSamples = append(allSamples, sid)
			_, _ = h.DB.Exec(`UPDATE samples SET active_journey_id = $1 WHERE id = $2`, req.TargetJourneyID, sid)
		}
		_, _ = h.DB.Exec(`UPDATE journeys SET status = 'cancelled', updated_at = NOW() WHERE id = $1`, sjID)
	}

	newVersion := curVersion + 1
	_, _ = h.DB.Exec(`
		UPDATE journeys
		SET plan_version = $1, route_mode = 'batched', sample_ids = $2, updated_at = NOW()
		WHERE id = $3
	`, newVersion, pq.Array(allSamples), req.TargetJourneyID)

	targetPlan, _ := h.JourneyService.GetFullJourneyPlan(req.TargetJourneyID)

	h.AuditService.LogAudit(actor.ID, actor.ActiveRole, "journey.merge", "journey", req.TargetJourneyID, true, map[string]interface{}{
		"sourceJourneys": req.SourceJourneyIDs,
		"allSamples":     allSamples,
	})

	SaveIdempotency(h.DB, req.IdempotencyKey, "merge_journeys", http.StatusCreated, targetPlan)
	JSON(w, http.StatusCreated, targetPlan)
}

func (h *JourneysDisruptionsHandler) RerouteJourney(w http.ResponseWriter, r *http.Request) {
	actor := GetUserFromContext(r.Context())
	if actor == nil {
		Error(w, http.StatusUnauthorized, "Unauthorized", "unauthorized")
		return
	}

	var req struct {
		JourneyID           string  `json:"journeyId"`
		ExpectedPlanVersion int     `json:"expectedPlanVersion"`
		Reason              *string `json:"reason"`
		IdempotencyKey      string  `json:"idempotencyKey"`
	}

	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		Error(w, http.StatusBadRequest, "Invalid JSON payload", "invalid_json")
		return
	}

	if req.IdempotencyKey != "" {
		if code, body, found := CheckIdempotency(h.DB, req.IdempotencyKey); found {
			w.Header().Set("Content-Type", "application/json")
			w.WriteHeader(code)
			w.Write(body)
			return
		}
	}

	reasonStr := ""
	if req.Reason != nil {
		reasonStr = *req.Reason
	}

	replanStatus, replanPlanID, replanJourney, err := h.JourneyService.RerouteJourney(req.JourneyID, req.ExpectedPlanVersion, reasonStr)
	if err != nil {
		if errors.Is(err, services.ErrStalePlan) {
			Error(w, http.StatusConflict, "Plan version has changed", "stale_plan")
			return
		}
		Error(w, http.StatusBadRequest, err.Error(), "invalid_json")
		return
	}

	res := map[string]interface{}{
		"journeyId":    req.JourneyID,
		"replanStatus": replanStatus,
	}
	if replanPlanID != nil {
		res["replacementPlanId"] = *replanPlanID
	}
	if replanJourney != nil {
		res["replacementJourney"] = replanJourney
	}

	SaveIdempotency(h.DB, req.IdempotencyKey, "reroute_journey", http.StatusCreated, res)
	JSON(w, http.StatusCreated, res)
}

func (h *JourneysDisruptionsHandler) CancelJourney(w http.ResponseWriter, r *http.Request) {
	actor := GetUserFromContext(r.Context())
	if actor == nil {
		Error(w, http.StatusUnauthorized, "Unauthorized", "unauthorized")
		return
	}

	var req struct {
		JourneyID           string  `json:"journeyId"`
		ExpectedPlanVersion int     `json:"expectedPlanVersion"`
		Reason              *string `json:"reason"`
		IdempotencyKey      string  `json:"idempotencyKey"`
	}

	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		Error(w, http.StatusBadRequest, "Invalid JSON payload", "invalid_json")
		return
	}

	if req.IdempotencyKey != "" {
		if code, body, found := CheckIdempotency(h.DB, req.IdempotencyKey); found {
			w.Header().Set("Content-Type", "application/json")
			w.WriteHeader(code)
			w.Write(body)
			return
		}
	}

	reasonStr := ""
	if req.Reason != nil {
		reasonStr = *req.Reason
	}

	sampleIDs, err := h.JourneyService.CancelJourney(req.JourneyID, req.ExpectedPlanVersion, reasonStr)
	if err != nil {
		if errors.Is(err, services.ErrStalePlan) {
			Error(w, http.StatusConflict, "Plan version has changed", "stale_plan")
			return
		}
		Error(w, http.StatusBadRequest, err.Error(), "invalid_json")
		return
	}

	res := map[string]interface{}{
		"journeyId": req.JourneyID,
		"status":    "cancelled",
		"sampleIds": sampleIDs,
	}

	SaveIdempotency(h.DB, req.IdempotencyKey, "cancel_journey", http.StatusCreated, res)
	JSON(w, http.StatusCreated, res)
}

func (h *JourneysDisruptionsHandler) ReportDisruption(w http.ResponseWriter, r *http.Request) {
	actor := GetUserFromContext(r.Context())
	if actor == nil {
		Error(w, http.StatusUnauthorized, "Unauthorized", "unauthorized")
		return
	}

	var req struct {
		ResourceType   string  `json:"resourceType"`
		ResourceID     string  `json:"resourceId"`
		Reason         *string `json:"reason"`
		OccurredAt     string  `json:"occurredAt"`
		IdempotencyKey string  `json:"idempotencyKey"`
	}

	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		Error(w, http.StatusBadRequest, "Invalid JSON payload", "invalid_json")
		return
	}

	if req.IdempotencyKey != "" {
		if code, body, found := CheckIdempotency(h.DB, req.IdempotencyKey); found {
			w.Header().Set("Content-Type", "application/json")
			w.WriteHeader(code)
			w.Write(body)
			return
		}
	}

	if req.ResourceType == "" || req.ResourceID == "" || req.OccurredAt == "" {
		Error(w, http.StatusBadRequest, "Missing required fields", "invalid_json")
		return
	}

	occAt, err := time.Parse(time.RFC3339, req.OccurredAt)
	if err != nil {
		Error(w, http.StatusBadRequest, "Invalid occurredAt format", "invalid_time")
		return
	}

	reasonStr := ""
	if req.Reason != nil {
		reasonStr = *req.Reason
	}

	disID, affSamples, replPlans, replanStatus, err := h.JourneyService.ReportDisruption(req.ResourceType, req.ResourceID, reasonStr, occAt)
	if err != nil {
		Error(w, http.StatusInternalServerError, err.Error(), "internal_error")
		return
	}

	res := map[string]interface{}{
		"disruptionId":       disID,
		"affectedSampleIds":  affSamples,
		"replacementPlanIds": replPlans,
		"replanStatus":       replanStatus,
	}

	SaveIdempotency(h.DB, req.IdempotencyKey, "report_disruption", http.StatusCreated, res)
	JSON(w, http.StatusCreated, res)
}

