func (h *JourneysDisruptionsHandler) SplitJourney(w http.ResponseWriter, r *http.Request) {
	actor := GetUserFromContext(r.Context())
	if actor == nil {
		Error(w, http.StatusUnauthorized, "Unauthorized", "unauthorized")
		return
	}

	var req struct {
		JourneyID           string   `json:"journeyId"`
		ExpectedPlanVersion int      `json:"expectedPlanVersion"`
		SampleIDs           []string `json:"sampleIds"`
		IdempotencyKey      string   `json:"idempotencyKey"`
	}

	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		Error(w, http.StatusBadRequest, "Invalid JSON payload", "invalid_json")
		return
	}

	if req.IdempotencyKey != "" {
		if code, body, found := CheckIdempotency(h.DB, req.IdempotencyKey); found {
			w.Header().Set("Content-Type", "application/json")
			w.WriteHeader(code)
			w.Write(body)
			return
		}
	}

	var curVersion int
	var existingSamples pq.StringArray
	err := h.DB.QueryRow(`SELECT plan_version, sample_ids FROM journeys WHERE id = $1`, req.JourneyID).Scan(&curVersion, &existingSamples)
	if err != nil {
		Error(w, http.StatusNotFound, "Journey not found", "not_found")
		return
	}

	if curVersion != req.ExpectedPlanVersion {
		Error(w, http.StatusConflict, "Plan version has changed", "stale_plan")
		return
	}

	// Create split journey
	splitJourneyID := uuid.New().String()
	newVersion := curVersion + 1

	// Remaining samples
	splitSet := make(map[string]bool)
	for _, s := range req.SampleIDs {
		splitSet[s] = true
	}
	var remaining []string
	for _, s := range existingSamples {
		if !splitSet[s] {
			remaining = append(remaining, s)
		}
	}

	_, _ = h.DB.Exec(`
		UPDATE journeys
		SET plan_version = $1, sample_ids = $2, updated_at = NOW()
		WHERE id = $3
	`, newVersion, pq.Array(remaining), req.JourneyID)

	_, _ = h.DB.Exec(`
		INSERT INTO journeys (id, parent_journey_id, plan_version, route_mode, status, sample_ids, valid, replan_status)
		VALUES ($1, $2, 1, 'direct', 'planned', $3, true, 'not_required')
	`, splitJourneyID, req.JourneyID, pq.Array(req.SampleIDs))

	for _, sid := range req.SampleIDs {
		_, _ = h.DB.Exec(`UPDATE samples SET active_journey_id = $1 WHERE id = $2`, splitJourneyID, sid)
	}

	origPlan, _ := h.JourneyService.GetFullJourneyPlan(req.JourneyID)
	splitPlan, _ := h.JourneyService.GetFullJourneyPlan(splitJourneyID)

	res := map[string]interface{}{
		"journey":      origPlan,
		"splitJourney": splitPlan,
	}

	h.AuditService.LogAudit(actor.ID, actor.ActiveRole, "journey.split", "journey", req.JourneyID, true, map[string]interface{}{
		"splitJourneyId": splitJourneyID,
		"splitSampleIds": req.SampleIDs,
	})

	SaveIdempotency(h.DB, req.IdempotencyKey, "split_journey", http.StatusCreated, res)
	JSON(w, http.StatusCreated, res)
}

