			w.Header().Set("Content-Type", "application/json")
			w.WriteHeader(code)
			w.Write(body)
			return
		}
	}

	reasonStr := ""
	if req.Reason != nil {
		reasonStr = *req.Reason
	}

	replanStatus, replanPlanID, replanJourney, err := h.JourneyService.RerouteJourney(req.JourneyID, req.ExpectedPlanVersion, reasonStr)
	if err != nil {
		if errors.Is(err, services.ErrStalePlan) {
			Error(w, http.StatusConflict, "Plan version has changed", "stale_plan")
			return
		}
		Error(w, http.StatusBadRequest, err.Error(), "invalid_json")
		return
	}

	res := map[string]interface{}{
		"journeyId":    req.JourneyID,
		"replanStatus": replanStatus,
	}
	if replanPlanID != nil {
		res["replacementPlanId"] = *replanPlanID
	}
	if replanJourney != nil {
		res["replacementJourney"] = replanJourney
	}

	SaveIdempotency(h.DB, req.IdempotencyKey, "reroute_journey", http.StatusCreated, res)
	JSON(w, http.StatusCreated, res)
}

func (h *JourneysDisruptionsHandler) CancelJourney(w http.ResponseWriter, r *http.Request) {
	actor := GetUserFromContext(r.Context())
	if actor == nil {
		Error(w, http.StatusUnauthorized, "Unauthorized", "unauthorized")
		return
	}

	var req struct {
		JourneyID           string  `json:"journeyId"`
