package services

import (
	"database/sql"
	"encoding/json"
	"errors"
	"fmt"
	"labsystem/internal/models"
	"time"

	"github.com/google/uuid"
	"github.com/lib/pq"
)

var (
	ErrIneligibleWorker = errors.New("ineligible_worker")
	ErrAssignmentTaken  = errors.New("assignment_taken")
	ErrOfferNotOffered  = errors.New("offer_not_offered")
	ErrOfferNotAvailable= errors.New("offer_not_available")
	ErrAssignmentInactive = errors.New("assignment_inactive")
	ErrWorkerUnavailable = errors.New("worker_unavailable")
)

type AssignmentService struct {
	DB           *sql.DB
	AuditService *AuditService
	EventService *EventService
}

func NewAssignmentService(db *sql.DB, audit *AuditService, events *EventService) *AssignmentService {
	return &AssignmentService{
		DB:           db,
		AuditService: audit,
		EventService: events,
	}
}

type CandidateWorker struct {
	ID               string
	Username         string
	ActiveWorkload   int
	TotalCompleted   int
	HasDeclinedThis  bool
}

func (s *AssignmentService) FindEligibleWorkers(kind string, requiredRole string, requiredQual string, locationID *string, assignmentID *string) ([]CandidateWorker, error) {
	query := `
		SELECT u.id, u.username, u.roles, u.qualifications, u.certifications, u.active, u.available, u.assigned_location_id,
		       COALESCE((SELECT COUNT(*) FROM assignments a WHERE a.worker_id = u.id AND a.status IN ('offered', 'accepted', 'in_progress')), 0) as active_workload,
		       COALESCE((SELECT COUNT(*) FROM assignments a WHERE a.worker_id = u.id AND a.status = 'completed'), 0) as total_completed
		FROM users u
		WHERE u.active = true AND u.available = true AND $1 = ANY(u.roles)
	`
	rows, err := s.DB.Query(query, requiredRole)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	var candidates []CandidateWorker
	for rows.Next() {
		var id, username string
		var roles, quals pq.StringArray
		var certsRaw []byte
		var active, available bool
		var assignedLoc sql.NullString
		var activeWorkload, totalCompleted int

		if err := rows.Scan(&id, &username, &roles, &quals, &certsRaw, &active, &available, &assignedLoc, &activeWorkload, &totalCompleted); err != nil {
			return nil, err
		}

		// Node / Lab assignment location check
		if (kind == "node" || kind == "laboratory") && locationID != nil && *locationID != "" {
			if !assignedLoc.Valid || assignedLoc.String != *locationID {
				continue
			}
		}

		// Qualification check for collection
		if kind == "collection" && requiredQual != "" {
			var certs []models.Certification
			_ = json.Unmarshal(certsRaw, &certs)
			hasCert := false
			for _, c := range certs {
				if c.Code == requiredQual && c.Active {
					if c.ExpiresAt == nil || *c.ExpiresAt == "" {
						hasCert = true
						break
					}
					if exp, err := time.Parse(time.RFC3339, *c.ExpiresAt); err == nil && exp.After(time.Now().UTC()) {
						hasCert = true
						break
					}
				}
			}
			if !hasCert {
				for _, q := range quals {
					if q == requiredQual {
						hasCert = true
						break
					}
				}
			}
			if !hasCert {
				continue
			}
		}

		// Check if declined this assignment
		hasDeclined := false
		if assignmentID != nil && *assignmentID != "" {
			var declinedCount int
			_ = s.DB.QueryRow(`SELECT COUNT(*) FROM assignments WHERE id = $1 AND declined_by = $2`, *assignmentID, id).Scan(&declinedCount)
			if declinedCount > 0 {
				hasDeclined = true
			}
		}

		candidates = append(candidates, CandidateWorker{
			ID:              id,
			Username:        username,
			ActiveWorkload:  activeWorkload,
			TotalCompleted:  totalCompleted,
			HasDeclinedThis: hasDeclined,
		})
	}

	// Sort candidates:
	// 1. Not declined first
	// 2. Active workload ASC
	// 3. Total completed ASC
	for i := 0; i < len(candidates); i++ {
		for j := i + 1; j < len(candidates); j++ {
			c1 := candidates[i]
			c2 := candidates[j]
			swap := false
			if c1.HasDeclinedThis && !c2.HasDeclinedThis {
				swap = true
			} else if c1.HasDeclinedThis == c2.HasDeclinedThis {
				if c1.ActiveWorkload > c2.ActiveWorkload {
					swap = true
				} else if c1.ActiveWorkload == c2.ActiveWorkload {
					if c1.TotalCompleted > c2.TotalCompleted {
						swap = true
					}
				}
			}
			if swap {
				candidates[i], candidates[j] = candidates[j], candidates[i]
			}
		}
	}

	return candidates, nil
}

func (s *AssignmentService) OfferAssignmentToBestWorker(assignmentID string, kind string, requiredRole string, requiredQual string, locationID *string) (string, error) {
	candidates, err := s.FindEligibleWorkers(kind, requiredRole, requiredQual, locationID, &assignmentID)
	if err != nil {
		return "", err
	}

	if len(candidates) == 0 {
		return "", nil
	}

	best := candidates[0]
	expiresAt := time.Now().UTC().Add(15 * time.Minute)

	_, err = s.DB.Exec(`
		UPDATE assignments
		SET worker_id = $1, status = 'offered', offer_expires_at = $2, updated_at = NOW()
		WHERE id = $3
	`, best.ID, expiresAt, assignmentID)
	if err != nil {
		return "", err
	}

	s.AuditService.LogAudit(best.ID, requiredRole, "assignment.offer", "assignment", assignmentID, true, map[string]interface{}{
		"workerId":       best.ID,
		"kind":           kind,
		"offerExpiresAt": models.FormatTime(expiresAt),
	})

	s.EventService.Broadcast("assignment.offered", "assignment", assignmentID, map[string]interface{}{
		"assignmentId": assignmentID,
		"workerId":     best.ID,
		"kind":         kind,
	})

	return best.ID, nil
}

func (s *AssignmentService) AcceptAssignment(assignmentID, workerID string) error {
	var currentStatus string
	var assignedWorker sql.NullString
	var sampleID, journeyID, kind string
	err := s.DB.QueryRow(`
		SELECT status, worker_id, sample_id, journey_id, kind
		FROM assignments
		WHERE id = $1
	`, assignmentID).Scan(&currentStatus, &assignedWorker, &sampleID, &journeyID, &kind)

	if err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return ErrAssignmentInactive
		}
		return err
	}

	if !assignedWorker.Valid || assignedWorker.String != workerID {
		return ErrIneligibleWorker
	}

	if currentStatus == "accepted" {
		return nil // idempotent
	}

	if currentStatus != "offered" && currentStatus != "pending" {
		return ErrAssignmentInactive
	}

	_, err = s.DB.Exec(`
		UPDATE assignments
		SET status = 'accepted', updated_at = NOW()
		WHERE id = $1
	`, assignmentID)
	if err != nil {
		return err
	}

	// Update sample status
	sampleStatus := "scheduled"
	if kind == "collection" {
		sampleStatus = "collection_scheduled"
	} else if kind == "transport" {
		sampleStatus = "in_transit"
	}
	_, _ = s.DB.Exec(`UPDATE samples SET status = $1, updated_at = NOW() WHERE id = $2`, sampleStatus, sampleID)

	s.AuditService.LogTimeline("assignment.accepted", workerID, kind, "assignment", assignmentID, true, map[string]interface{}{
		"workerId": workerID,
		"sampleId": sampleID,
		"status":   "accepted",
	})

	s.AuditService.LogTimeline("sample.status_changed", workerID, kind, "sample", sampleID, true, map[string]interface{}{
		"newStatus": sampleStatus,
	})

	s.AuditService.LogAudit(workerID, kind, "assignment.accept", "assignment", assignmentID, true, map[string]interface{}{
		"workerId": workerID,
		"sampleId": sampleID,
		"status":   "accepted",
	})

	s.EventService.Broadcast("assignment.accepted", "assignment", assignmentID, map[string]interface{}{
		"assignmentId": assignmentID,
		"workerId":     workerID,
		"sampleId":     sampleID,
		"status":       "accepted",
	})

	return nil
}

func (s *AssignmentService) DeclineAssignment(assignmentID, workerID, reason string, declinedAt time.Time) (string, error) {
	var currentStatus, kind, sampleID string
	var assignedWorker sql.NullString
	var fromLoc, toLoc, nodeLoc, labLoc sql.NullString
	var expectedST sql.NullString

	err := s.DB.QueryRow(`
		SELECT status, worker_id, kind, sample_id, from_location_id, to_location_id, node_id, laboratory_id, expected_sample_type_id
		FROM assignments
		WHERE id = $1
	`, assignmentID).Scan(&currentStatus, &assignedWorker, &kind, &sampleID, &fromLoc, &toLoc, &nodeLoc, &labLoc, &expectedST)

	if err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return "", ErrAssignmentInactive
		}
		return "", err
	}

	if !assignedWorker.Valid || assignedWorker.String != workerID {
		return "", ErrIneligibleWorker
	}

	if currentStatus != "offered" {
		return "", ErrOfferNotAvailable
	}

	_, err = s.DB.Exec(`
		UPDATE assignments
		SET status = 'pending', declined_by = $1, declined_at = $2, worker_id = NULL, updated_at = NOW()
		WHERE id = $3
	`, workerID, declinedAt, assignmentID)
	if err != nil {
		return "", err
	}

	s.AuditService.LogTimeline("assignment.declined", workerID, kind, "assignment", assignmentID, true, map[string]interface{}{
		"declinedBy": workerID,
		"reason":     reason,
	})

	s.AuditService.LogAudit(workerID, kind, "assignment.decline", "assignment", assignmentID, true, map[string]interface{}{
		"declinedBy": workerID,
		"reason":     reason,
	})

	// Re-offer to next worker
	var requiredRole string
	var qualCode string
	var targetLoc *string

	if kind == "collection" {
		requiredRole = "collection_professional"
		if expectedST.Valid {
			var q sql.NullString
			_ = s.DB.QueryRow(`SELECT required_qualification FROM sample_types WHERE id = $1`, expectedST.String).Scan(&q)
			if q.Valid {
				qualCode = q.String
			}
		}
	} else if kind == "transport" {
		requiredRole = "delivery_partner"
	} else if kind == "node" {
		requiredRole = "node_handler"
		if nodeLoc.Valid {
			targetLoc = &nodeLoc.String
		}
	} else if kind == "laboratory" {
		requiredRole = "laboratory_team"
		if labLoc.Valid {
			targetLoc = &labLoc.String
		}
	}

	reofferedTo, _ := s.OfferAssignmentToBestWorker(assignmentID, kind, requiredRole, qualCode, targetLoc)

	s.EventService.Broadcast("assignment.declined", "assignment", assignmentID, map[string]interface{}{
		"assignmentId": assignmentID,
		"declinedBy":   workerID,
		"reofferedTo":  reofferedTo,
	})

	return reofferedTo, nil
}

func (s *AssignmentService) UpdateProgress(assignmentID, workerID, newStatus string, occurredAt time.Time) (string, error) {
	var currentStatus, kind, sampleID string
	var assignedWorker sql.NullString

	err := s.DB.QueryRow(`
		SELECT status, worker_id, kind, sample_id
		FROM assignments
		WHERE id = $1
	`, assignmentID).Scan(&currentStatus, &assignedWorker, &kind, &sampleID)

	if err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return "", ErrAssignmentInactive
		}
		return "", err
	}

	// Update assignment status
	dbStatus := newStatus
	if newStatus == "delivered" || newStatus == "completed" {
		dbStatus = "completed"
	} else if newStatus == "picked_up" || newStatus == "in_transit" || newStatus == "at_pickup" || newStatus == "arrived" {
		dbStatus = "in_progress"
	}

	_, err = s.DB.Exec(`
		UPDATE assignments
		SET status = $1, updated_at = NOW()
		WHERE id = $2
	`, dbStatus, assignmentID)
	if err != nil {
		return "", err
	}

	// Sample status update
	sampleStatus := newStatus
	if newStatus == "delivered" {
		sampleStatus = "delivered"
	} else if newStatus == "picked_up" || newStatus == "in_transit" {
		sampleStatus = "in_transit"
	}
	_, _ = s.DB.Exec(`UPDATE samples SET status = $1, updated_at = NOW() WHERE id = $2`, sampleStatus, sampleID)

	s.AuditService.LogTimeline("assignment.progress_updated", workerID, kind, "assignment", assignmentID, true, map[string]interface{}{
		"status":     newStatus,
		"occurredAt": models.FormatTime(occurredAt),
	})

	s.AuditService.LogTimeline("sample.status_changed", workerID, kind, "sample", sampleID, true, map[string]interface{}{
		"newStatus": sampleStatus,
	})

	s.AuditService.LogAudit(workerID, kind, "assignment.update_progress", "assignment", assignmentID, true, map[string]interface{}{
		"status":     newStatus,
		"occurredAt": models.FormatTime(occurredAt),
	})

	s.EventService.Broadcast("assignment.progress_updated", "assignment", assignmentID, map[string]interface{}{
		"assignmentId": assignmentID,
		"sampleId":     sampleID,
		"status":       newStatus,
	})

	return sampleID, nil
}

func (s *AssignmentService) RecordLocation(assignmentID string, workerID string, coord models.Coordinate, sequence int, recordedAt time.Time) error {
	var sampleID string
	err := s.DB.QueryRow(`SELECT sample_id FROM assignments WHERE id = $1`, assignmentID).Scan(&sampleID)
	if err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return ErrAssignmentInactive
		}
		return err
	}

	coordJSON, _ := json.Marshal(coord)

	// Record in worker_location_history
	_, err = s.DB.Exec(`
		INSERT INTO worker_location_history (worker_id, assignment_id, latitude, longitude, sequence, recorded_at)
		VALUES ($1, $2, $3, $4, $5, $6)
	`, workerID, assignmentID, coord.Latitude, coord.Longitude, sequence, recordedAt)
	if err != nil {
		return err
	}

	// Update user's latest location
	_, _ = s.DB.Exec(`
		UPDATE users
		SET latest_location = $1::jsonb, location_recorded_at = $2, updated_at = NOW()
		WHERE id = $3
	`, string(coordJSON), recordedAt, workerID)

	// Update sample's latest location
	_, _ = s.DB.Exec(`
		UPDATE samples
		SET latest_lat = $1, latest_lng = $2, location_recorded_at = $3, updated_at = NOW()
		WHERE id = $4
	`, coord.Latitude, coord.Longitude, recordedAt, sampleID)

	s.AuditService.LogAudit(workerID, "worker", "worker.record_location", "assignment", assignmentID, true, map[string]interface{}{
		"latitude":   coord.Latitude,
		"longitude":  coord.Longitude,
		"sequence":   sequence,
		"recordedAt": models.FormatTime(recordedAt),
	})

	s.EventService.Broadcast("worker.location_recorded", "worker", workerID, map[string]interface{}{
		"workerId":   workerID,
		"assignmentId": assignmentID,
		"sampleId":   sampleID,
		"coordinate": coord,
		"recordedAt": models.FormatTime(recordedAt),
	})

	return nil
}

