package handlers

import (
	"database/sql"
	"encoding/json"
	"errors"
	"labsystem/internal/models"
	"labsystem/internal/services"
	"net/http"
	"time"
)

type AssignmentsHandoffsHandler struct {
	DB                *sql.DB
	AssignmentService *services.AssignmentService
	HandoffService    *services.HandoffService
	AuditService      *services.AuditService
}

func NewAssignmentsHandoffsHandler(db *sql.DB, assign *services.AssignmentService, handoff *services.HandoffService, audit *services.AuditService) *AssignmentsHandoffsHandler {
	return &AssignmentsHandoffsHandler{
		DB:                db,
		AssignmentService: assign,
		HandoffService:    handoff,
		AuditService:      audit,
	}
}

func (h *AssignmentsHandoffsHandler) AcceptAssignment(w http.ResponseWriter, r *http.Request) {
	actor := GetUserFromContext(r.Context())
	if actor == nil {
		Error(w, http.StatusUnauthorized, "Unauthorized", "unauthorized")
		return
	}

	var req struct {
		AssignmentID   string `json:"assignmentId"`
		IdempotencyKey string `json:"idempotencyKey"`
	}

	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		Error(w, http.StatusBadRequest, "Invalid JSON payload", "invalid_json")
		return
	}

	if req.IdempotencyKey != "" {
		if code, body, found := CheckIdempotency(h.DB, req.IdempotencyKey); found {
			w.Header().Set("Content-Type", "application/json")
			w.WriteHeader(code)
			w.Write(body)
			return
		}
	}

	if req.AssignmentID == "" {
		Error(w, http.StatusBadRequest, "Assignment ID required", "invalid_json")
		return
	}

	err := h.AssignmentService.AcceptAssignment(req.AssignmentID, actor.ID)
	if err != nil {
		if errors.Is(err, services.ErrIneligibleWorker) {
			Error(w, http.StatusForbidden, "Assignment is not offered to you", "ineligible_worker")
			return
		}
		if errors.Is(err, services.ErrAssignmentInactive) {
			Error(w, http.StatusConflict, "Assignment is no longer available", "assignment_inactive")
			return
		}
		Error(w, http.StatusBadRequest, err.Error(), "invalid_json")
		return
	}

	res := map[string]interface{}{
		"assignmentId": req.AssignmentID,
		"workerId":     actor.ID,
		"status":       "accepted",
	}

	SaveIdempotency(h.DB, req.IdempotencyKey, "accept_assignment", http.StatusCreated, res)
	JSON(w, http.StatusCreated, res)
}

func (h *AssignmentsHandoffsHandler) DeclineAssignment(w http.ResponseWriter, r *http.Request) {
	actor := GetUserFromContext(r.Context())
	if actor == nil {
		Error(w, http.StatusUnauthorized, "Unauthorized", "unauthorized")
		return
	}

	var req struct {
		AssignmentID   string  `json:"assignmentId"`
		Reason         *string `json:"reason"`
		DeclinedAt     *string `json:"declinedAt"`
		IdempotencyKey string  `json:"idempotencyKey"`
	}

	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		Error(w, http.StatusBadRequest, "Invalid JSON payload", "invalid_json")
		return
	}

	if req.IdempotencyKey != "" {
		if code, body, found := CheckIdempotency(h.DB, req.IdempotencyKey); found {
			w.Header().Set("Content-Type", "application/json")
			w.WriteHeader(code)
			w.Write(body)
			return
		}
	}

	if req.AssignmentID == "" {
		Error(w, http.StatusBadRequest, "Assignment ID required", "invalid_json")
		return
	}

	decTime := time.Now().UTC()
	if req.DeclinedAt != nil && *req.DeclinedAt != "" {
		if t, err := time.Parse(time.RFC3339, *req.DeclinedAt); err == nil {
			decTime = t
		}
	}

	reasonStr := ""
	if req.Reason != nil {
		reasonStr = *req.Reason
	}

	reofferedTo, err := h.AssignmentService.DeclineAssignment(req.AssignmentID, actor.ID, reasonStr, decTime)
	if err != nil {
		if errors.Is(err, services.ErrIneligibleWorker) {
			Error(w, http.StatusForbidden, "Assignment is not offered to you", "forbidden")
			return
		}
		if errors.Is(err, services.ErrOfferNotAvailable) {
			Error(w, http.StatusConflict, "Offer no longer available", "offer_not_available")
			return
		}
		Error(w, http.StatusBadRequest, err.Error(), "invalid_json")
		return
	}

	res := map[string]interface{}{
		"assignmentId": req.AssignmentID,
		"status":       "pending",
		"declinedBy":   actor.ID,
		"declinedAt":   models.FormatTime(decTime),
	}
	if reofferedTo != "" {
		res["reofferedTo"] = reofferedTo
	}

	SaveIdempotency(h.DB, req.IdempotencyKey, "decline_assignment", http.StatusCreated, res)
	JSON(w, http.StatusCreated, res)
}

func (h *AssignmentsHandoffsHandler) UpdateAssignmentProgress(w http.ResponseWriter, r *http.Request) {
	actor := GetUserFromContext(r.Context())
	if actor == nil {
		Error(w, http.StatusUnauthorized, "Unauthorized", "unauthorized")
		return
	}

	var req struct {
		AssignmentID   string `json:"assignmentId"`
		Status         string `json:"status"`
		OccurredAt     string `json:"occurredAt"`
		IdempotencyKey string `json:"idempotencyKey"`
	}

	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		Error(w, http.StatusBadRequest, "Invalid JSON payload", "invalid_json")
		return
	}

	if req.IdempotencyKey != "" {
		if code, body, found := CheckIdempotency(h.DB, req.IdempotencyKey); found {
			w.Header().Set("Content-Type", "application/json")
			w.WriteHeader(code)
			w.Write(body)
			return
		}
	}

	if req.AssignmentID == "" || req.Status == "" || req.OccurredAt == "" {
		Error(w, http.StatusBadRequest, "Missing required fields", "invalid_json")
		return
	}

	occAt, err := time.Parse(time.RFC3339, req.OccurredAt)
	if err != nil {
		Error(w, http.StatusBadRequest, "Invalid occurredAt format", "invalid_time")
		return
	}

	sampleID, err := h.AssignmentService.UpdateProgress(req.AssignmentID, actor.ID, req.Status, occAt)
	if err != nil {
		Error(w, http.StatusInternalServerError, err.Error(), "internal_error")
		return
	}

	res := map[string]interface{}{
		"assignmentId": req.AssignmentID,
		"sampleId":     sampleID,
		"status":       req.Status,
	}

	SaveIdempotency(h.DB, req.IdempotencyKey, "update_assignment_progress", http.StatusCreated, res)
	JSON(w, http.StatusCreated, res)
}

func (h *AssignmentsHandoffsHandler) RecordWorkerLocation(w http.ResponseWriter, r *http.Request) {
	actor := GetUserFromContext(r.Context())
	if actor == nil {
		Error(w, http.StatusUnauthorized, "Unauthorized", "unauthorized")
		return
	}

	var req struct {
		AssignmentID string            `json:"assignmentId"`
		Coordinate   models.Coordinate `json:"coordinate"`
		Sequence     int               `json:"sequence"`
		RecordedAt   string            `json:"recordedAt"`
	}

	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		Error(w, http.StatusBadRequest, "Invalid JSON payload", "invalid_json")
		return
	}

	if req.Coordinate.Latitude < -90 || req.Coordinate.Latitude > 90 || req.Coordinate.Longitude < -180 || req.Coordinate.Longitude > 180 {
		Error(w, http.StatusBadRequest, "Invalid coordinate", "invalid_coordinate")
		return
	}

	recAt, err := time.Parse(time.RFC3339, req.RecordedAt)
	if err != nil {
		Error(w, http.StatusBadRequest, "Invalid recordedAt format", "invalid_time")
		return
	}

	err = h.AssignmentService.RecordLocation(req.AssignmentID, actor.ID, req.Coordinate, req.Sequence, recAt)
	if err != nil {
		if errors.Is(err, services.ErrAssignmentInactive) {
			Error(w, http.StatusNotFound, "Assignment not found", "not_found")
			return
		}
		Error(w, http.StatusInternalServerError, err.Error(), "internal_error")
		return
	}

	res := map[string]interface{}{
		"assignmentId": req.AssignmentID,
		"coordinate":   req.Coordinate,
		"sequence":     req.Sequence,
		"recordedAt":   models.FormatTime(recAt),
	}

	JSON(w, http.StatusCreated, res)
}

func (h *AssignmentsHandoffsHandler) InitiateHandoff(w http.ResponseWriter, r *http.Request) {
	actor := GetUserFromContext(r.Context())
	if actor == nil {
		Error(w, http.StatusUnauthorized, "Unauthorized", "unauthorized")
		return
	}

	var req struct {
		SampleID         string `json:"sampleId"`
		FromAssignmentID string `json:"fromAssignmentId"`
		ToAssignmentID   string `json:"toAssignmentId"`
		ReceiverID       string `json:"receiverId"`
		InitiatedAt      string `json:"initiatedAt"`
		IdempotencyKey   string `json:"idempotencyKey"`
	}

	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		Error(w, http.StatusBadRequest, "Invalid JSON payload", "invalid_json")
		return
	}

	if req.IdempotencyKey != "" {
		if code, body, found := CheckIdempotency(h.DB, req.IdempotencyKey); found {
			w.Header().Set("Content-Type", "application/json")
			w.WriteHeader(code)
			w.Write(body)
			return
		}
	}

	if req.SampleID == "" || req.ReceiverID == "" || req.InitiatedAt == "" {
		Error(w, http.StatusBadRequest, "Missing required fields", "invalid_json")
		return
	}

	initAt, err := time.Parse(time.RFC3339, req.InitiatedAt)
	if err != nil {
		Error(w, http.StatusBadRequest, "Invalid initiatedAt format", "invalid_time")
		return
	}

	res, err := h.HandoffService.InitiateHandoff(req.SampleID, req.FromAssignmentID, req.ToAssignmentID, actor.ID, req.ReceiverID, initAt)
	if err != nil {
		if errors.Is(err, services.ErrNotCurrentHolder) {
			Error(w, http.StatusConflict, "You are not the current holder of this sample", "not_current_holder")
			return
		}
		if errors.Is(err, services.ErrPendingHandoffExists) {
			Error(w, http.StatusConflict, "A pending handoff already exists for this sample", "pending_handoff_exists")
			return
		}
		if errors.Is(err, services.ErrHandoffNotFound) {
			Error(w, http.StatusNotFound, "Sample not found", "not_found")
			return
		}
		Error(w, http.StatusBadRequest, err.Error(), "invalid_json")
		return
	}

	SaveIdempotency(h.DB, req.IdempotencyKey, "initiate_handoff", http.StatusCreated, res)
	JSON(w, http.StatusCreated, res)
}

func (h *AssignmentsHandoffsHandler) ConfirmHandoff(w http.ResponseWriter, r *http.Request) {
	actor := GetUserFromContext(r.Context())
	if actor == nil {
		Error(w, http.StatusUnauthorized, "Unauthorized", "unauthorized")
