	}

	if req.IdempotencyKey != "" {
		if code, body, found := CheckIdempotency(h.DB, req.IdempotencyKey); found {
			w.Header().Set("Content-Type", "application/json")
			w.WriteHeader(code)
			w.Write(body)
			return
		}
	}

	if req.HandoffID == "" || req.ConfirmationSide == "" || req.ConfirmedAt == "" {
		Error(w, http.StatusBadRequest, "Missing required fields", "invalid_json")
		return
	}

	confAt, err := time.Parse(time.RFC3339, req.ConfirmedAt)
	if err != nil {
		Error(w, http.StatusBadRequest, "Invalid confirmedAt format", "invalid_time")
		return
	}

	res, err := h.HandoffService.ConfirmHandoff(req.HandoffID, req.ConfirmationSide, actor.ID, confAt)
	if err != nil {
		if errors.Is(err, services.ErrHandoffNotFound) {
			Error(w, http.StatusNotFound, "Handoff not found", "not_found")
			return
		}
		Error(w, http.StatusBadRequest, err.Error(), "invalid_json")
		return
	}

	SaveIdempotency(h.DB, req.IdempotencyKey, "confirm_handoff", http.StatusCreated, res)
	JSON(w, http.StatusCreated, res)
