func (h *AssignmentsHandoffsHandler) RecordWorkerLocation(w http.ResponseWriter, r *http.Request) {
	actor := GetUserFromContext(r.Context())
	if actor == nil {
		Error(w, http.StatusUnauthorized, "Unauthorized", "unauthorized")
		return
	}

	var req struct {
		AssignmentID string            `json:"assignmentId"`
		Coordinate   models.Coordinate `json:"coordinate"`
		Sequence     int               `json:"sequence"`
		RecordedAt   string            `json:"recordedAt"`
	}

	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		Error(w, http.StatusBadRequest, "Invalid JSON payload", "invalid_json")
		return
	}

	if req.Coordinate.Latitude < -90 || req.Coordinate.Latitude > 90 || req.Coordinate.Longitude < -180 || req.Coordinate.Longitude > 180 {
