type AuditEventsHandler struct {
	DB           *sql.DB
	AuditService *services.AuditService
	EventService *services.EventService
}

func NewAuditEventsHandler(db *sql.DB, audit *services.AuditService, events *services.EventService) *AuditEventsHandler {
	return &AuditEventsHandler{
		DB:           db,
		AuditService: audit,
		EventService: events,
	}
}

func (h *AuditEventsHandler) SearchAuditTrail(w http.ResponseWriter, r *http.Request) {
	actor := GetUserFromContext(r.Context())
	if actor == nil {
		Error(w, http.StatusUnauthorized, "Unauthorized", "unauthorized")
		return
	}

	var req struct {
		Query      *string `json:"query"`
		ActorID    *string `json:"actorId"`
		EntityType *string `json:"entityType"`
		EntityID   *string `json:"entityId"`
		Action     *string `json:"action"`
		Role       *string `json:"role"`
		Success    *bool   `json:"success"`
		FromTime   *string `json:"fromTime"`
		ToTime     *string `json:"toTime"`
		Limit      *int    `json:"limit"`
		Offset     *int    `json:"offset"`
		Order      *string `json:"order"`
	}

	_ = json.NewDecoder(r.Body).Decode(&req)

	qStr := ""
	if req.Query != nil {
		qStr = *req.Query
	}
	limit := 50
	if req.Limit != nil {
		limit = *req.Limit
	}
	offset := 0
	if req.Offset != nil {
		offset = *req.Offset
	}
	order := "newest_first"
	if req.Order != nil {
		order = *req.Order
	}

	result, err := h.AuditService.SearchAudit(qStr, req.ActorID, req.EntityType, req.EntityID, req.Action, req.Role, req.Success, req.FromTime, req.ToTime, limit, offset, order)
	if err != nil {
		Error(w, http.StatusInternalServerError, err.Error(), "internal_error")
		return
	}

	JSON(w, http.StatusOK, result)
}

func (h *AuditEventsHandler) StreamRealtimeEvents(w http.ResponseWriter, r *http.Request) {
	acceptHeader := r.Header.Get("Accept")
	if strings.Contains(acceptHeader, "text/event-stream") {
		// Server-Sent Events mode
		flusher, ok := w.(http.Flusher)
		if !ok {
			http.Error(w, "Streaming unsupported", http.StatusInternalServerError)
			return
		}

		w.Header().Set("Content-Type", "text/event-stream")
		w.Header().Set("Cache-Control", "no-cache")
		w.Header().Set("Connection", "keep-alive")
		w.WriteHeader(http.StatusOK)
		flusher.Flush()

		ch := h.EventService.Subscribe()
		defer h.EventService.Unsubscribe(ch)

		notify := r.Context().Done()
		for {
			select {
			case <-notify:
				return
			case ev, ok := <-ch:
				if !ok {
					return
				}
				evJSON, _ := json.Marshal(ev)
				fmt.Fprintf(w, "data: %s\n\n", evJSON)
				flusher.Flush()
			}
		}
	}

	// Polling / standard GET mode
	afterStr := r.URL.Query().Get("after")
	var afterID int64
	if afterStr != "" {
		afterID, _ = strconv.ParseInt(afterStr, 10, 64)
	}

	limit := 100
	events, maxID, err := h.EventService.GetEventsAfter(afterID, limit)
	if err != nil {
		Error(w, http.StatusInternalServerError, err.Error(), "internal_error")
		return
	}

	JSON(w, http.StatusOK, map[string]interface{}{
		"events": events,
		"cursor": maxID,
	})
}

func (h *AuditEventsHandler) SystemReadiness(w http.ResponseWriter, r *http.Request) {
	err := h.DB.Ping()
	if err != nil {
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(http.StatusServiceUnavailable)
		_ = json.NewEncoder(w).Encode(map[string]string{
			"status": "starting",
		})
		return
	}

	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(http.StatusOK)
	_ = json.NewEncoder(w).Encode(map[string]string{
		"status": "ready",
	})
}

