	mapAssetDir := os.Getenv("OFFLINE_MAP_ASSET_DIR")
	if mapAssetDir == "" {
		mapAssetDir = "/opt/arena/map-assets"
	}
	if _, err := os.Stat(mapAssetDir); err == nil {
		fs := http.StripPrefix("/map-assets/", http.FileServer(http.Dir(mapAssetDir)))
		r.Get("/map-assets/*", func(w http.ResponseWriter, r *http.Request) {
			fs.ServeHTTP(w, r)
		})
	}

	// 3. API Routes
	r.Route("/api", func(api chi.Router) {
		// Public Auth
		api.Post("/authenticate-user", authH.AuthenticateUser)

		// Authenticated Routes
		api.Group(func(auth chi.Router) {
			auth.Use(func(next http.Handler) http.Handler {
				return http.HandlerFunc(handlers.RequireAuth(authSvc, next.ServeHTTP))
			})

			// User & Role
			auth.Post("/select-active-role", authH.SelectActiveRole)
			auth.Post("/create-user", authH.CreateUser)
			auth.Post("/update-user-access", authH.UpdateUserAccess)
			auth.Get("/read-user/{userId}", authH.ReadUser)
			auth.Get("/ui/bootstrap", authH.ReadUIBootstrap)

			// Serviceability
			auth.Post("/check-serviceability", svcH.CheckServiceability)
			auth.Post("/read-serviceability-snapshot", svcH.ReadServiceabilitySnapshot)

			// Requests & Samples
			auth.Post("/create-collection-request", reqSampleH.CreateCollectionRequest)
			auth.Post("/ingest-presealed-sample", reqSampleH.IngestPresealedSample)
			auth.Post("/collect-and-seal-sample", reqSampleH.CollectAndSealSample)
			auth.Get("/read-sample-state/{sampleId}", reqSampleH.ReadSampleState)
			auth.Post("/read-sample-lifecycle", reqSampleH.ReadSampleLifecycle)
			auth.Post("/record-handling-checkpoint", reqSampleH.RecordHandlingCheckpoint)

			// Assignments & Handoffs
			auth.Post("/accept-assignment", assignH.AcceptAssignment)
			auth.Post("/decline-assignment", assignH.DeclineAssignment)
			auth.Post("/update-assignment-progress", assignH.UpdateAssignmentProgress)
			auth.Post("/record-worker-location", assignH.RecordWorkerLocation)
			auth.Post("/initiate-handoff", assignH.InitiateHandoff)
			auth.Post("/confirm-handoff", assignH.ConfirmHandoff)
			auth.Post("/list-role-work", assignH.ListRoleWork)

			// Journeys & Disruptions
			auth.Post("/read-journey-plan", journeyH.ReadJourneyPlan)
			auth.Post("/edit-active-plan", journeyH.EditActivePlan)
			auth.Post("/split-journey", journeyH.SplitJourney)
			auth.Post("/merge-journeys", journeyH.MergeJourneys)
			auth.Post("/reroute-journey", journeyH.RerouteJourney)
			auth.Post("/cancel-journey", journeyH.CancelJourney)
			auth.Post("/report-disruption", journeyH.ReportDisruption)

			// Operations & Config
			auth.Post("/read-operations-state", opsH.ReadOperationsState)
			auth.Post("/configure-capacity", opsH.ConfigureCapacity)
			auth.Post("/configure-laboratory-acceptance", opsH.ConfigureLaboratoryAcceptance)
			auth.Post("/create-location", opsH.CreateLocation)
			auth.Post("/update-location", opsH.UpdateLocation)
			auth.Post("/set-location-status", opsH.SetLocationStatus)
			auth.Post("/set-location-function-status", opsH.SetLocationFunctionStatus)
			auth.Post("/create-connection", opsH.CreateConnection)
			auth.Post("/set-connection-status", opsH.SetConnectionStatus)
			auth.Post("/create-sample-type", opsH.CreateSampleType)
			auth.Post("/update-sample-type", opsH.UpdateSampleType)
			auth.Post("/set-worker-availability", opsH.SetWorkerAvailability)
			auth.Post("/confirm-laboratory-receipt", opsH.ConfirmLaboratoryReceipt)
			auth.Post("/record-laboratory-exception", opsH.RecordLaboratoryException)

			// Audit & Events
			auth.Post("/search-audit-trail", auditH.SearchAuditTrail)
			auth.Get("/events", auditH.StreamRealtimeEvents)
		})
	})

	// 4. Frontend Static Files & SPA Fallback
	frontendDir := os.Getenv("FRONTEND_DIST_DIR")
	if frontendDir == "" {
		frontendDir = "/workspace/frontend/dist"
	}

	r.Get("/*", func(w http.ResponseWriter, r *http.Request) {
		path := filepath.Join(frontendDir, filepath.Clean(r.URL.Path))
		info, err := os.Stat(path)
		if err == nil && !info.IsDir() {
			http.ServeFile(w, r, path)
			return
		}
		indexPath := filepath.Join(frontendDir, "index.html")
		if _, err := os.Stat(indexPath); err == nil {
			http.ServeFile(w, r, indexPath)
			return
		}
		http.NotFound(w, r)
	})

	port := *portFlag
	if p := os.Getenv("PORT"); p != "" {
		port = p
	}

	addr := fmt.Sprintf("0.0.0.0:%s", port)
	log.Printf("Server listening on %s", addr)
	if err := http.ListenAndServe(addr, r); err != nil {
		log.Fatalf("Server stopped: %v", err)
	}
}

