const API_BASE = '/api';

export function getToken(): string | null {
  return localStorage.getItem('session_token');
}

export function setToken(token: string): void {
  localStorage.setItem('session_token', token);
}

export function clearToken(): void {
  localStorage.removeItem('session_token');
}

export async function apiRequest<T = any>(
  endpoint: string,
  method: string = 'GET',
  body?: any,
  customHeaders?: Record<string, string>
): Promise<T> {
  const headers: Record<string, string> = {
    'Content-Type': 'application/json',
    ...customHeaders,
  };

  const token = getToken();
  if (token) {
    headers['Authorization'] = `Bearer ${token}`;
  }

  const options: RequestInit = {
    method,
    headers,
  };

  if (body !== undefined && method !== 'GET') {
    options.body = JSON.stringify(body);
  }

  const res = await fetch(`${API_BASE}${endpoint}`, options);

  let json: any = null;
  const text = await res.text();
  if (text) {
    try {
      json = JSON.parse(text);
    } catch {
      // not json
    }
  }

  if (!res.ok) {
    const errorMsg = json?.error || `Request failed with status ${res.status}`;
    const errorCode = json?.code || 'request_failed';
    const err = new Error(errorMsg);
    (err as any).code = errorCode;
    (err as any).status = res.status;
    throw err;
  }

  return json?.data !== undefined ? json.data : json;
}

// API methods
export const api = {
  // Auth
  login: (username: string, password: string) =>
    apiRequest('/authenticate-user', 'POST', { username, password }),
  selectRole: (role: string) =>
    apiRequest('/select-active-role', 'POST', { role }),
  getBootstrap: () =>
    apiRequest('/ui/bootstrap', 'GET'),
  createUser: (userData: any) =>
    apiRequest('/create-user', 'POST', userData),
  updateUserAccess: (accessData: any) =>
    apiRequest('/update-user-access', 'POST', accessData),
  getUser: (userId: string) =>
    apiRequest(`/read-user/${userId}`, 'GET'),

  // Serviceability
  checkServiceability: (data: any) =>
    apiRequest('/check-serviceability', 'POST', data),
  getServiceabilitySnapshot: () =>
    apiRequest('/read-serviceability-snapshot', 'POST', {}),

  // Requests & Samples
  createCollectionRequest: (data: any) =>
    apiRequest('/create-collection-request', 'POST', data),
  ingestPresealedSample: (data: any) =>
    apiRequest('/ingest-presealed-sample', 'POST', data),
  collectAndSealSample: (data: any) =>
    apiRequest('/collect-and-seal-sample', 'POST', data),
  getSampleState: (sampleId: string) =>
    apiRequest(`/read-sample-state/${sampleId}`, 'GET'),
  getSampleLifecycle: (sampleId: string) =>
    apiRequest('/read-sample-lifecycle', 'POST', { sampleId }),
  recordHandlingCheckpoint: (data: any) =>
    apiRequest('/record-handling-checkpoint', 'POST', data),

  // Assignments & Handoffs
  listRoleWork: (role?: string, status?: string) =>
    apiRequest('/list-role-work', 'POST', { role, status }),
  acceptAssignment: (assignmentId: string, idempotencyKey: string = crypto.randomUUID()) =>
    apiRequest('/accept-assignment', 'POST', { assignmentId, idempotencyKey }),
  declineAssignment: (assignmentId: string, reason?: string, idempotencyKey: string = crypto.randomUUID()) =>
    apiRequest('/decline-assignment', 'POST', { assignmentId, reason, idempotencyKey, declinedAt: new Date().toISOString() }),
  updateAssignmentProgress: (assignmentId: string, status: string, idempotencyKey: string = crypto.randomUUID()) =>
    apiRequest('/update-assignment-progress', 'POST', { assignmentId, status, occurredAt: new Date().toISOString(), idempotencyKey }),
  recordWorkerLocation: (assignmentId: string, coordinate: { latitude: number; longitude: number }, sequence: number) =>
    apiRequest('/record-worker-location', 'POST', { assignmentId, coordinate, sequence, recordedAt: new Date().toISOString() }),
  initiateHandoff: (data: any) =>
    apiRequest('/initiate-handoff', 'POST', { ...data, idempotencyKey: data.idempotencyKey || crypto.randomUUID(), initiatedAt: new Date().toISOString() }),
  confirmHandoff: (handoffId: string, confirmationSide: 'sender' | 'receiver', idempotencyKey: string = crypto.randomUUID()) =>
    apiRequest('/confirm-handoff', 'POST', { handoffId, confirmationSide, confirmedAt: new Date().toISOString(), idempotencyKey }),

  // Journeys & Disruptions
  getJourneyPlan: (journeyId: string) =>
    apiRequest('/read-journey-plan', 'POST', { journeyId }),
  editActivePlan: (data: any) =>
    apiRequest('/edit-active-plan', 'POST', { ...data, idempotencyKey: data.idempotencyKey || crypto.randomUUID() }),
  splitJourney: (data: any) =>
    apiRequest('/split-journey', 'POST', { ...data, idempotencyKey: data.idempotencyKey || crypto.randomUUID() }),
  mergeJourneys: (data: any) =>
    apiRequest('/merge-journeys', 'POST', { ...data, idempotencyKey: data.idempotencyKey || crypto.randomUUID() }),
  rerouteJourney: (journeyId: string, expectedPlanVersion: number, reason?: string, idempotencyKey: string = crypto.randomUUID()) =>
    apiRequest('/reroute-journey', 'POST', { journeyId, expectedPlanVersion, reason, idempotencyKey }),
  cancelJourney: (journeyId: string, expectedPlanVersion: number, reason?: string, idempotencyKey: string = crypto.randomUUID()) =>
    apiRequest('/cancel-journey', 'POST', { journeyId, expectedPlanVersion, reason, idempotencyKey }),
  reportDisruption: (data: any) =>
    apiRequest('/report-disruption', 'POST', { ...data, idempotencyKey: data.idempotencyKey || crypto.randomUUID(), occurredAt: new Date().toISOString() }),

  // Operations & Config
  getOperationsState: () =>
    apiRequest('/read-operations-state', 'POST', {}),
  configureCapacity: (resourceId: string, capacityUnits: number, cooledCapacityUnits: number = 0) =>
    apiRequest('/configure-capacity', 'POST', { resourceId, capacityUnits, cooledCapacityUnits }),
  configureLaboratoryAcceptance: (laboratoryId: string, sampleTypeId: string, accepts: boolean) =>
    apiRequest('/configure-laboratory-acceptance', 'POST', { laboratoryId, sampleTypeId, accepts }),
  createLocation: (data: any) =>
    apiRequest('/create-location', 'POST', data),
  updateLocation: (data: any) =>
    apiRequest('/update-location', 'POST', data),
  setLocationStatus: (locationId: string, active: boolean) =>
    apiRequest('/set-location-status', 'POST', { locationId, active }),
  setLocationFunctionStatus: (locationId: string, func: string, active: boolean) =>
    apiRequest('/set-location-function-status', 'POST', { locationId, function: func, active }),
  createConnection: (data: any) =>
    apiRequest('/create-connection', 'POST', data),
  setConnectionStatus: (connectionId: string, active: boolean) =>
    apiRequest('/set-connection-status', 'POST', { connectionId, active }),
  createSampleType: (data: any) =>
    apiRequest('/create-sample-type', 'POST', data),
  updateSampleType: (data: any) =>
    apiRequest('/update-sample-type', 'POST', data),
  setWorkerAvailability: (workerId: string, available: boolean, capacityUnits: number) =>
    apiRequest('/set-worker-availability', 'POST', { workerId, available, capacityUnits }),
  confirmLaboratoryReceipt: (sampleId: string, laboratoryId: string, idempotencyKey: string = crypto.randomUUID()) =>
    apiRequest('/confirm-laboratory-receipt', 'POST', { sampleId, laboratoryId, receivedAt: new Date().toISOString(), idempotencyKey }),
  recordLaboratoryException: (sampleId: string, laboratoryId: string, reason: string, idempotencyKey: string = crypto.randomUUID()) =>
    apiRequest('/record-laboratory-exception', 'POST', { sampleId, laboratoryId, reason, observedAt: new Date().toISOString(), idempotencyKey }),

  // Audit
  searchAuditTrail: (filter: any) =>
    apiRequest('/search-audit-trail', 'POST', filter),
};

