import React from 'react';
import { api } from '../api/client';
import { UserCheck } from 'lucide-react';

interface RoleSwitcherProps {
  roles: string[];
  activeRole: string;
  onRoleChanged: (newRole: string) => void;
}

const roleDisplayNames: Record<string, string> = {
  administrator: 'Administrator',
  dispatcher: 'Dispatcher',
  requester: 'Requester',
  collection_professional: 'Collection Professional',
  delivery_partner: 'Relay Courier',
  node_handler: 'Node Handler',
  laboratory_team: 'Lab Intake Operator',
};

export const RoleSwitcher: React.FC<RoleSwitcherProps> = ({ roles, activeRole, onRoleChanged }) => {
  const [switching, setSwitching] = React.useState(false);
  const [error, setError] = React.useState<string | null>(null);

  const handleSelect = async (newRole: string) => {
    if (newRole === activeRole || switching) return;
    setSwitching(true);
    setError(null);
    try {
      const res = await api.selectRole(newRole);
      onRoleChanged(res.activeRole || newRole);
    } catch (err: any) {
      setError(err.message || 'Failed to switch role');
    } finally {
      setSwitching(false);
    }
  };

  return (
    <div className="flex items-center space-x-2">
      <label htmlFor="role-select" className="text-xs font-semibold uppercase text-slate-500 flex items-center">
        <UserCheck className="w-3.5 h-3.5 mr-1" />
        Active Role:
      </label>
      <select
        id="role-select"
        aria-label="Select active role"
        value={activeRole}
        onChange={(e) => handleSelect(e.target.value)}
        disabled={switching}
        className="bg-white border border-slate-300 text-slate-800 text-sm rounded-md px-2.5 py-1.5 focus:outline-none focus:ring-2 focus:ring-blue-500 font-medium cursor-pointer shadow-sm disabled:opacity-50"
      >
        {roles.map((r) => (
          <option key={r} value={r}>
            {roleDisplayNames[r] || r}
          </option>
        ))}
      </select>
      {error && <span className="text-xs text-red-600 ml-1">{error}</span>}
    </div>
  );
};

