import React from 'react';
import { RoleSwitcher } from './RoleSwitcher';
import { LogOut, Activity, MapPin, ShieldAlert, Settings } from 'lucide-react';

interface NavbarProps {
  user: {
    userId: string;
    username: string;
    fullName?: string;
    roles: string[];
    activeRole: string;
  };
  activeTab: string;
  onTabChange: (tab: string) => void;
  onRoleChanged: (newRole: string) => void;
  onSignOut: () => void;
}

export const Navbar: React.FC<NavbarProps> = ({
  user,
  activeTab,
  onTabChange,
  onRoleChanged,
  onSignOut,
}) => {
  const isAdminOrDispatcher = user.activeRole === 'administrator' || user.activeRole === 'dispatcher';
  const isAdmin = user.activeRole === 'administrator';

  return (
    <header className="bg-white border-b border-slate-200 sticky top-0 z-30 shadow-sm">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex justify-between h-16 items-center">
          {/* Brand */}
          <div className="flex items-center space-x-3">
            <div className="w-9 h-9 rounded-lg bg-blue-600 flex items-center justify-center text-white font-bold text-lg shadow">
              <Activity className="w-5 h-5" />
            </div>
            <div>
              <span className="text-base font-bold text-slate-900 tracking-tight block">
                Lab Sample Delivery Network
              </span>
              <span className="text-xs text-slate-500 block">Bangalore Clinical Logistics</span>
            </div>
          </div>

          {/* Navigation Tabs */}
          <nav className="hidden md:flex space-x-1">
            <button
              onClick={() => onTabChange('dashboard')}
              className={`px-3.5 py-2 rounded-md text-sm font-medium transition-colors ${
                activeTab === 'dashboard'
                  ? 'bg-blue-50 text-blue-700'
                  : 'text-slate-600 hover:text-slate-900 hover:bg-slate-50'
              }`}
            >
              Dashboard
            </button>

            {isAdminOrDispatcher && (
              <button
                onClick={() => onTabChange('map')}
                className={`px-3.5 py-2 rounded-md text-sm font-medium transition-colors flex items-center ${
                  activeTab === 'map'
                    ? 'bg-blue-50 text-blue-700'
                    : 'text-slate-600 hover:text-slate-900 hover:bg-slate-50'
                }`}
              >
                <MapPin className="w-4 h-4 mr-1.5" />
                Live Map
              </button>
            )}

            {isAdminOrDispatcher && (
              <button
                onClick={() => onTabChange('audit')}
                className={`px-3.5 py-2 rounded-md text-sm font-medium transition-colors flex items-center ${
                  activeTab === 'audit'
                    ? 'bg-blue-50 text-blue-700'
                    : 'text-slate-600 hover:text-slate-900 hover:bg-slate-50'
                }`}
              >
                <ShieldAlert className="w-4 h-4 mr-1.5" />
                Audit Trail
              </button>
            )}

            {isAdmin && (
              <button
                onClick={() => onTabChange('admin')}
                className={`px-3.5 py-2 rounded-md text-sm font-medium transition-colors flex items-center ${
                  activeTab === 'admin'
                    ? 'bg-blue-50 text-blue-700'
                    : 'text-slate-600 hover:text-slate-900 hover:bg-slate-50'
                }`}
              >
                <Settings className="w-4 h-4 mr-1.5" />
                Management
              </button>
            )}
          </nav>

          {/* Controls: Role Switcher, User Badge, Sign Out */}
          <div className="flex items-center space-x-4">
            <RoleSwitcher
              roles={user.roles}
              activeRole={user.activeRole}
              onRoleChanged={onRoleChanged}
            />

            <div className="hidden sm:flex flex-col text-right">
              <span className="text-xs font-semibold text-slate-800">{user.fullName || user.username}</span>
              <span className="text-[10px] text-slate-400 uppercase tracking-wider">{user.username}</span>
            </div>

            <button
              onClick={onSignOut}
              aria-label="Sign out"
              className="inline-flex items-center px-3 py-1.5 border border-slate-300 text-xs font-medium rounded-md text-slate-700 bg-white hover:bg-slate-50 hover:text-red-600 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-red-500 shadow-sm transition-colors"
            >
              <LogOut className="w-3.5 h-3.5 mr-1" />
              Sign Out
            </button>
          </div>
        </div>
      </div>
    </header>
  );
};

