import React, { useEffect, useRef } from 'react';
import maplibregl from 'maplibre-gl';
import * as pmtiles from 'pmtiles';
import { OperationsLocation, OperationsConnection } from '../types';

interface MapViewProps {
  locations?: OperationsLocation[];
  connections?: OperationsConnection[];
  workers?: Array<{
    workerId: string;
    fullName?: string;
    latestLocation?: { latitude: number; longitude: number };
    locationStale?: boolean;
    available?: boolean;
  }>;
  samples?: Array<{
    sampleId: string;
    latestLocation?: { latitude: number; longitude: number };
    status: string;
    locationStale?: boolean;
  }>;
}

let protocolRegistered = false;

export const MapView: React.FC<MapViewProps> = ({
  locations = [],
  connections = [],
  workers = [],
  samples = [],
}) => {
  const mapContainer = useRef<HTMLDivElement>(null);
  const mapInstance = useRef<maplibregl.Map | null>(null);
  const markersRef = useRef<maplibregl.Marker[]>([]);

  useEffect(() => {
    if (!protocolRegistered) {
      const protocol = new pmtiles.Protocol();
      maplibregl.addProtocol('pmtiles', protocol.tile);
      protocolRegistered = true;
    }

    if (!mapContainer.current || mapInstance.current) return;

    try {
      const map = new maplibregl.Map({
        container: mapContainer.current,
        style: '/map-assets/style.json',
        center: [77.5946, 12.9716],
        zoom: 11,
      });

      map.addControl(new maplibregl.NavigationControl(), 'top-right');
      mapInstance.current = map;
    } catch (e) {
      console.error('Error initializing map:', e);
    }

    return () => {
      markersRef.current.forEach((m) => m.remove());
      markersRef.current = [];
      if (mapInstance.current) {
        mapInstance.current.remove();
        mapInstance.current = null;
      }
    };
  }, []);

  // Update markers when props change
  useEffect(() => {
    const map = mapInstance.current;
    if (!map) return;

    // Clear old markers
    markersRef.current.forEach((m) => m.remove());
    markersRef.current = [];

    // Add Locations
    locations.forEach((loc) => {
      if (!loc.coordinate) return;
      const el = document.createElement('div');
      el.className = 'custom-map-marker';

      let bgColor = 'bg-blue-600';
      let iconText = 'N';
      if (loc.functions?.laboratory) {
        bgColor = 'bg-purple-600';
        iconText = 'Lab';
      } else if (loc.functions?.hub) {
        bgColor = 'bg-amber-600';
        iconText = 'Hub';
      } else if (loc.functions?.collection_point) {
        bgColor = 'bg-emerald-600';
        iconText = 'Col';
      }

      el.innerHTML = `
        <div class="${bgColor} text-white text-[10px] font-bold px-1.5 py-0.5 rounded shadow flex items-center justify-center border border-white cursor-pointer hover:scale-110 transition-transform">
          ${iconText}
        </div>
      `;

      const popup = new maplibregl.Popup({ offset: 15 }).setHTML(`
        <div class="p-1 text-slate-800 text-xs">
          <div class="font-bold text-sm text-slate-900">${loc.name}</div>
          <div class="text-slate-500 mt-1">Status: <span class="${loc.active ? 'text-emerald-600 font-semibold' : 'text-red-600 font-semibold'}">${loc.active ? 'Active' : 'Inactive'}</span></div>
          <div class="text-slate-500">Coverage: ${loc.coverageKm} km</div>
          <div class="text-slate-500">Handling Time: ${loc.handlingMinutes} mins</div>
          ${loc.capacity ? `<div class="text-slate-600 font-medium mt-1">Capacity: ${loc.capacity.availableUnits}/${loc.capacity.capacityUnits} (Cooled: ${loc.capacity.cooledAvailableUnits}/${loc.capacity.cooledCapacityUnits})</div>` : ''}
        </div>
      `);

      const marker = new maplibregl.Marker({ element: el })
        .setLngLat([loc.coordinate.longitude, loc.coordinate.latitude])
        .setPopup(popup)
        .addTo(map);

      markersRef.current.push(marker);
    });

    // Add Workers
    workers.forEach((w) => {
      if (!w.latestLocation) return;
      const el = document.createElement('div');
      const isFresh = !w.locationStale;
      const ringColor = isFresh ? 'ring-emerald-500 ring-2' : 'ring-slate-400 ring-1 opacity-70';

      el.innerHTML = `
        <div class="w-6 h-6 rounded-full bg-slate-900 text-white text-[10px] flex items-center justify-center font-bold shadow-md ${ringColor} cursor-pointer hover:scale-110 transition-transform">
          👷
        </div>
      `;

      const popup = new maplibregl.Popup({ offset: 15 }).setHTML(`
        <div class="p-1 text-slate-800 text-xs">
          <div class="font-bold text-sm text-slate-900">${w.fullName || w.workerId}</div>
          <div class="text-slate-500 mt-0.5">Location: <span class="${isFresh ? 'text-emerald-600 font-medium' : 'text-amber-600 font-medium'}">${isFresh ? 'Fresh' : 'Stale'}</span></div>
          <div class="text-slate-500">Status: ${w.available ? 'Available' : 'Unavailable'}</div>
        </div>
      `);

      const marker = new maplibregl.Marker({ element: el })
        .setLngLat([w.latestLocation.longitude, w.latestLocation.latitude])
        .setPopup(popup)
        .addTo(map);

      markersRef.current.push(marker);
    });

    // Add Samples
    samples.forEach((s) => {
      if (!s.latestLocation) return;
      const el = document.createElement('div');
      const isFresh = !s.locationStale;

      el.innerHTML = `
        <div class="w-5 h-5 rounded-full bg-rose-600 text-white text-[9px] flex items-center justify-center font-bold shadow ${isFresh ? 'ring-2 ring-rose-400' : 'opacity-60'} cursor-pointer hover:scale-110 transition-transform">
          🧪
        </div>
      `;

      const popup = new maplibregl.Popup({ offset: 15 }).setHTML(`
        <div class="p-1 text-slate-800 text-xs">
          <div class="font-bold text-xs text-slate-900">Sample ${s.sampleId.slice(0, 8)}</div>
          <div class="text-slate-500 mt-0.5">Status: <span class="font-semibold text-blue-600">${s.status}</span></div>
          <div class="text-slate-500">Location: <span class="${isFresh ? 'text-emerald-600' : 'text-amber-600'}">${isFresh ? 'Fresh' : 'Stale'}</span></div>
        </div>
      `);

      const marker = new maplibregl.Marker({ element: el })
        .setLngLat([s.latestLocation.longitude, s.latestLocation.latitude])
        .setPopup(popup)
        .addTo(map);

      markersRef.current.push(marker);
    });
  }, [locations, connections, workers, samples]);

  return (
    <div className="relative w-full h-[550px] bg-slate-100 rounded-xl overflow-hidden border border-slate-200 shadow-sm">
      <div ref={mapContainer} className="w-full h-full" />
      <div className="absolute bottom-3 left-3 bg-white/90 backdrop-blur px-3 py-2 rounded-lg shadow-sm border border-slate-200 text-xs flex items-center space-x-4">
        <span className="flex items-center font-medium text-slate-700">
          <span className="w-2.5 h-2.5 rounded-full bg-emerald-600 inline-block mr-1.5" /> Collection Point
        </span>
        <span className="flex items-center font-medium text-slate-700">
          <span className="w-2.5 h-2.5 rounded-full bg-amber-600 inline-block mr-1.5" /> Hub
        </span>
        <span className="flex items-center font-medium text-slate-700">
          <span className="w-2.5 h-2.5 rounded-full bg-purple-600 inline-block mr-1.5" /> Laboratory
        </span>
        <span className="flex items-center font-medium text-slate-700">
          <span className="w-2.5 h-2.5 rounded-full bg-slate-900 ring-2 ring-emerald-500 inline-block mr-1.5" /> Live Worker
        </span>
      </div>
    </div>
  );
};

