import React from 'react';
import { TimelineEntry } from '../types';
import { Clock, CheckCircle2, AlertCircle } from 'lucide-react';

interface TimelineViewProps {
  timeline: TimelineEntry[];
  title?: string;
}

export const TimelineView: React.FC<TimelineViewProps> = ({ timeline, title = 'Status Timeline' }) => {
  if (!timeline || timeline.length === 0) {
    return (
      <div className="text-xs text-slate-400 italic py-2">No history events recorded yet.</div>
    );
  }

  return (
    <div className="space-y-3">
      {title && <h4 className="text-xs font-bold uppercase tracking-wider text-slate-500">{title}</h4>}
      <div className="relative border-l border-slate-200 ml-3 pl-4 space-y-4">
        {timeline.map((entry) => (
          <div key={entry.eventId} className="relative group">
            {/* Timeline bullet */}
            <div className="absolute -left-[23px] top-1 w-3.5 h-3.5 rounded-full bg-white border-2 border-blue-500 flex items-center justify-center">
              <span className="w-1.5 h-1.5 rounded-full bg-blue-600" />
            </div>

            <div className="bg-slate-50 p-2.5 rounded-lg border border-slate-200/80 text-xs">
              <div className="flex items-center justify-between font-semibold text-slate-800">
                <span className="capitalize">{entry.action.replace(/[._]/g, ' ')}</span>
                <span className="text-[11px] font-normal text-slate-400 flex items-center">
                  <Clock className="w-3 h-3 mr-1" />
                  {new Date(entry.occurredAt).toLocaleString()}
                </span>
              </div>

              <div className="text-slate-500 mt-1 flex items-center space-x-2 text-[11px]">
                <span>Role: <span className="font-medium text-slate-700">{entry.role}</span></span>
                <span>•</span>
                <span className="flex items-center">
                  {entry.success ? (
                    <span className="text-emerald-600 flex items-center font-medium">
                      <CheckCircle2 className="w-3 h-3 mr-0.5" /> Successful
                    </span>
                  ) : (
                    <span className="text-rose-600 flex items-center font-medium">
                      <AlertCircle className="w-3 h-3 mr-0.5" /> Exception
                    </span>
                  )}
                </span>
              </div>

              {entry.details && Object.keys(entry.details).length > 0 && (
                <div className="mt-1.5 bg-white p-1.5 rounded border border-slate-100 font-mono text-[10px] text-slate-600 overflow-x-auto">
                  {JSON.stringify(entry.details, null, 2)}
                </div>
              )}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

