import React, { useState } from 'react';
import { api } from '../api/client';
import { CheckCircle, AlertTriangle, Search, Loader2 } from 'lucide-react';

interface ServiceabilityCheckerProps {
  sampleTypes: Array<{ sampleTypeId: string; name: string }>;
}

export const ServiceabilityChecker: React.FC<ServiceabilityCheckerProps> = ({ sampleTypes }) => {
  const [lat, setLat] = useState('12.9716');
  const [lng, setLng] = useState('77.5946');
  const [sampleTypeId, setSampleTypeId] = useState(sampleTypes[0]?.sampleTypeId || '');
  const [deliveryDeadline, setDeliveryDeadline] = useState(
    new Date(Date.now() + 4 * 3600 * 1000).toISOString().slice(0, 16)
  );

  const [checking, setChecking] = useState(false);
  const [result, setResult] = useState<any>(null);
  const [error, setError] = useState<string | null>(null);

  React.useEffect(() => {
    if (sampleTypes.length > 0 && !sampleTypeId) {
      setSampleTypeId(sampleTypes[0].sampleTypeId);
    }
  }, [sampleTypes, sampleTypeId]);

  const handleCheck = async (e: React.FormEvent) => {
    e.preventDefault();
    setChecking(true);
    setError(null);
    setResult(null);

    try {
      const res = await api.checkServiceability({
        origin: {
          latitude: parseFloat(lat),
          longitude: parseFloat(lng),
        },
        originType: 'home',
        sampleTypeId: sampleTypeId || (sampleTypes[0]?.sampleTypeId ?? ''),
        requestedAt: new Date().toISOString(),
        deliveryDeadline: new Date(deliveryDeadline).toISOString(),
      });
      setResult(res);
    } catch (err: any) {
      setError(err.message || 'Serviceability check failed');
    } finally {
      setChecking(false);
    }
  };

  return (
    <div className="bg-white p-5 rounded-xl border border-slate-200 shadow-sm">
      <div className="flex items-center space-x-2 border-b border-slate-100 pb-3 mb-4">
        <Search className="w-5 h-5 text-blue-600" />
        <h3 className="text-base font-bold text-slate-800">Check Serviceability (Dry Run)</h3>
      </div>
      <p className="text-xs text-slate-500 mb-4">
        Verify if an origin location, sample type, and deadline can be served by the network without creating any request or reservation.
      </p>

      <form onSubmit={handleCheck} className="space-y-3.5">
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
          <div>
            <label htmlFor="check-lat" className="block text-xs font-semibold text-slate-600 mb-1">
              Latitude
            </label>
            <input
              id="check-lat"
              type="number"
              step="any"
              value={lat}
              onChange={(e) => setLat(e.target.value)}
              required
              className="w-full text-xs px-3 py-2 border border-slate-300 rounded-md focus:ring-2 focus:ring-blue-500 focus:outline-none"
            />
          </div>
          <div>
            <label htmlFor="check-lng" className="block text-xs font-semibold text-slate-600 mb-1">
              Longitude
            </label>
            <input
              id="check-lng"
              type="number"
              step="any"
              value={lng}
              onChange={(e) => setLng(e.target.value)}
              required
              className="w-full text-xs px-3 py-2 border border-slate-300 rounded-md focus:ring-2 focus:ring-blue-500 focus:outline-none"
            />
          </div>
        </div>

        <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
          <div>
            <label htmlFor="check-sample-type" className="block text-xs font-semibold text-slate-600 mb-1">
              Sample Type
            </label>
            <select
              id="check-sample-type"
              value={sampleTypeId}
              onChange={(e) => setSampleTypeId(e.target.value)}
              className="w-full text-xs px-3 py-2 border border-slate-300 rounded-md focus:ring-2 focus:ring-blue-500 focus:outline-none bg-white"
            >
              {sampleTypes.map((st) => (
                <option key={st.sampleTypeId} value={st.sampleTypeId}>
                  {st.name}
                </option>
              ))}
            </select>
          </div>
          <div>
            <label htmlFor="check-deadline" className="block text-xs font-semibold text-slate-600 mb-1">
              Delivery Deadline
            </label>
            <input
              id="check-deadline"
              type="datetime-local"
              value={deliveryDeadline}
              onChange={(e) => setDeliveryDeadline(e.target.value)}
              required
              className="w-full text-xs px-3 py-2 border border-slate-300 rounded-md focus:ring-2 focus:ring-blue-500 focus:outline-none"
            />
          </div>
        </div>

        <button
          type="submit"
          disabled={checking}
          className="w-full flex items-center justify-center py-2 px-4 border border-transparent rounded-md shadow-sm text-xs font-semibold text-white bg-blue-600 hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-500 transition-colors disabled:opacity-50"
        >
          {checking ? (
            <>
              <Loader2 className="w-3.5 h-3.5 mr-1.5 animate-spin" />
              Calculating Serviceability...
            </>
          ) : (
            'Run Serviceability Check'
          )}
        </button>
      </form>

      {error && (
        <div className="mt-4 p-3 bg-red-50 border border-red-200 rounded-lg text-xs text-red-700 flex items-start space-x-2">
          <AlertTriangle className="w-4 h-4 text-red-600 flex-shrink-0 mt-0.5" />
          <span>{error}</span>
        </div>
      )}

      {result && (
        <div
          className={`mt-4 p-4 rounded-lg border text-xs ${
            result.serviceable
              ? 'bg-emerald-50 border-emerald-200 text-emerald-900'
              : 'bg-amber-50 border-amber-200 text-amber-900'
          }`}
        >
          <div className="flex items-center space-x-2 font-bold text-sm">
            {result.serviceable ? (
              <>
                <CheckCircle className="w-5 h-5 text-emerald-600" />
                <span>Serviceable</span>
              </>
            ) : (
              <>
                <AlertTriangle className="w-5 h-5 text-amber-600" />
                <span>Unserviceable</span>
              </>
            )}
          </div>
          <div className="mt-2 space-y-1 text-xs">
            <div>
              <span className="font-semibold">Reason:</span> {result.reason}
            </div>
            {result.estimatedArrivalAt && (
              <div>
                <span className="font-semibold">Estimated Lab Arrival:</span>{' '}
                {new Date(result.estimatedArrivalAt).toLocaleString()}
              </div>
            )}
            {result.serviceabilityVersion && (
              <div>
                <span className="font-semibold">Calculation Version:</span> v{result.serviceabilityVersion}
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  );
};

