import React, { useState } from 'react';
import { api } from '../api/client';
import { PlusCircle, AlertCircle, CheckCircle, Loader2 } from 'lucide-react';
import { SampleType } from '../types';

interface CollectionRequestFormProps {
  sampleTypes: SampleType[];
  onRequestCreated: () => void;
}

export const CollectionRequestForm: React.FC<CollectionRequestFormProps> = ({
  sampleTypes,
  onRequestCreated,
}) => {
  const [lat, setLat] = useState('12.9716');
  const [lng, setLng] = useState('77.5946');
  const [originType, setOriginType] = useState('home');
  const [sampleTypeId, setSampleTypeId] = useState(sampleTypes[0]?.sampleTypeId || '');

  const now = new Date();
  const [earliestCol, setEarliestCol] = useState(new Date(now.getTime() + 15 * 60000).toISOString().slice(0, 16));
  const [latestCol, setLatestCol] = useState(new Date(now.getTime() + 2 * 3600000).toISOString().slice(0, 16));
  const [deadline, setDeadline] = useState(new Date(now.getTime() + 5 * 3600000).toISOString().slice(0, 16));

  const [containerType, setContainerType] = useState('standard_ambient');
  const [tempMin, setTempMin] = useState(15.0);
  const [tempMax, setTempMax] = useState(25.0);

  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState<string | null>(null);

  React.useEffect(() => {
    if (sampleTypes.length > 0 && !sampleTypeId) {
      setSampleTypeId(sampleTypes[0].sampleTypeId);
      updateSampleTypeDefaults(sampleTypes[0]);
    }
  }, [sampleTypes, sampleTypeId]);

  const updateSampleTypeDefaults = (st: SampleType) => {
    setContainerType(st.containerType || 'standard_ambient');
    setTempMin(st.temperatureMinC ?? 15.0);
    setTempMax(st.temperatureMaxC ?? 25.0);
  };

  const handleSampleTypeChange = (id: string) => {
    setSampleTypeId(id);
    const selected = sampleTypes.find((s) => s.sampleTypeId === id);
    if (selected) {
      updateSampleTypeDefaults(selected);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    setSuccess(null);

    // Client-side validations
    const numLat = parseFloat(lat);
    const numLng = parseFloat(lng);
    if (isNaN(numLat) || numLat < -90 || numLat > 90) {
      setError('Latitude must be between -90 and 90');
      return;
    }
    if (isNaN(numLng) || numLng < -180 || numLng > 180) {
      setError('Longitude must be between -180 and 180');
      return;
    }

    const earDate = new Date(earliestCol);
    const latDate = new Date(latestCol);
    const deadDate = new Date(deadline);

    if (latDate < earDate) {
      setError('Latest collection time cannot be earlier than earliest collection time');
      return;
    }
    if (deadDate < latDate) {
      setError('Delivery deadline must be after the collection window');
      return;
    }
    if (tempMin > tempMax) {
      setError('Minimum temperature cannot exceed maximum temperature');
      return;
    }

    setSubmitting(true);
    try {
      const res = await api.createCollectionRequest({
        origin: {
          latitude: numLat,
          longitude: numLng,
        },
        originType,
        sampleTypeId,
        requestedAt: new Date().toISOString(),
        earliestCollectionAt: earDate.toISOString(),
        latestCollectionAt: latDate.toISOString(),
        deliveryDeadline: deadDate.toISOString(),
        containerType,
        temperatureMinC: tempMin,
        temperatureMaxC: tempMax,
        incompatibleSampleTypes: [],
      });

      setSuccess(`Request created successfully! Request ID: ${res.requestId}`);
      onRequestCreated();
    } catch (err: any) {
      setError(err.message || 'Failed to create collection request');
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <div className="bg-white p-5 rounded-xl border border-slate-200 shadow-sm">
      <div className="flex items-center space-x-2 border-b border-slate-100 pb-3 mb-4">
        <PlusCircle className="w-5 h-5 text-blue-600" />
        <h3 className="text-base font-bold text-slate-800">Create Collection Request</h3>
      </div>

      <form onSubmit={handleSubmit} className="space-y-4">
        {/* Origin Coords & Type */}
        <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
          <div>
            <label htmlFor="req-origin-type" className="block text-xs font-semibold text-slate-600 mb-1">
              Origin Type
            </label>
            <select
              id="req-origin-type"
              value={originType}
              onChange={(e) => setOriginType(e.target.value)}
              className="w-full text-xs px-3 py-2 border border-slate-300 rounded-md focus:ring-2 focus:ring-blue-500 focus:outline-none bg-white"
            >
              <option value="home">Patient Home</option>
              <option value="clinic">Clinic</option>
              <option value="node">Network Node</option>
            </select>
          </div>
          <div>
            <label htmlFor="req-lat" className="block text-xs font-semibold text-slate-600 mb-1">
              Latitude
            </label>
            <input
              id="req-lat"
              type="number"
              step="any"
              value={lat}
              onChange={(e) => setLat(e.target.value)}
              required
              className="w-full text-xs px-3 py-2 border border-slate-300 rounded-md focus:ring-2 focus:ring-blue-500 focus:outline-none"
            />
          </div>
          <div>
            <label htmlFor="req-lng" className="block text-xs font-semibold text-slate-600 mb-1">
              Longitude
            </label>
            <input
              id="req-lng"
              type="number"
              step="any"
              value={lng}
              onChange={(e) => setLng(e.target.value)}
              required
              className="w-full text-xs px-3 py-2 border border-slate-300 rounded-md focus:ring-2 focus:ring-blue-500 focus:outline-none"
            />
          </div>
        </div>

        {/* Sample Type & Container */}
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
          <div>
            <label htmlFor="req-sample-type" className="block text-xs font-semibold text-slate-600 mb-1">
              Sample Type
            </label>
            <select
              id="req-sample-type"
              value={sampleTypeId}
              onChange={(e) => handleSampleTypeChange(e.target.value)}
              className="w-full text-xs px-3 py-2 border border-slate-300 rounded-md focus:ring-2 focus:ring-blue-500 focus:outline-none bg-white"
            >
              {sampleTypes.map((st) => (
                <option key={st.sampleTypeId} value={st.sampleTypeId}>
                  {st.name} {st.requiresCooledRoute ? '(Requires Cooled)' : ''}
                </option>
              ))}
            </select>
          </div>
          <div>
            <label htmlFor="req-container" className="block text-xs font-semibold text-slate-600 mb-1">
              Container Type
            </label>
            <input
              id="req-container"
              type="text"
              value={containerType}
              onChange={(e) => setContainerType(e.target.value)}
              required
              className="w-full text-xs px-3 py-2 border border-slate-300 rounded-md focus:ring-2 focus:ring-blue-500 focus:outline-none"
            />
          </div>
        </div>

        {/* Temperature Min & Max */}
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
          <div>
            <label htmlFor="req-temp-min" className="block text-xs font-semibold text-slate-600 mb-1">
              Min Temperature (°C)
            </label>
            <input
              id="req-temp-min"
              type="number"
              step="any"
              value={tempMin}
              onChange={(e) => setTempMin(parseFloat(e.target.value))}
              required
              className="w-full text-xs px-3 py-2 border border-slate-300 rounded-md focus:ring-2 focus:ring-blue-500 focus:outline-none"
            />
          </div>
          <div>
            <label htmlFor="req-temp-max" className="block text-xs font-semibold text-slate-600 mb-1">
              Max Temperature (°C)
            </label>
            <input
              id="req-temp-max"
              type="number"
              step="any"
              value={tempMax}
              onChange={(e) => setTempMax(parseFloat(e.target.value))}
              required
              className="w-full text-xs px-3 py-2 border border-slate-300 rounded-md focus:ring-2 focus:ring-blue-500 focus:outline-none"
            />
          </div>
        </div>

        {/* Collection Window & Delivery Deadline */}
        <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
          <div>
            <label htmlFor="req-earliest-col" className="block text-xs font-semibold text-slate-600 mb-1">
              Earliest Collection
            </label>
            <input
              id="req-earliest-col"
              type="datetime-local"
              value={earliestCol}
              onChange={(e) => setEarliestCol(e.target.value)}
              required
              className="w-full text-xs px-3 py-2 border border-slate-300 rounded-md focus:ring-2 focus:ring-blue-500 focus:outline-none"
            />
          </div>
          <div>
            <label htmlFor="req-latest-col" className="block text-xs font-semibold text-slate-600 mb-1">
              Latest Collection
            </label>
            <input
              id="req-latest-col"
              type="datetime-local"
              value={latestCol}
              onChange={(e) => setLatestCol(e.target.value)}
              required
              className="w-full text-xs px-3 py-2 border border-slate-300 rounded-md focus:ring-2 focus:ring-blue-500 focus:outline-none"
            />
          </div>
          <div>
            <label htmlFor="req-deadline" className="block text-xs font-semibold text-slate-600 mb-1">
              Delivery Deadline
            </label>
            <input
              id="req-deadline"
              type="datetime-local"
              value={deadline}
              onChange={(e) => setDeadline(e.target.value)}
              required
              className="w-full text-xs px-3 py-2 border border-slate-300 rounded-md focus:ring-2 focus:ring-blue-500 focus:outline-none"
            />
          </div>
        </div>

        {error && (
          <div className="p-3 bg-red-50 border border-red-200 rounded-lg text-xs text-red-700 flex items-start space-x-2">
            <AlertCircle className="w-4 h-4 text-red-600 flex-shrink-0 mt-0.5" />
            <span className="font-medium">{error}</span>
          </div>
        )}

        {success && (
          <div className="p-3 bg-emerald-50 border border-emerald-200 rounded-lg text-xs text-emerald-700 flex items-start space-x-2">
            <CheckCircle className="w-4 h-4 text-emerald-600 flex-shrink-0 mt-0.5" />
            <span className="font-medium">{success}</span>
          </div>
        )}

        <button
          type="submit"
          disabled={submitting}
          className="w-full flex items-center justify-center py-2.5 px-4 border border-transparent rounded-md shadow-sm text-xs font-bold text-white bg-blue-600 hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-500 transition-colors disabled:opacity-50"
        >
          {submitting ? (
            <>
              <Loader2 className="w-4 h-4 mr-2 animate-spin" />
              Creating Collection Request & Routing...
            </>
          ) : (
            'Submit Collection Request'
          )}
        </button>
      </form>
    </div>
  );
};

