import React, { useState, useEffect } from 'react';
import { api } from '../api/client';
import { AuditEntry } from '../types';
import { Search, Filter, Clock, CheckCircle2, AlertCircle, Loader2 } from 'lucide-react';

export const AuditSearch: React.FC = () => {
  const [query, setQuery] = useState('');
  const [role, setRole] = useState('');
  const [action, setAction] = useState('');
  const [entityType, setEntityType] = useState('');
  const [order, setOrder] = useState('newest_first');
  const [offset, setOffset] = useState(0);
  const limit = 20;

  const [loading, setLoading] = useState(false);
  const [entries, setEntries] = useState<AuditEntry[]>([]);
  const [total, setTotal] = useState(0);
  const [hasMore, setHasMore] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const fetchAudit = async () => {
    setLoading(true);
    setError(null);
    try {
      const res = await api.searchAuditTrail({
        query: query || undefined,
        role: role || undefined,
        action: action || undefined,
        entityType: entityType || undefined,
        order,
        limit,
        offset,
      });
      setEntries(res.entries || []);
      setTotal(res.total || 0);
      setHasMore(res.hasMore || false);
    } catch (err: any) {
      setError(err.message || 'Failed to search audit trail');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchAudit();
  }, [offset, order]);

  const handleSearchSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setOffset(0);
    fetchAudit();
  };

  return (
    <div className="bg-white p-5 rounded-xl border border-slate-200 shadow-sm space-y-4">
      <div className="flex items-center justify-between border-b border-slate-100 pb-3">
        <div className="flex items-center space-x-2">
          <Search className="w-5 h-5 text-blue-600" />
          <h3 className="text-base font-bold text-slate-800">Audit Trail Search</h3>
        </div>
        <span className="text-xs text-slate-500 font-medium">Total records: {total}</span>
      </div>

      {/* Search & Filters */}
      <form onSubmit={handleSearchSubmit} className="space-y-3">
        <div className="grid grid-cols-1 sm:grid-cols-4 gap-3">
          <div className="sm:col-span-2">
            <label htmlFor="audit-query" className="block text-xs font-semibold text-slate-600 mb-1">
              Search Query
            </label>
            <input
              id="audit-query"
              type="text"
              placeholder="Search action, details, entity..."
              value={query}
              onChange={(e) => setQuery(e.target.value)}
              className="w-full text-xs px-3 py-2 border border-slate-300 rounded-md focus:ring-2 focus:ring-blue-500 focus:outline-none"
            />
          </div>
          <div>
            <label htmlFor="audit-role" className="block text-xs font-semibold text-slate-600 mb-1">
              Role
            </label>
            <input
              id="audit-role"
              type="text"
              placeholder="e.g. requester, dispatcher"
              value={role}
              onChange={(e) => setRole(e.target.value)}
              className="w-full text-xs px-3 py-2 border border-slate-300 rounded-md focus:ring-2 focus:ring-blue-500 focus:outline-none"
            />
          </div>
          <div>
            <label htmlFor="audit-entity-type" className="block text-xs font-semibold text-slate-600 mb-1">
              Entity Type
            </label>
            <input
              id="audit-entity-type"
              type="text"
              placeholder="e.g. sample, journey"
              value={entityType}
              onChange={(e) => setEntityType(e.target.value)}
              className="w-full text-xs px-3 py-2 border border-slate-300 rounded-md focus:ring-2 focus:ring-blue-500 focus:outline-none"
            />
          </div>
        </div>

        <div className="flex items-center justify-between pt-1">
          <div className="flex items-center space-x-2">
            <label htmlFor="audit-order" className="text-xs text-slate-500 font-medium">
              Order:
            </label>
            <select
              id="audit-order"
              value={order}
              onChange={(e) => setOrder(e.target.value)}
              className="text-xs px-2 py-1 border border-slate-300 rounded bg-white"
            >
              <option value="newest_first">Newest First</option>
              <option value="oldest_first">Oldest First</option>
            </select>
          </div>

          <button
            type="submit"
            disabled={loading}
            className="inline-flex items-center px-4 py-1.5 border border-transparent rounded-md shadow-sm text-xs font-semibold text-white bg-blue-600 hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-blue-500"
          >
            {loading ? <Loader2 className="w-3.5 h-3.5 mr-1 animate-spin" /> : <Filter className="w-3.5 h-3.5 mr-1" />}
            Filter Audit Records
          </button>
        </div>
      </form>

      {error && (
        <div className="p-3 bg-red-50 border border-red-200 rounded-lg text-xs text-red-700">{error}</div>
      )}

      {/* Results Table */}
      <div className="overflow-x-auto border border-slate-200 rounded-lg">
        <table className="min-w-full divide-y divide-slate-200 text-xs text-left">
          <thead className="bg-slate-50 text-slate-600 font-semibold uppercase tracking-wider text-[10px]">
            <tr>
              <th className="px-3 py-2.5">Time</th>
              <th className="px-3 py-2.5">Actor / Role</th>
              <th className="px-3 py-2.5">Action</th>
              <th className="px-3 py-2.5">Entity</th>
              <th className="px-3 py-2.5">Status</th>
              <th className="px-3 py-2.5">Details</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100 bg-white">
            {entries.length === 0 ? (
              <tr>
                <td colSpan={6} className="px-4 py-6 text-center text-slate-400 italic">
                  {loading ? 'Searching audit trail...' : 'No audit entries found.'}
                </td>
              </tr>
            ) : (
              entries.map((e) => (
                <tr key={e.auditId} className="hover:bg-slate-50/80 transition-colors">
                  <td className="px-3 py-2 text-slate-500 whitespace-nowrap">
                    <span className="flex items-center">
                      <Clock className="w-3 h-3 mr-1 text-slate-400" />
                      {new Date(e.occurredAt).toLocaleString()}
                    </span>
                  </td>
                  <td className="px-3 py-2 text-slate-700 whitespace-nowrap">
                    <div className="font-semibold text-slate-900">{e.actorRole || e.role}</div>
                    <div className="text-[10px] text-slate-400 font-mono">{e.actorId.slice(0, 8)}...</div>
                  </td>
                  <td className="px-3 py-2 font-mono font-medium text-blue-700 whitespace-nowrap">
                    {e.action}
                  </td>
                  <td className="px-3 py-2 text-slate-700 whitespace-nowrap">
                    <div className="font-medium capitalize">{e.entityType}</div>
                    <div className="text-[10px] text-slate-400 font-mono">{e.entityId.slice(0, 8)}...</div>
                  </td>
                  <td className="px-3 py-2 whitespace-nowrap">
                    {e.success ? (
                      <span className="inline-flex items-center px-1.5 py-0.5 rounded text-[10px] font-semibold bg-emerald-100 text-emerald-800">
                        <CheckCircle2 className="w-2.5 h-2.5 mr-1" /> Success
                      </span>
                    ) : (
                      <span className="inline-flex items-center px-1.5 py-0.5 rounded text-[10px] font-semibold bg-rose-100 text-rose-800">
                        <AlertCircle className="w-2.5 h-2.5 mr-1" /> Failed
                      </span>
                    )}
                  </td>
                  <td className="px-3 py-2 font-mono text-[10px] text-slate-600 max-w-xs truncate">
                    {JSON.stringify(e.details)}
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>

      {/* Pagination */}
      <div className="flex items-center justify-between text-xs text-slate-500 pt-2">
        <span>
          Showing {entries.length > 0 ? offset + 1 : 0} to {offset + entries.length} of {total}
        </span>
        <div className="flex space-x-2">
          <button
            onClick={() => setOffset(Math.max(0, offset - limit))}
            disabled={offset === 0 || loading}
            className="px-2.5 py-1 border border-slate-300 rounded bg-white hover:bg-slate-50 disabled:opacity-50"
          >
            Previous
          </button>
          <button
            onClick={() => setOffset(offset + limit)}
            disabled={!hasMore || loading}
            className="px-2.5 py-1 border border-slate-300 rounded bg-white hover:bg-slate-50 disabled:opacity-50"
          >
            Next
          </button>
        </div>
      </div>
    </div>
  );
};

