import React, { useState, useEffect } from 'react';
import { api } from '../api/client';
import { ServiceabilityChecker } from '../components/ServiceabilityChecker';
import { CollectionRequestForm } from '../components/CollectionRequestForm';
import { TimelineView } from '../components/TimelineView';
import { SampleType, RoleWork } from '../types';
import { TestTube, Clock, MapPin, User, AlertTriangle, CheckCircle2, ChevronRight, RefreshCw } from 'lucide-react';

export const RequesterView: React.FC = () => {
  const [sampleTypes, setSampleTypes] = useState<SampleType[]>([]);
  const [work, setWork] = useState<RoleWork>({ pending: [], inProgress: [], completed: [] });
  const [selectedSample, setSelectedSample] = useState<any | null>(null);
  const [loading, setLoading] = useState(false);

  const fetchWorkAndTypes = async () => {
    setLoading(true);
    try {
      const ops = await api.getOperationsState();
      // Load sample types or fallback default sample types
      const types: SampleType[] = [
        { sampleTypeId: '11111111-1111-1111-1111-111111111111', name: 'Amber', qualifiedCollectorRequired: true, requiredQualification: 'QUAL_AMBER', containerType: 'standard_ambient', temperatureMinC: 15, temperatureMaxC: 25, incompatibleSampleTypes: ['22222222-2222-2222-2222-222222222222'], requiresCooledRoute: false, batchingAllowed: true },
        { sampleTypeId: '22222222-2222-2222-2222-222222222222', name: 'Indigo', qualifiedCollectorRequired: true, requiredQualification: 'QUAL_INDIGO', containerType: 'isolated_ambient', temperatureMinC: 15, temperatureMaxC: 25, incompatibleSampleTypes: ['11111111-1111-1111-1111-111111111111'], requiresCooledRoute: false, batchingAllowed: true },
        { sampleTypeId: '33333333-3333-3333-3333-333333333333', name: 'Frost', qualifiedCollectorRequired: true, requiredQualification: 'QUAL_FROST', containerType: 'cold_pack_container', temperatureMinC: 2, temperatureMaxC: 8, incompatibleSampleTypes: [], requiresCooledRoute: true, batchingAllowed: true },
        { sampleTypeId: '44444444-4444-4444-4444-444444444444', name: 'Pulse', qualifiedCollectorRequired: true, requiredQualification: 'QUAL_PULSE', containerType: 'rapid_transit_vial', temperatureMinC: 10, temperatureMaxC: 30, incompatibleSampleTypes: [], requiresCooledRoute: false, batchingAllowed: false },
      ];
      setSampleTypes(types);

      const workRes = await api.listRoleWork('requester');
      setWork(workRes || { pending: [], inProgress: [], completed: [] });

      // If selectedSample, refresh it
      if (selectedSample?.sampleId) {
        const updated = await api.getSampleState(selectedSample.sampleId);
        setSelectedSample(updated);
      }
    } catch (e) {
      console.error(e);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchWorkAndTypes();
  }, []);

  const handleSelectSample = async (sampleId: string) => {
    try {
      const state = await api.getSampleState(sampleId);
      setSelectedSample(state);
    } catch (e) {
      console.error(e);
    }
  };

  const allWorkItems = [...(work.pending || []), ...(work.inProgress || [])];
  const completedItems = work.completed || [];

  return (
    <div className="space-y-6">
      {/* Top action grid: Serviceability Check & Create Request */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <ServiceabilityChecker sampleTypes={sampleTypes} />
        <CollectionRequestForm sampleTypes={sampleTypes} onRequestCreated={fetchWorkAndTypes} />
      </div>

      {/* Samples & Tracking */}
      <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden">
        <div className="p-5 border-b border-slate-200 flex items-center justify-between">
          <div>
            <h2 className="text-base font-bold text-slate-900">My Collection Requests & Samples</h2>
            <p className="text-xs text-slate-500">Track sample custody, location freshness, and history</p>
          </div>
          <button
            onClick={fetchWorkAndTypes}
            disabled={loading}
            className="inline-flex items-center px-3 py-1.5 border border-slate-300 rounded-md text-xs font-medium text-slate-700 bg-white hover:bg-slate-50 shadow-sm"
          >
            <RefreshCw className={`w-3.5 h-3.5 mr-1.5 ${loading ? 'animate-spin' : ''}`} />
            Refresh
          </button>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-3 divide-y lg:divide-y-0 lg:divide-x divide-slate-200">
          {/* Active Work / Past Work List */}
          <div className="lg:col-span-1 p-4 space-y-4 max-h-[600px] overflow-y-auto">
            <div>
              <h3 className="text-xs font-bold uppercase tracking-wider text-slate-500 mb-2">
                Active Requests ({allWorkItems.length})
              </h3>
              <div className="space-y-2">
                {allWorkItems.length === 0 ? (
                  <div className="text-xs text-slate-400 italic py-2">No active requests.</div>
                ) : (
                  allWorkItems.map((item) => {
                    const sid = item.sampleId || item.sample_id || '';
                    const isSelected = selectedSample?.sampleId === sid;
                    const isStale = item.locationStale;
                    const isException = item.status === 'exception';

                    return (
                      <div
                        key={sid}
                        onClick={() => handleSelectSample(sid)}
                        className={`p-3 rounded-lg border cursor-pointer transition-all ${
                          isSelected
                            ? 'bg-blue-50 border-blue-300 ring-1 ring-blue-400'
                            : 'bg-white border-slate-200 hover:border-slate-300'
                        }`}
                      >
                        <div className="flex items-center justify-between">
                          <span className="font-bold text-xs text-slate-900 flex items-center">
                            <TestTube className="w-3.5 h-3.5 mr-1 text-blue-600" />
                            {sid.slice(0, 8)}...
                          </span>
                          <span
                            className={`text-[10px] font-bold px-2 py-0.5 rounded-full ${
                              isException
                                ? 'bg-rose-100 text-rose-800'
                                : 'bg-blue-100 text-blue-800'
                            }`}
                          >
                            {item.status}
                          </span>
                        </div>

                        <div className="mt-2 text-[11px] text-slate-500 space-y-1">
                          <div className="flex items-center justify-between">
                            <span>Deadline:</span>
                            <span className="font-medium text-slate-700">
                              {item.deliveryDeadline ? new Date(item.deliveryDeadline).toLocaleTimeString() : 'N/A'}
                            </span>
                          </div>
                          <div className="flex items-center justify-between">
                            <span>Location Freshness:</span>
                            <span className={`font-semibold ${isStale ? 'text-amber-600' : 'text-emerald-600'}`}>
                              {isStale ? 'Stale' : 'Fresh'}
                            </span>
                          </div>
                        </div>
                      </div>
                    );
                  })
                )}
              </div>
            </div>

            {/* Completed Requests */}
            <div className="pt-2 border-t border-slate-100">
              <h3 className="text-xs font-bold uppercase tracking-wider text-slate-500 mb-2">
                Completed ({completedItems.length})
              </h3>
              <div className="space-y-2">
                {completedItems.length === 0 ? (
                  <div className="text-xs text-slate-400 italic py-2">No completed requests.</div>
                ) : (
                  completedItems.map((item) => {
                    const sid = item.sampleId || item.sample_id || '';
                    const isSelected = selectedSample?.sampleId === sid;

                    return (
                      <div
                        key={sid}
                        onClick={() => handleSelectSample(sid)}
                        className={`p-2.5 rounded-lg border cursor-pointer text-xs ${
                          isSelected ? 'bg-blue-50 border-blue-300' : 'bg-slate-50 border-slate-200'
                        }`}
                      >
                        <div className="flex items-center justify-between font-medium">
                          <span>Sample {sid.slice(0, 8)}...</span>
                          <span className="text-[10px] bg-emerald-100 text-emerald-800 px-1.5 py-0.5 rounded">
                            {item.status}
                          </span>
                        </div>
                      </div>
                    );
                  })
                )}
              </div>
            </div>
          </div>

          {/* Sample Details & Timeline */}
          <div className="lg:col-span-2 p-5">
            {selectedSample ? (
              <div className="space-y-5">
                <div className="flex items-center justify-between border-b border-slate-100 pb-3">
                  <div>
                    <h3 className="text-sm font-bold text-slate-900 flex items-center">
                      <TestTube className="w-4 h-4 mr-1.5 text-blue-600" />
                      Sample Details: <span className="font-mono text-xs ml-1 text-slate-600">{selectedSample.sampleId}</span>
                    </h3>
                    <p className="text-xs text-slate-400 mt-0.5">Request ID: {selectedSample.requestId}</p>
                  </div>
                  <div>
                    {selectedSample.state?.status === 'exception' ? (
                      <span className="inline-flex items-center px-2.5 py-1 rounded-full text-xs font-bold bg-rose-100 text-rose-800 border border-rose-200">
                        <AlertTriangle className="w-3.5 h-3.5 mr-1" /> Exception Flagged
                      </span>
                    ) : (
                      <span className="inline-flex items-center px-2.5 py-1 rounded-full text-xs font-bold bg-blue-100 text-blue-800">
                        Status: {selectedSample.state?.status || 'Active'}
                      </span>
                    )}
                  </div>
                </div>

                {/* Key Status Metrics: Location, Custodian, Freshness */}
                <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
                  <div className="bg-slate-50 p-3 rounded-lg border border-slate-200">
                    <span className="text-[10px] font-bold uppercase text-slate-500 block mb-1">Current Custodian</span>
                    <span className="text-xs font-semibold text-slate-800 flex items-center font-mono">
                      <User className="w-3.5 h-3.5 mr-1 text-slate-400" />
                      {selectedSample.currentHolderId ? `${selectedSample.currentHolderId.slice(0, 8)}...` : 'Unassigned / Pending'}
                    </span>
                  </div>

                  <div className="bg-slate-50 p-3 rounded-lg border border-slate-200">
                    <span className="text-[10px] font-bold uppercase text-slate-500 block mb-1">Latest Location</span>
                    <span className="text-xs font-semibold text-slate-800 flex items-center">
                      <MapPin className="w-3.5 h-3.5 mr-1 text-slate-400" />
                      {selectedSample.latestLocation
                        ? `${selectedSample.latestLocation.latitude.toFixed(4)}, ${selectedSample.latestLocation.longitude.toFixed(4)}`
                        : `${selectedSample.origin.latitude.toFixed(4)}, ${selectedSample.origin.longitude.toFixed(4)}`}
                    </span>
                  </div>

                  <div className="bg-slate-50 p-3 rounded-lg border border-slate-200">
                    <span className="text-[10px] font-bold uppercase text-slate-500 block mb-1">Location Freshness</span>
                    <span className={`text-xs font-bold flex items-center ${selectedSample.locationStale ? 'text-amber-600' : 'text-emerald-600'}`}>
                      <Clock className="w-3.5 h-3.5 mr-1" />
                      {selectedSample.locationStale ? 'Stale Location' : 'Fresh (Updated Recently)'}
                    </span>
                    {selectedSample.locationRecordedAt && (
                      <span className="text-[10px] text-slate-400 block mt-0.5">
                        Last update: {new Date(selectedSample.locationRecordedAt).toLocaleTimeString()}
                      </span>
                    )}
                  </div>
                </div>

                {/* Status Timeline */}
                <div className="pt-2 border-t border-slate-100">
                  <TimelineView timeline={selectedSample.timeline || []} title="Sample Lifecycle & Status Timeline" />
                </div>
              </div>
            ) : (
              <div className="py-16 text-center text-slate-400 text-xs">
                Select a sample request from the left list to view detailed custody, freshness, and lifecycle timeline.
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

