import React, { useState, useEffect } from 'react';
import { api } from '../api/client';
import { TimelineView } from '../components/TimelineView';
import { RoleWork, RoleWorkItem } from '../types';
import { ShieldCheck, Check, X, MapPin, Package, ArrowRight, RefreshCw, Loader2, AlertCircle } from 'lucide-react';

export const CollectorView: React.FC = () => {
  const [work, setWork] = useState<RoleWork>({ pending: [], inProgress: [], completed: [] });
  const [selectedItem, setSelectedItem] = useState<RoleWorkItem | null>(null);
  const [loading, setLoading] = useState(false);
  const [actionLoading, setActionLoading] = useState(false);
  const [actionMsg, setActionMsg] = useState<{ type: 'success' | 'error'; text: string } | null>(null);

  // Form states for collection
  const [containerType, setContainerType] = useState('standard_ambient');
  const [observedTemp, setObservedTemp] = useState('20.0');

  // Form states for location recording
  const [lat, setLat] = useState('12.9716');
  const [lng, setLng] = useState('77.5946');

  // Form states for handoff
  const [receiverId, setReceiverId] = useState('');
  const [nextAssignmentId, setNextAssignmentId] = useState('');

  const fetchWork = async () => {
    setLoading(true);
    try {
      const res = await api.listRoleWork('collection_professional');
      setWork(res || { pending: [], inProgress: [], completed: [] });
      if (selectedItem) {
        const sid = selectedItem.assignmentId || selectedItem.assignment_id;
        const all = [...(res.pending || []), ...(res.inProgress || []), ...(res.completed || [])];
        const match = all.find((i) => (i.assignmentId || i.assignment_id) === sid);
        if (match) setSelectedItem(match);
      }
    } catch (e) {
      console.error(e);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchWork();
  }, []);

  const handleAccept = async (assignmentId: string) => {
    setActionLoading(true);
    setActionMsg(null);
    try {
      await api.acceptAssignment(assignmentId);
      setActionMsg({ type: 'success', text: 'Assignment accepted successfully!' });
      await fetchWork();
    } catch (e: any) {
      setActionMsg({ type: 'error', text: e.message || 'Failed to accept assignment' });
    } finally {
      setActionLoading(false);
    }
  };

  const handleDecline = async (assignmentId: string) => {
    setActionLoading(true);
    setActionMsg(null);
    try {
      await api.declineAssignment(assignmentId, 'Collector unavailable');
      setActionMsg({ type: 'success', text: 'Assignment declined and re-offered.' });
      await fetchWork();
    } catch (e: any) {
      setActionMsg({ type: 'error', text: e.message || 'Failed to decline assignment' });
    } finally {
      setActionLoading(false);
    }
  };

  const handleCollectAndSeal = async (sampleId: string, assignmentId: string) => {
    setActionLoading(true);
    setActionMsg(null);
    try {
      const res = await api.collectAndSealSample({
        sampleId,
        assignmentId,
        collectedAt: new Date().toISOString(),
        containerType,
        observedTemperatureC: parseFloat(observedTemp),
      });
      if (res.handlingCompliant) {
        setActionMsg({ type: 'success', text: 'Sample successfully collected and sealed!' });
      } else {
        setActionMsg({ type: 'error', text: 'Warning: Sample flagged for non-compliant temperature/container!' });
      }
      await fetchWork();
    } catch (e: any) {
      setActionMsg({ type: 'error', text: e.message || 'Failed to seal sample' });
    } finally {
      setActionLoading(false);
    }
  };

  const handleRecordLocation = async (assignmentId: string) => {
    setActionLoading(true);
    setActionMsg(null);
    try {
      await api.recordWorkerLocation(
        assignmentId,
        { latitude: parseFloat(lat), longitude: parseFloat(lng) },
        1
      );
      setActionMsg({ type: 'success', text: 'Current location recorded successfully!' });
      await fetchWork();
    } catch (e: any) {
      setActionMsg({ type: 'error', text: e.message || 'Failed to record location' });
    } finally {
      setActionLoading(false);
    }
  };

  const handleInitiateHandoff = async (sampleId: string, assignmentId: string) => {
    if (!receiverId) {
      setActionMsg({ type: 'error', text: 'Receiver Worker ID required' });
      return;
    }
    setActionLoading(true);
    setActionMsg(null);
    try {
      await api.initiateHandoff({
        sampleId,
        fromAssignmentId: assignmentId,
        toAssignmentId: nextAssignmentId || undefined,
        receiverId,
      });
      setActionMsg({ type: 'success', text: 'Handoff initiated! Awaiting receiver confirmation.' });
      await fetchWork();
    } catch (e: any) {
      setActionMsg({ type: 'error', text: e.message || 'Failed to initiate handoff' });
    } finally {
      setActionLoading(false);
    }
  };

  return (
    <div className="space-y-6">
      <div className="bg-white p-5 rounded-xl border border-slate-200 shadow-sm flex items-center justify-between">
        <div className="flex items-center space-x-3">
          <div className="w-10 h-10 rounded-lg bg-emerald-100 text-emerald-700 flex items-center justify-center font-bold">
            <ShieldCheck className="w-6 h-6" />
          </div>
          <div>
            <h2 className="text-base font-bold text-slate-900">Certified Collection Professional Dashboard</h2>
            <p className="text-xs text-slate-500">Qualified sample collection, sealing, custody transfer, and location recording</p>
          </div>
        </div>
        <button
          onClick={fetchWork}
          disabled={loading}
          className="inline-flex items-center px-3 py-1.5 border border-slate-300 rounded-md text-xs font-medium text-slate-700 bg-white hover:bg-slate-50 shadow-sm"
        >
          <RefreshCw className={`w-3.5 h-3.5 mr-1.5 ${loading ? 'animate-spin' : ''}`} />
          Refresh Work
        </button>
      </div>

      {actionMsg && (
        <div
          className={`p-3 rounded-lg border text-xs flex items-center space-x-2 ${
            actionMsg.type === 'success'
              ? 'bg-emerald-50 border-emerald-200 text-emerald-800'
              : 'bg-red-50 border-red-200 text-red-800'
          }`}
        >
          {actionMsg.type === 'success' ? <Check className="w-4 h-4" /> : <AlertCircle className="w-4 h-4" />}
          <span>{actionMsg.text}</span>
        </div>
      )}

      {/* Main Grid: Work List vs Selected Assignment Actions & Timeline */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Left Column: Offered / Active / Completed Work */}
        <div className="bg-white p-4 rounded-xl border border-slate-200 shadow-sm space-y-4 max-h-[700px] overflow-y-auto">
          {/* Pending Offers */}
          <div>
            <h3 className="text-xs font-bold uppercase tracking-wider text-amber-600 mb-2 flex items-center">
              Offered Assignments ({work.pending.length})
            </h3>
            <div className="space-y-2">
              {work.pending.length === 0 ? (
                <div className="text-xs text-slate-400 italic py-1">No pending offers.</div>
              ) : (
                work.pending.map((item) => {
                  const aid = item.assignmentId || item.assignment_id || '';
                  const sid = item.sampleId || item.sample_id || '';
                  return (
                    <div
                      key={aid}
                      className="p-3 bg-amber-50/60 border border-amber-200 rounded-lg text-xs space-y-2"
                    >
                      <div className="flex items-center justify-between font-bold text-slate-900">
                        <span>Sample {sid.slice(0, 8)}...</span>
                        <span className="text-[10px] bg-amber-200 text-amber-900 px-1.5 py-0.5 rounded">Offered</span>
                      </div>
                      <div className="flex space-x-2 pt-1">
                        <button
                          onClick={() => handleAccept(aid)}
                          disabled={actionLoading}
                          className="flex-1 py-1 px-2 bg-emerald-600 hover:bg-emerald-700 text-white rounded font-semibold text-[11px] flex items-center justify-center"
                        >
                          <Check className="w-3 h-3 mr-1" /> Accept
                        </button>
                        <button
                          onClick={() => handleDecline(aid)}
                          disabled={actionLoading}
                          className="flex-1 py-1 px-2 bg-white border border-slate-300 hover:bg-slate-50 text-slate-700 rounded font-semibold text-[11px] flex items-center justify-center"
                        >
                          <X className="w-3 h-3 mr-1" /> Decline
                        </button>
                      </div>
                    </div>
                  );
                })
              )}
            </div>
          </div>

          {/* In Progress Work */}
          <div className="pt-3 border-t border-slate-100">
