import React, { useState, useEffect } from 'react';
import { api } from '../api/client';
import { TimelineView } from '../components/TimelineView';
import { RoleWork, RoleWorkItem } from '../types';
import { Truck, Check, X, MapPin, CheckSquare, ArrowRight, RefreshCw, AlertCircle } from 'lucide-react';

export const CourierView: React.FC = () => {
  const [work, setWork] = useState<RoleWork>({ pending: [], inProgress: [], completed: [] });
  const [selectedItem, setSelectedItem] = useState<RoleWorkItem | null>(null);
  const [loading, setLoading] = useState(false);
  const [actionLoading, setActionLoading] = useState(false);
  const [actionMsg, setActionMsg] = useState<{ type: 'success' | 'error'; text: string } | null>(null);

  // Form states
  const [progressStatus, setProgressStatus] = useState('in_transit');
  const [lat, setLat] = useState('12.9716');
  const [lng, setLng] = useState('77.5946');
  const [handoffId, setHandoffId] = useState('');

  const fetchWork = async () => {
    setLoading(true);
    try {
      const res = await api.listRoleWork('delivery_partner');
      setWork(res || { pending: [], inProgress: [], completed: [] });
      if (selectedItem) {
        const sid = selectedItem.assignmentId || selectedItem.assignment_id;
        const all = [...(res.pending || []), ...(res.inProgress || []), ...(res.completed || [])];
        const match = all.find((i) => (i.assignmentId || i.assignment_id) === sid);
        if (match) setSelectedItem(match);
      }
    } catch (e) {
      console.error(e);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchWork();
  }, []);

  const handleAccept = async (assignmentId: string) => {
    setActionLoading(true);
    setActionMsg(null);
    try {
      await api.acceptAssignment(assignmentId);
      setActionMsg({ type: 'success', text: 'Transport assignment accepted!' });
      await fetchWork();
    } catch (e: any) {
      setActionMsg({ type: 'error', text: e.message || 'Failed to accept' });
    } finally {
      setActionLoading(false);
    }
  };

  const handleDecline = async (assignmentId: string) => {
    setActionLoading(true);
    setActionMsg(null);
    try {
      await api.declineAssignment(assignmentId, 'Courier capacity unavailable');
      setActionMsg({ type: 'success', text: 'Assignment declined and re-offered.' });
      await fetchWork();
    } catch (e: any) {
      setActionMsg({ type: 'error', text: e.message || 'Failed to decline' });
    } finally {
      setActionLoading(false);
    }
  };

  const handleUpdateProgress = async (assignmentId: string) => {
    setActionLoading(true);
    setActionMsg(null);
    try {
      await api.updateAssignmentProgress(assignmentId, progressStatus);
      setActionMsg({ type: 'success', text: `Progress updated to ${progressStatus}!` });
      await fetchWork();
    } catch (e: any) {
      setActionMsg({ type: 'error', text: e.message || 'Failed to update progress' });
    } finally {
      setActionLoading(false);
    }
  };

  const handleRecordLocation = async (assignmentId: string) => {
    setActionLoading(true);
    setActionMsg(null);
    try {
      await api.recordWorkerLocation(
        assignmentId,
        { latitude: parseFloat(lat), longitude: parseFloat(lng) },
        1
      );
      setActionMsg({ type: 'success', text: 'Location recorded successfully!' });
      await fetchWork();
    } catch (e: any) {
      setActionMsg({ type: 'error', text: e.message || 'Failed to record location' });
    } finally {
      setActionLoading(false);
    }
  };

  const handleConfirmHandoff = async () => {
    if (!handoffId) {
      setActionMsg({ type: 'error', text: 'Handoff ID is required' });
      return;
    }
    setActionLoading(true);
    setActionMsg(null);
    try {
      const res = await api.confirmHandoff(handoffId, 'receiver');
      setActionMsg({ type: 'success', text: `Handoff confirmed! Status: ${res.status}` });
      await fetchWork();
    } catch (e: any) {
      setActionMsg({ type: 'error', text: e.message || 'Failed to confirm handoff' });
    } finally {
      setActionLoading(false);
    }
  };

  return (
    <div className="space-y-6">
      <div className="bg-white p-5 rounded-xl border border-slate-200 shadow-sm flex items-center justify-between">
        <div className="flex items-center space-x-3">
          <div className="w-10 h-10 rounded-lg bg-blue-100 text-blue-700 flex items-center justify-center font-bold">
            <Truck className="w-6 h-6" />
          </div>
          <div>
            <h2 className="text-base font-bold text-slate-900">Relay Courier Dashboard</h2>
            <p className="text-xs text-slate-500">Manage transport legs, update progress, confirm handoffs, and report live location</p>
          </div>
        </div>
        <button
          onClick={fetchWork}
          disabled={loading}
          className="inline-flex items-center px-3 py-1.5 border border-slate-300 rounded-md text-xs font-medium text-slate-700 bg-white hover:bg-slate-50 shadow-sm"
        >
          <RefreshCw className={`w-3.5 h-3.5 mr-1.5 ${loading ? 'animate-spin' : ''}`} />
          Refresh Work
        </button>
      </div>

      {actionMsg && (
        <div
          className={`p-3 rounded-lg border text-xs flex items-center space-x-2 ${
            actionMsg.type === 'success'
              ? 'bg-emerald-50 border-emerald-200 text-emerald-800'
              : 'bg-red-50 border-red-200 text-red-800'
          }`}
        >
          {actionMsg.type === 'success' ? <Check className="w-4 h-4" /> : <AlertCircle className="w-4 h-4" />}
          <span>{actionMsg.text}</span>
        </div>
      )}

      {/* Main Grid: Work List vs Selected Assignment Actions & Timeline */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Left Column: Offered / Active / Completed Transport */}
        <div className="bg-white p-4 rounded-xl border border-slate-200 shadow-sm space-y-4 max-h-[700px] overflow-y-auto">
