import React, { useState, useEffect } from 'react';
import { api } from '../api/client';
import { TimelineView } from '../components/TimelineView';
import { RoleWork, RoleWorkItem, OperationsLocation } from '../types';
import { Building2, Check, X, Shield, PlusCircle, RefreshCw, AlertCircle } from 'lucide-react';

export const NodeHandlerView: React.FC = () => {
  const [work, setWork] = useState<RoleWork>({ pending: [], inProgress: [], completed: [] });
  const [selectedItem, setSelectedItem] = useState<RoleWorkItem | null>(null);
  const [locations, setLocations] = useState<OperationsLocation[]>([]);
  const [selectedNodeId, setSelectedNodeId] = useState('');

  // Capacity config
  const [regularCapacity, setRegularCapacity] = useState(150);
  const [cooledCapacity, setCooledCapacity] = useState(75);

  // Pre-sealed sample intake form
  const [preSampleTypeId, setPreSampleTypeId] = useState('11111111-1111-1111-1111-111111111111');
  const [preDeadline, setPreDeadline] = useState(new Date(Date.now() + 5 * 3600000).toISOString().slice(0, 16));
  const [preLat, setPreLat] = useState('12.9784');
  const [preLng, setPreLng] = useState('77.6408');

  // Handoff confirmation
  const [handoffId, setHandoffId] = useState('');

  const [loading, setLoading] = useState(false);
  const [actionLoading, setActionLoading] = useState(false);
  const [actionMsg, setActionMsg] = useState<{ type: 'success' | 'error'; text: string } | null>(null);

  const fetchData = async () => {
    setLoading(true);
    try {
      const ops = await api.getOperationsState();
      setLocations(ops.locations || []);
      if (ops.locations?.length > 0 && !selectedNodeId) {
        setSelectedNodeId(ops.locations[0].locationId);
        setRegularCapacity(ops.locations[0].capacity?.capacityUnits ?? 150);
        setCooledCapacity(ops.locations[0].capacity?.cooledCapacityUnits ?? 75);
      }

      const workRes = await api.listRoleWork('node_handler');
      setWork(workRes || { pending: [], inProgress: [], completed: [] });
    } catch (e) {
      console.error(e);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchData();
  }, []);

  const handleNodeSelect = (nodeId: string) => {
    setSelectedNodeId(nodeId);
    const node = locations.find((l) => l.locationId === nodeId);
    if (node) {
      setRegularCapacity(node.capacity?.capacityUnits ?? 150);
      setCooledCapacity(node.capacity?.cooledCapacityUnits ?? 75);
      setPreLat(node.coordinate.latitude.toString());
      setPreLng(node.coordinate.longitude.toString());
    }
  };

  const handleUpdateCapacity = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedNodeId) return;
    setActionLoading(true);
    setActionMsg(null);
    try {
      await api.configureCapacity(selectedNodeId, regularCapacity, cooledCapacity);
      setActionMsg({ type: 'success', text: 'Node capacity updated successfully!' });
      await fetchData();
    } catch (e: any) {
      setActionMsg({ type: 'error', text: e.message || 'Failed to update capacity' });
    } finally {
      setActionLoading(false);
    }
  };

  const handleIngestPresealed = async (e: React.FormEvent) => {
    e.preventDefault();
    setActionLoading(true);
    setActionMsg(null);
    try {
      const res = await api.ingestPresealedSample({
        origin: { latitude: parseFloat(preLat), longitude: parseFloat(preLng) },
        originType: 'clinic',
        originNodeId: selectedNodeId || undefined,
        requestedAt: new Date().toISOString(),
        deliveryDeadline: new Date(preDeadline).toISOString(),
        sampleTypeId: preSampleTypeId,
        containerType: 'standard_ambient',
        temperatureMinC: 15,
        temperatureMaxC: 25,
        incompatibleSampleTypes: [],
      });
      setActionMsg({ type: 'success', text: `Pre-sealed sample registered! Sample ID: ${res.sampleId}` });
      await fetchData();
    } catch (e: any) {
      setActionMsg({ type: 'error', text: e.message || 'Failed to register pre-sealed sample' });
    } finally {
