import React, { useState, useEffect } from 'react';
import { api } from '../api/client';
import { TimelineView } from '../components/TimelineView';
import { RoleWork, RoleWorkItem, OperationsLocation } from '../types';
import { Building2, Check, X, Shield, PlusCircle, RefreshCw, AlertCircle } from 'lucide-react';

export const NodeHandlerView: React.FC = () => {
  const [work, setWork] = useState<RoleWork>({ pending: [], inProgress: [], completed: [] });
  const [selectedItem, setSelectedItem] = useState<RoleWorkItem | null>(null);
  const [locations, setLocations] = useState<OperationsLocation[]>([]);
  const [selectedNodeId, setSelectedNodeId] = useState('');

  // Capacity config
  const [regularCapacity, setRegularCapacity] = useState(150);
  const [cooledCapacity, setCooledCapacity] = useState(75);

  // Pre-sealed sample intake form
  const [preSampleTypeId, setPreSampleTypeId] = useState('11111111-1111-1111-1111-111111111111');
  const [preDeadline, setPreDeadline] = useState(new Date(Date.now() + 5 * 3600000).toISOString().slice(0, 16));
  const [preLat, setPreLat] = useState('12.9784');
  const [preLng, setPreLng] = useState('77.6408');

  // Handoff confirmation
  const [handoffId, setHandoffId] = useState('');

  const [loading, setLoading] = useState(false);
  const [actionLoading, setActionLoading] = useState(false);
  const [actionMsg, setActionMsg] = useState<{ type: 'success' | 'error'; text: string } | null>(null);

  const fetchData = async () => {
    setLoading(true);
    try {
      const ops = await api.getOperationsState();
      setLocations(ops.locations || []);
      if (ops.locations?.length > 0 && !selectedNodeId) {
        setSelectedNodeId(ops.locations[0].locationId);
        setRegularCapacity(ops.locations[0].capacity?.capacityUnits ?? 150);
        setCooledCapacity(ops.locations[0].capacity?.cooledCapacityUnits ?? 75);
      }

      const workRes = await api.listRoleWork('node_handler');
      setWork(workRes || { pending: [], inProgress: [], completed: [] });
    } catch (e) {
      console.error(e);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchData();
  }, []);

  const handleNodeSelect = (nodeId: string) => {
    setSelectedNodeId(nodeId);
    const node = locations.find((l) => l.locationId === nodeId);
    if (node) {
      setRegularCapacity(node.capacity?.capacityUnits ?? 150);
      setCooledCapacity(node.capacity?.cooledCapacityUnits ?? 75);
      setPreLat(node.coordinate.latitude.toString());
      setPreLng(node.coordinate.longitude.toString());
    }
  };

  const handleUpdateCapacity = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedNodeId) return;
    setActionLoading(true);
    setActionMsg(null);
    try {
      await api.configureCapacity(selectedNodeId, regularCapacity, cooledCapacity);
      setActionMsg({ type: 'success', text: 'Node capacity updated successfully!' });
      await fetchData();
    } catch (e: any) {
      setActionMsg({ type: 'error', text: e.message || 'Failed to update capacity' });
    } finally {
      setActionLoading(false);
    }
  };

  const handleIngestPresealed = async (e: React.FormEvent) => {
    e.preventDefault();
    setActionLoading(true);
    setActionMsg(null);
    try {
      const res = await api.ingestPresealedSample({
        origin: { latitude: parseFloat(preLat), longitude: parseFloat(preLng) },
        originType: 'clinic',
        originNodeId: selectedNodeId || undefined,
        requestedAt: new Date().toISOString(),
        deliveryDeadline: new Date(preDeadline).toISOString(),
        sampleTypeId: preSampleTypeId,
        containerType: 'standard_ambient',
        temperatureMinC: 15,
        temperatureMaxC: 25,
        incompatibleSampleTypes: [],
      });
      setActionMsg({ type: 'success', text: `Pre-sealed sample registered! Sample ID: ${res.sampleId}` });
      await fetchData();
    } catch (e: any) {
      setActionMsg({ type: 'error', text: e.message || 'Failed to register pre-sealed sample' });
    } finally {
      setActionLoading(false);
    }
  };

  const handleConfirmHandoff = async () => {
    if (!handoffId) {
      setActionMsg({ type: 'error', text: 'Handoff ID required' });
      return;
    }
    setActionLoading(true);
    setActionMsg(null);
    try {
      const res = await api.confirmHandoff(handoffId, 'receiver');
      setActionMsg({ type: 'success', text: `Custody handoff confirmed! Status: ${res.status}` });
      await fetchData();
    } catch (e: any) {
      setActionMsg({ type: 'error', text: e.message || 'Failed to confirm handoff' });
    } finally {
      setActionLoading(false);
    }
  };

  const currentNode = locations.find((l) => l.locationId === selectedNodeId);

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="bg-white p-5 rounded-xl border border-slate-200 shadow-sm flex items-center justify-between">
        <div className="flex items-center space-x-3">
          <div className="w-10 h-10 rounded-lg bg-amber-100 text-amber-700 flex items-center justify-center font-bold">
            <Building2 className="w-6 h-6" />
          </div>
          <div>
            <h2 className="text-base font-bold text-slate-900">Collection Centre / Hub Node Handler Dashboard</h2>
            <p className="text-xs text-slate-500">Node assignments, pre-sealed sample intake, and capacity configuration</p>
          </div>
        </div>
        <button
          onClick={fetchData}
          disabled={loading}
          className="inline-flex items-center px-3 py-1.5 border border-slate-300 rounded-md text-xs font-medium text-slate-700 bg-white hover:bg-slate-50 shadow-sm"
        >
          <RefreshCw className={`w-3.5 h-3.5 mr-1.5 ${loading ? 'animate-spin' : ''}`} />
          Refresh
        </button>
      </div>

      {actionMsg && (
        <div
          className={`p-3 rounded-lg border text-xs flex items-center space-x-2 ${
            actionMsg.type === 'success'
              ? 'bg-emerald-50 border-emerald-200 text-emerald-800'
              : 'bg-red-50 border-red-200 text-red-800'
          }`}
        >
          {actionMsg.type === 'success' ? <Check className="w-4 h-4" /> : <AlertCircle className="w-4 h-4" />}
          <span>{actionMsg.text}</span>
        </div>
      )}

      {/* Node Selector & Capacity Config Grid */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Node Capacity Management */}
        <div className="bg-white p-5 rounded-xl border border-slate-200 shadow-sm space-y-4">
          <div className="flex items-center space-x-2 border-b border-slate-100 pb-2">
            <Shield className="w-4 h-4 text-amber-600" />
            <h3 className="text-sm font-bold text-slate-900">Node Capacity Management</h3>
          </div>

          <div>
            <label htmlFor="node-select-assigned" className="block text-xs font-semibold text-slate-600 mb-1">
              Select Assigned Node
            </label>
            <select
              id="node-select-assigned"
              value={selectedNodeId}
              onChange={(e) => handleNodeSelect(e.target.value)}
              className="w-full text-xs px-3 py-2 border border-slate-300 rounded bg-white font-medium"
            >
              {locations.map((loc) => (
                <option key={loc.locationId} value={loc.locationId}>
                  {loc.name}
                </option>
              ))}
            </select>
          </div>

          {currentNode?.capacity && (
            <div className="p-3 bg-slate-50 rounded-lg border border-slate-200 text-xs space-y-1">
              <div className="flex justify-between">
                <span className="text-slate-500">Regular Capacity:</span>
                <span className="font-bold text-slate-800">
                  {currentNode.capacity.availableUnits} available / {currentNode.capacity.capacityUnits} total
                </span>
              </div>
              <div className="flex justify-between">
                <span className="text-slate-500">Cooled Capacity:</span>
                <span className="font-bold text-slate-800">
                  {currentNode.capacity.cooledAvailableUnits} available / {currentNode.capacity.cooledCapacityUnits} total
                </span>
              </div>
            </div>
          )}

          <form onSubmit={handleUpdateCapacity} className="space-y-3 pt-2">
            <div>
              <label htmlFor="node-reg-cap" className="block text-xs font-semibold text-slate-600 mb-1">
                Configured Regular Capacity Units
              </label>
              <input
                id="node-reg-cap"
                type="number"
                min="0"
                value={regularCapacity}
                onChange={(e) => setRegularCapacity(parseInt(e.target.value) || 0)}
                required
                className="w-full text-xs px-3 py-1.5 border border-slate-300 rounded bg-white"
              />
            </div>
            <div>
              <label htmlFor="node-cooled-cap" className="block text-xs font-semibold text-slate-600 mb-1">
                Configured Cooled Capacity Units
              </label>
              <input
                id="node-cooled-cap"
                type="number"
                min="0"
                value={cooledCapacity}
                onChange={(e) => setCooledCapacity(parseInt(e.target.value) || 0)}
                required
                className="w-full text-xs px-3 py-1.5 border border-slate-300 rounded bg-white"
              />
            </div>
            <button
              type="submit"
              disabled={actionLoading}
              className="w-full py-2 px-3 bg-amber-600 hover:bg-amber-700 text-white rounded text-xs font-semibold shadow-sm transition-colors"
            >
              Update Node Capacity
            </button>
          </form>
        </div>

        {/* Pre-Sealed Sample Registration */}
        <div className="bg-white p-5 rounded-xl border border-slate-200 shadow-sm space-y-4">
          <div className="flex items-center space-x-2 border-b border-slate-100 pb-2">
            <PlusCircle className="w-4 h-4 text-blue-600" />
            <h3 className="text-sm font-bold text-slate-900">Register Pre-Sealed Sample</h3>
          </div>
          <p className="text-xs text-slate-500">
            Intake a sample that was already collected & sealed at clinic/node. Creates transport legs onward.
          </p>

          <form onSubmit={handleIngestPresealed} className="space-y-3">
            <div>
              <label htmlFor="pre-sample-type" className="block text-xs font-semibold text-slate-600 mb-1">
                Sample Type
              </label>
              <select
                id="pre-sample-type"
                value={preSampleTypeId}
                onChange={(e) => setPreSampleTypeId(e.target.value)}
                className="w-full text-xs px-3 py-1.5 border border-slate-300 rounded bg-white"
              >
                <option value="11111111-1111-1111-1111-111111111111">Amber (Standard)</option>
                <option value="22222222-2222-2222-2222-222222222222">Indigo (Isolated)</option>
                <option value="33333333-3333-3333-3333-333333333333">Frost (Cooled)</option>
                <option value="44444444-4444-4444-4444-444444444444">Pulse (Rapid)</option>
              </select>
            </div>

            <div>
              <label htmlFor="pre-deadline" className="block text-xs font-semibold text-slate-600 mb-1">
                Delivery Deadline
              </label>
              <input
                id="pre-deadline"
                type="datetime-local"
                value={preDeadline}
                onChange={(e) => setPreDeadline(e.target.value)}
                required
                className="w-full text-xs px-3 py-1.5 border border-slate-300 rounded bg-white"
              />
            </div>

            <button
              type="submit"
              disabled={actionLoading}
              className="w-full py-2 px-3 bg-blue-600 hover:bg-blue-700 text-white rounded text-xs font-semibold shadow-sm transition-colors"
            >
              Register Pre-Sealed Sample
            </button>
          </form>
        </div>

        {/* Handoff Confirmation Tool */}
        <div className="bg-white p-5 rounded-xl border border-slate-200 shadow-sm space-y-4">
          <div className="flex items-center space-x-2 border-b border-slate-100 pb-2">
            <Check className="w-4 h-4 text-emerald-600" />
            <h3 className="text-sm font-bold text-slate-900">Confirm Incoming / Outgoing Handoff</h3>
          </div>
          <p className="text-xs text-slate-500">
            Confirm sample transfer between arriving courier and node handler.
          </p>

          <div className="space-y-3">
            <div>
              <label htmlFor="node-handoff-id" className="block text-xs font-semibold text-slate-600 mb-1">
                Handoff ID (UUID)
              </label>
              <input
                id="node-handoff-id"
                type="text"
                placeholder="Enter Handoff UUID"
                value={handoffId}
                onChange={(e) => setHandoffId(e.target.value)}
                className="w-full text-xs px-3 py-1.5 border border-slate-300 rounded bg-white"
              />
            </div>
            <button
              onClick={handleConfirmHandoff}
              disabled={actionLoading}
              className="w-full py-2 px-3 bg-emerald-600 hover:bg-emerald-700 text-white rounded text-xs font-semibold shadow-sm transition-colors"
            >
              Confirm Custody Transfer
            </button>
          </div>
        </div>
      </div>

      {/* Node Assignments & Timeline */}
      <div className="bg-white p-5 rounded-xl border border-slate-200 shadow-sm space-y-4">
        <h3 className="text-sm font-bold text-slate-900">Node Assignments & Work Items</h3>
        <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
          {work.inProgress.map((item) => {
            const aid = item.assignmentId || item.assignment_id || '';
            const sid = item.sampleId || item.sample_id || '';
            return (
              <div
                key={aid}
                onClick={() => setSelectedItem(item)}
                className="p-3 bg-slate-50 border border-slate-200 rounded-lg text-xs cursor-pointer hover:border-blue-400 space-y-1"
              >
                <div className="flex justify-between font-bold text-slate-800">
                  <span>Sample {sid.slice(0, 8)}...</span>
                  <span className="text-[10px] bg-blue-100 text-blue-800 px-1.5 py-0.5 rounded">{item.status}</span>
                </div>
                <div className="text-[10px] text-slate-400 font-mono">Assignment: {aid.slice(0, 8)}...</div>
              </div>
            );
          })}
        </div>

        {selectedItem && (
          <div className="pt-4 border-t border-slate-100">
            <TimelineView timeline={selectedItem.history || []} title="Node Assignment History" />
          </div>
        )}
      </div>
    </div>
  );
};

