import React, { useState, useEffect } from 'react';
import { api } from '../api/client';
import { TimelineView } from '../components/TimelineView';
import { RoleWork, RoleWorkItem, OperationsLocation } from '../types';
import { FlaskConical, Check, AlertTriangle, Shield, CheckCircle2, RefreshCw, AlertCircle } from 'lucide-react';

export const LabIntakeView: React.FC = () => {
  const [work, setWork] = useState<RoleWork>({ pending: [], inProgress: [], completed: [] });
  const [selectedItem, setSelectedItem] = useState<RoleWorkItem | null>(null);
  const [laboratories, setLaboratories] = useState<OperationsLocation[]>([]);
  const [selectedLabId, setSelectedLabId] = useState('');

  // Capacity config
  const [regularCapacity, setRegularCapacity] = useState(200);
  const [cooledCapacity, setCooledCapacity] = useState(100);

  // Receipt & Exception forms
  const [sampleIdInput, setSampleIdInput] = useState('');
  const [exceptionReason, setExceptionReason] = useState('Damaged sample container or compromised temperature');

  const [loading, setLoading] = useState(false);
  const [actionLoading, setActionLoading] = useState(false);
  const [actionMsg, setActionMsg] = useState<{ type: 'success' | 'error'; text: string } | null>(null);

  const fetchData = async () => {
    setLoading(true);
    try {
      const ops = await api.getOperationsState();
      const labs = (ops.locations || []).filter((l) => l.functions?.laboratory);
      setLaboratories(labs);
      if (labs.length > 0 && !selectedLabId) {
        setSelectedLabId(labs[0].locationId);
        setRegularCapacity(labs[0].capacity?.capacityUnits ?? 200);
        setCooledCapacity(labs[0].capacity?.cooledCapacityUnits ?? 100);
      }

      const workRes = await api.listRoleWork('laboratory_team');
      setWork(workRes || { pending: [], inProgress: [], completed: [] });
    } catch (e) {
      console.error(e);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchData();
  }, []);

  const handleLabSelect = (labId: string) => {
    setSelectedLabId(labId);
    const lab = laboratories.find((l) => l.locationId === labId);
    if (lab) {
      setRegularCapacity(lab.capacity?.capacityUnits ?? 200);
      setCooledCapacity(lab.capacity?.cooledCapacityUnits ?? 100);
    }
  };

  const handleUpdateCapacity = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedLabId) return;
    setActionLoading(true);
    setActionMsg(null);
    try {
      await api.configureCapacity(selectedLabId, regularCapacity, cooledCapacity);
      setActionMsg({ type: 'success', text: 'Laboratory capacity updated successfully!' });
      await fetchData();
    } catch (e: any) {
      setActionMsg({ type: 'error', text: e.message || 'Failed to update capacity' });
    } finally {
      setActionLoading(false);
    }
  };

  const handleConfirmReceipt = async (sampleId: string) => {
    if (!sampleId) {
      setActionMsg({ type: 'error', text: 'Sample ID required' });
      return;
    }
    setActionLoading(true);
    setActionMsg(null);
    try {
      await api.confirmLaboratoryReceipt(sampleId, selectedLabId || laboratories[0]?.locationId);
      setActionMsg({ type: 'success', text: `Sample ${sampleId} confirmed received at Laboratory!` });
      await fetchData();
    } catch (e: any) {
      setActionMsg({ type: 'error', text: e.message || 'Failed to confirm receipt' });
    } finally {
      setActionLoading(false);
    }
  };

  const handleRecordException = async (sampleId: string) => {
    if (!sampleId) {
      setActionMsg({ type: 'error', text: 'Sample ID required' });
      return;
    }
    setActionLoading(true);
    setActionMsg(null);
    try {
      await api.recordLaboratoryException(sampleId, selectedLabId || laboratories[0]?.locationId, exceptionReason);
      setActionMsg({ type: 'success', text: `Laboratory exception recorded for sample ${sampleId}!` });
      await fetchData();
    } catch (e: any) {
      setActionMsg({ type: 'error', text: e.message || 'Failed to record exception' });
    } finally {
      setActionLoading(false);
    }
  };

  const currentLab = laboratories.find((l) => l.locationId === selectedLabId);

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="bg-white p-5 rounded-xl border border-slate-200 shadow-sm flex items-center justify-between">
        <div className="flex items-center space-x-3">
          <div className="w-10 h-10 rounded-lg bg-purple-100 text-purple-700 flex items-center justify-center font-bold">
            <FlaskConical className="w-6 h-6" />
          </div>
          <div>
            <h2 className="text-base font-bold text-slate-900">Laboratory Intake Operator Dashboard</h2>
            <p className="text-xs text-slate-500">Confirm sample receipt, record exceptions, and manage laboratory capacity</p>
          </div>
        </div>
        <button
          onClick={fetchData}
          disabled={loading}
          className="inline-flex items-center px-3 py-1.5 border border-slate-300 rounded-md text-xs font-medium text-slate-700 bg-white hover:bg-slate-50 shadow-sm"
        >
          <RefreshCw className={`w-3.5 h-3.5 mr-1.5 ${loading ? 'animate-spin' : ''}`} />
          Refresh
        </button>
      </div>

      {actionMsg && (
        <div
          className={`p-3 rounded-lg border text-xs flex items-center space-x-2 ${
            actionMsg.type === 'success'
              ? 'bg-emerald-50 border-emerald-200 text-emerald-800'
              : 'bg-red-50 border-red-200 text-red-800'
          }`}
        >
          {actionMsg.type === 'success' ? <Check className="w-4 h-4" /> : <AlertCircle className="w-4 h-4" />}
          <span>{actionMsg.text}</span>
        </div>
      )}

      {/* Grid: Laboratory Capacity & Intake Actions */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Lab Capacity Configuration */}
        <div className="bg-white p-5 rounded-xl border border-slate-200 shadow-sm space-y-4">
          <div className="flex items-center space-x-2 border-b border-slate-100 pb-2">
            <Shield className="w-4 h-4 text-purple-600" />
            <h3 className="text-sm font-bold text-slate-900">Laboratory Capacity Configuration</h3>
          </div>

          <div>
            <label htmlFor="lab-select-assigned" className="block text-xs font-semibold text-slate-600 mb-1">
              Select Assigned Laboratory
            </label>
            <select
              id="lab-select-assigned"
              value={selectedLabId}
              onChange={(e) => handleLabSelect(e.target.value)}
              className="w-full text-xs px-3 py-2 border border-slate-300 rounded bg-white font-medium"
            >
              {laboratories.map((lab) => (
                <option key={lab.locationId} value={lab.locationId}>
                  {lab.name}
                </option>
              ))}
            </select>
          </div>

          {currentLab?.capacity && (
            <div className="p-3 bg-slate-50 rounded-lg border border-slate-200 text-xs space-y-1">
              <div className="flex justify-between">
                <span className="text-slate-500">Regular Capacity:</span>
                <span className="font-bold text-slate-800">
                  {currentLab.capacity.availableUnits} available / {currentLab.capacity.capacityUnits} total
                </span>
              </div>
              <div className="flex justify-between">
                <span className="text-slate-500">Cooled Capacity:</span>
                <span className="font-bold text-slate-800">
                  {currentLab.capacity.cooledAvailableUnits} available / {currentLab.capacity.cooledCapacityUnits} total
                </span>
              </div>
            </div>
          )}

          <form onSubmit={handleUpdateCapacity} className="space-y-3 pt-2">
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
              <div>
                <label htmlFor="lab-reg-cap" className="block text-xs font-semibold text-slate-600 mb-1">
                  Regular Capacity Units
                </label>
                <input
                  id="lab-reg-cap"
                  type="number"
                  min="0"
                  value={regularCapacity}
                  onChange={(e) => setRegularCapacity(parseInt(e.target.value) || 0)}
                  required
                  className="w-full text-xs px-3 py-1.5 border border-slate-300 rounded bg-white"
                />
              </div>
              <div>
                <label htmlFor="lab-cooled-cap" className="block text-xs font-semibold text-slate-600 mb-1">
                  Cooled Capacity Units
                </label>
                <input
                  id="lab-cooled-cap"
                  type="number"
                  min="0"
                  value={cooledCapacity}
                  onChange={(e) => setCooledCapacity(parseInt(e.target.value) || 0)}
                  required
                  className="w-full text-xs px-3 py-1.5 border border-slate-300 rounded bg-white"
                />
              </div>
            </div>
            <button
              type="submit"
              disabled={actionLoading}
              className="w-full py-2 px-3 bg-purple-600 hover:bg-purple-700 text-white rounded text-xs font-semibold shadow-sm transition-colors"
            >
              Update Laboratory Capacity
            </button>
          </form>
        </div>

        {/* Intake Actions: Confirm Receipt or Record Exception */}
        <div className="bg-white p-5 rounded-xl border border-slate-200 shadow-sm space-y-4">
          <div className="flex items-center space-x-2 border-b border-slate-100 pb-2">
            <CheckCircle2 className="w-4 h-4 text-purple-600" />
            <h3 className="text-sm font-bold text-slate-900">Confirm Receipt or Record Exception</h3>
          </div>

          <div className="space-y-3">
            <div>
              <label htmlFor="lab-sample-id-input" className="block text-xs font-semibold text-slate-600 mb-1">
                Sample ID (UUID)
              </label>
              <input
                id="lab-sample-id-input"
                type="text"
                placeholder="Enter or paste Sample UUID"
                value={sampleIdInput}
                onChange={(e) => setSampleIdInput(e.target.value)}
                className="w-full text-xs px-3 py-2 border border-slate-300 rounded bg-white"
              />
