                  onChange={(e) => setRegularCapacity(parseInt(e.target.value) || 0)}
                  required
                  className="w-full text-xs px-3 py-1.5 border border-slate-300 rounded bg-white"
                />
              </div>
              <div>
                <label htmlFor="lab-cooled-cap" className="block text-xs font-semibold text-slate-600 mb-1">
                  Cooled Capacity Units
                </label>
                <input
                  id="lab-cooled-cap"
                  type="number"
                  min="0"
                  value={cooledCapacity}
                  onChange={(e) => setCooledCapacity(parseInt(e.target.value) || 0)}
                  required
                  className="w-full text-xs px-3 py-1.5 border border-slate-300 rounded bg-white"
                />
              </div>
            </div>
            <button
              type="submit"
              disabled={actionLoading}
              className="w-full py-2 px-3 bg-purple-600 hover:bg-purple-700 text-white rounded text-xs font-semibold shadow-sm transition-colors"
            >
              Update Laboratory Capacity
            </button>
          </form>
        </div>

        {/* Intake Actions: Confirm Receipt or Record Exception */}
        <div className="bg-white p-5 rounded-xl border border-slate-200 shadow-sm space-y-4">
          <div className="flex items-center space-x-2 border-b border-slate-100 pb-2">
            <CheckCircle2 className="w-4 h-4 text-purple-600" />
            <h3 className="text-sm font-bold text-slate-900">Confirm Receipt or Record Exception</h3>
          </div>

          <div className="space-y-3">
            <div>
              <label htmlFor="lab-sample-id-input" className="block text-xs font-semibold text-slate-600 mb-1">
                Sample ID (UUID)
              </label>
              <input
                id="lab-sample-id-input"
                type="text"
                placeholder="Enter or paste Sample UUID"
                value={sampleIdInput}
                onChange={(e) => setSampleIdInput(e.target.value)}
                className="w-full text-xs px-3 py-2 border border-slate-300 rounded bg-white"
              />
            </div>

            <div>
              <label htmlFor="lab-exc-reason" className="block text-xs font-semibold text-slate-600 mb-1">
                Exception Reason (if recording an exception)
              </label>
              <input
                id="lab-exc-reason"
                type="text"
                value={exceptionReason}
                onChange={(e) => setExceptionReason(e.target.value)}
                className="w-full text-xs px-3 py-2 border border-slate-300 rounded bg-white"
              />
            </div>

            <div className="flex space-x-3 pt-2">
              <button
                onClick={() => handleConfirmReceipt(sampleIdInput)}
                disabled={actionLoading || !sampleIdInput}
                className="flex-1 py-2 px-3 bg-emerald-600 hover:bg-emerald-700 text-white rounded text-xs font-semibold shadow-sm transition-colors disabled:opacity-50 flex items-center justify-center"
              >
                <Check className="w-3.5 h-3.5 mr-1" /> Confirm Receipt
              </button>
              <button
                onClick={() => handleRecordException(sampleIdInput)}
                disabled={actionLoading || !sampleIdInput}
                className="flex-1 py-2 px-3 bg-rose-600 hover:bg-rose-700 text-white rounded text-xs font-semibold shadow-sm transition-colors disabled:opacity-50 flex items-center justify-center"
              >
                <AlertTriangle className="w-3.5 h-3.5 mr-1" /> Record Exception
              </button>
            </div>
          </div>
        </div>
      </div>

      {/* Expected Samples & Work Items */}
      <div className="bg-white p-5 rounded-xl border border-slate-200 shadow-sm space-y-4">
        <h3 className="text-sm font-bold text-slate-900">Expected Laboratory Samples & Intake Assignments</h3>
        <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
          {work.inProgress.map((item) => {
            const sid = item.sampleId || item.sample_id || '';
            const aid = item.assignmentId || item.assignment_id || '';
            return (
              <div
                key={aid}
                onClick={() => {
                  setSelectedItem(item);
                  setSampleIdInput(sid);
                }}
                className="p-3 bg-purple-50/50 border border-purple-200 rounded-lg text-xs cursor-pointer hover:border-purple-400 space-y-1.5"
              >
                <div className="flex justify-between font-bold text-slate-800">
                  <span>Sample {sid.slice(0, 8)}...</span>
                  <span className="text-[10px] bg-purple-100 text-purple-800 px-1.5 py-0.5 rounded">{item.status}</span>
                </div>
                <div className="flex space-x-2 pt-1">
                  <button
                    onClick={(e) => {
                      e.stopPropagation();
                      handleConfirmReceipt(sid);
                    }}
                    className="py-1 px-2 bg-emerald-600 text-white rounded text-[10px] font-semibold"
                  >
                    Confirm Receipt
                  </button>
                  <button
                    onClick={(e) => {
                      e.stopPropagation();
                      handleRecordException(sid);
                    }}
                    className="py-1 px-2 bg-rose-600 text-white rounded text-[10px] font-semibold"
                  >
                    Record Exception
                  </button>
                </div>
              </div>
            );
          })}
        </div>

        {selectedItem && (
          <div className="pt-4 border-t border-slate-100">
            <TimelineView timeline={selectedItem.history || []} title="Intake Assignment Status Timeline" />
          </div>
        )}
      </div>
    </div>
  );
};

