  const [ops, setOps] = useState<OperationsState | null>(null);
  const [loading, setLoading] = useState(false);
  const [selectedJourney, setSelectedJourney] = useState<JourneyPlan | null>(null);
  const [inspectLoading, setInspectLoading] = useState(false);

  // Action Dialogs
  const [disruptionModal, setDisruptionModal] = useState(false);
  const [disResType, setDisResType] = useState('worker');
  const [disResId, setDisResId] = useState('');
  const [disReason, setDisReason] = useState('Worker vehicle breakdown');

  const [rerouteModal, setRerouteModal] = useState(false);
  const [targetJourneyId, setTargetJourneyId] = useState('');
  const [planVersion, setPlanVersion] = useState(1);

  const [actionMsg, setActionMsg] = useState<{ type: 'success' | 'error'; text: string } | null>(null);

  const fetchOps = async () => {
    setLoading(true);
    try {
      const res = await api.getOperationsState();
      setOps(res);
    } catch (e) {
      console.error(e);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchOps();
    const interval = setInterval(fetchOps, 10000);
    return () => clearInterval(interval);
  }, []);

  const handleInspectJourney = async (journeyId: string) => {
    setInspectLoading(true);
    try {
      const res = await api.getJourneyPlan(journeyId);
      setSelectedJourney(res);
    } catch (e: any) {
      setActionMsg({ type: 'error', text: e.message || 'Failed to inspect journey' });
    } finally {
      setInspectLoading(false);
    }
  };

  const handleReportDisruption = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!disResId) return;
    try {
      const res = await api.reportDisruption({
        resourceType: disResType,
        resourceId: disResId,
        reason: disReason,
      });
      setActionMsg({ type: 'success', text: `Disruption reported! Replanning status: ${res.replanStatus}` });
      setDisruptionModal(false);
      await fetchOps();
    } catch (e: any) {
      setActionMsg({ type: 'error', text: e.message || 'Failed to report disruption' });
    }
  };

  const handleReroute = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!targetJourneyId) return;
    try {
      const res = await api.rerouteJourney(targetJourneyId, planVersion, 'Dispatcher manual reroute');
      setActionMsg({ type: 'success', text: `Journey rerouted! Replan status: ${res.replanStatus}` });
      setRerouteModal(false);
      await fetchOps();
    } catch (e: any) {
      setActionMsg({ type: 'error', text: e.message || 'Failed to reroute journey' });
    }
  };

  const handleCancelJourney = async (journeyId: string, version: number) => {
    try {
      await api.cancelJourney(journeyId, version, 'Dispatcher cancellation');
      setActionMsg({ type: 'success', text: `Journey ${journeyId} cancelled.` });
      await fetchOps();
    } catch (e: any) {
      setActionMsg({ type: 'error', text: e.message || 'Failed to cancel journey' });
    }
  };

  const samples = ops?.samples || [];
  const workers = ops?.workers || [];
  const locations = ops?.locations || [];
  const connections = ops?.connections || [];
  const exceptions = ops?.exceptions || [];
  const labs = locations.filter((l) => l.functions?.laboratory);
  const nodes = locations.filter((l) => !l.functions?.laboratory);

  return (
    <div className="space-y-6">
      {/* Header & Quick Action Buttons */}
      <div className="bg-white p-5 rounded-xl border border-slate-200 shadow-sm flex flex-wrap items-center justify-between gap-4">
        <div>
          <h2 className="text-base font-bold text-slate-900">Dispatcher Operations Monitor</h2>
          <p className="text-xs text-slate-500">Real-time custody tracking, workload spread, route monitoring, and exception recovery</p>
        </div>
        <div className="flex items-center space-x-2">
          <button
            onClick={() => setDisruptionModal(true)}
            className="inline-flex items-center px-3 py-1.5 bg-rose-600 hover:bg-rose-700 text-white rounded-md text-xs font-semibold shadow-sm transition-colors"
          >
            <AlertOctagon className="w-3.5 h-3.5 mr-1.5" />
            Report Disruption
          </button>
          <button
            onClick={() => setRerouteModal(true)}
            className="inline-flex items-center px-3 py-1.5 bg-blue-600 hover:bg-blue-700 text-white rounded-md text-xs font-semibold shadow-sm transition-colors"
          >
            <RotateCw className="w-3.5 h-3.5 mr-1.5" />
            Reroute Journey
          </button>
          <button
            onClick={fetchOps}
            disabled={loading}
            className="inline-flex items-center px-3 py-1.5 border border-slate-300 rounded-md text-xs font-medium text-slate-700 bg-white hover:bg-slate-50 shadow-sm"
          >
            <RefreshCw className={`w-3.5 h-3.5 mr-1.5 ${loading ? 'animate-spin' : ''}`} />
            Refresh
          </button>
        </div>
      </div>

      {actionMsg && (
        <div
          className={`p-3 rounded-lg border text-xs flex items-center space-x-2 ${
            actionMsg.type === 'success'
              ? 'bg-emerald-50 border-emerald-200 text-emerald-800'
              : 'bg-red-50 border-red-200 text-red-800'
          }`}
        >
          {actionMsg.type === 'success' ? <CheckCircle2 className="w-4 h-4" /> : <AlertTriangle className="w-4 h-4" />}
          <span>{actionMsg.text}</span>
        </div>
      )}

      {/* Category Overview Cards (monitor_dashboard_renders_categories) */}
      <div className="grid grid-cols-2 sm:grid-cols-4 lg:grid-cols-7 gap-3">
        <div className="bg-white p-3.5 rounded-xl border border-slate-200 shadow-sm">
          <span className="text-[10px] font-bold uppercase text-slate-400 block">Samples</span>
          <span className="text-xl font-black text-slate-900">{samples.length}</span>
        </div>
        <div className="bg-white p-3.5 rounded-xl border border-slate-200 shadow-sm">
          <span className="text-[10px] font-bold uppercase text-slate-400 block">Workers</span>
          <span className="text-xl font-black text-slate-900">{workers.length}</span>
        </div>
        <div className="bg-white p-3.5 rounded-xl border border-slate-200 shadow-sm">
          <span className="text-[10px] font-bold uppercase text-slate-400 block">Collection Nodes</span>
          <span className="text-xl font-black text-slate-900">{nodes.length}</span>
        </div>
        <div className="bg-white p-3.5 rounded-xl border border-slate-200 shadow-sm">
          <span className="text-[10px] font-bold uppercase text-slate-400 block">Laboratories</span>
          <span className="text-xl font-black text-slate-900">{labs.length}</span>
        </div>
        <div className="bg-white p-3.5 rounded-xl border border-slate-200 shadow-sm">
          <span className="text-[10px] font-bold uppercase text-slate-400 block">Connections</span>
          <span className="text-xl font-black text-slate-900">{connections.length}</span>
        </div>
        <div className="bg-white p-3.5 rounded-xl border border-slate-200 shadow-sm">
          <span className="text-[10px] font-bold uppercase text-slate-400 block">Exceptions</span>
          <span className={`text-xl font-black ${exceptions.length > 0 ? 'text-rose-600' : 'text-slate-900'}`}>
            {exceptions.length}
          </span>
        </div>
        <div className="bg-white p-3.5 rounded-xl border border-slate-200 shadow-sm">
          <span className="text-[10px] font-bold uppercase text-slate-400 block">Workload Spread</span>
          <span className="text-xl font-black text-slate-900">{ops?.assignmentCountSpread ?? 0}</span>
        </div>
      </div>

      {/* Live Map */}
      <div className="bg-white p-5 rounded-xl border border-slate-200 shadow-sm space-y-3">
        <h3 className="text-sm font-bold text-slate-900 flex items-center">
          <Activity className="w-4 h-4 mr-1.5 text-blue-600" />
          Bangalore Network Live Map
        </h3>
        <MapView locations={locations} connections={connections} workers={workers} samples={samples} />
      </div>

      {/* Tables Grid: Samples & Workers */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Active Samples Table */}
        <div className="bg-white p-5 rounded-xl border border-slate-200 shadow-sm space-y-4">
          <h3 className="text-sm font-bold text-slate-900">Tracked Samples & Custody</h3>
          <div className="overflow-x-auto border border-slate-200 rounded-lg max-h-[400px]">
            <table className="min-w-full divide-y divide-slate-200 text-xs text-left">
              <thead className="bg-slate-50 text-slate-600 font-semibold uppercase text-[10px]">
                <tr>
                  <th className="px-3 py-2">Sample ID</th>
                  <th className="px-3 py-2">Status</th>
                  <th className="px-3 py-2">Current Holder</th>
                  <th className="px-3 py-2">Freshness</th>
                  <th className="px-3 py-2">Actions</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100 bg-white">
                {samples.map((s) => (
                  <tr key={s.sampleId} className="hover:bg-slate-50">
                    <td className="px-3 py-2 font-mono font-medium">{s.sampleId.slice(0, 8)}...</td>
                    <td className="px-3 py-2">
                      <span className={`px-1.5 py-0.5 rounded text-[10px] font-bold ${
                        s.status === 'exception' ? 'bg-rose-100 text-rose-800' : 'bg-blue-100 text-blue-800'
                      }`}>
                        {s.status}
                      </span>
                    </td>
                    <td className="px-3 py-2 font-mono text-[10px] text-slate-600">
                      {s.currentHolderId ? `${s.currentHolderId.slice(0, 8)}...` : 'Pending'}
                    </td>
                    <td className="px-3 py-2">
                      <span className={`font-semibold ${s.locationStale ? 'text-amber-600' : 'text-emerald-600'}`}>
                        {s.locationStale ? 'Stale' : 'Fresh'}
                      </span>
                    </td>
                    <td className="px-3 py-2">
                      {s.activeJourneyId && (
                        <button
                          onClick={() => handleInspectJourney(s.activeJourneyId!)}
                          className="text-blue-600 hover:text-blue-800 font-semibold flex items-center"
                        >
                          <Eye className="w-3 h-3 mr-1" /> View Journey
                        </button>
                      )}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>

        {/* Workers Table */}
        <div className="bg-white p-5 rounded-xl border border-slate-200 shadow-sm space-y-4">
          <h3 className="text-sm font-bold text-slate-900">Network Workers & Active Workload</h3>
          <div className="overflow-x-auto border border-slate-200 rounded-lg max-h-[400px]">
            <table className="min-w-full divide-y divide-slate-200 text-xs text-left">
              <thead className="bg-slate-50 text-slate-600 font-semibold uppercase text-[10px]">
                <tr>
                  <th className="px-3 py-2">Worker</th>
                  <th className="px-3 py-2">Roles</th>
                  <th className="px-3 py-2">Availability</th>
                  <th className="px-3 py-2">Assignments</th>
                  <th className="px-3 py-2">Location</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100 bg-white">
                {workers.map((w) => (
                  <tr key={w.workerId} className="hover:bg-slate-50">
                    <td className="px-3 py-2 font-medium">{w.fullName || w.workerId.slice(0, 8)}</td>
                    <td className="px-3 py-2 text-[10px] text-slate-500">{(w.roles || []).join(', ')}</td>
                    <td className="px-3 py-2">
                      <span className={`px-1.5 py-0.5 rounded text-[10px] font-bold ${
                        w.available ? 'bg-emerald-100 text-emerald-800' : 'bg-slate-100 text-slate-700'
                      }`}>
                        {w.available ? 'Available' : 'Unavailable'}
                      </span>
                    </td>
                    <td className="px-3 py-2 font-bold text-slate-800">{w.assignmentCount}</td>
                    <td className="px-3 py-2">
                      <span className={`font-semibold ${w.locationStale ? 'text-amber-600' : 'text-emerald-600'}`}>
                        {w.locationStale ? 'Stale' : 'Fresh'}
                      </span>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      </div>

      {/* Disruption Modal */}
      {disruptionModal && (
        <div className="fixed inset-0 z-50 bg-slate-900/50 backdrop-blur-sm flex items-center justify-center p-4">
          <div className="bg-white rounded-2xl p-6 max-w-md w-full shadow-2xl border border-slate-200 space-y-4">
            <h3 className="text-base font-bold text-slate-900 flex items-center">
              <AlertOctagon className="w-5 h-5 mr-2 text-rose-600" />
              Report Disruption & Trigger Reroute
            </h3>
            <form onSubmit={handleReportDisruption} className="space-y-3">
              <div>
                <label htmlFor="dis-res-type" className="block text-xs font-semibold text-slate-600 mb-1">
                  Resource Type
                </label>
                <select
                  id="dis-res-type"
                  value={disResType}
                  onChange={(e) => setDisResType(e.target.value)}
                  className="w-full text-xs px-3 py-2 border border-slate-300 rounded bg-white"
                >
                  <option value="worker">Worker</option>
                  <option value="node">Node</option>
                  <option value="connection">Connection</option>
                  <option value="laboratory">Laboratory</option>
                </select>
              </div>

              <div>
                <label htmlFor="dis-res-id" className="block text-xs font-semibold text-slate-600 mb-1">
                  Resource ID (UUID)
                </label>
                <input
                  id="dis-res-id"
                  type="text"
                  required
                  placeholder="Enter affected UUID"
                  value={disResId}
                  onChange={(e) => setDisResId(e.target.value)}
                  className="w-full text-xs px-3 py-2 border border-slate-300 rounded"
                />
              </div>

              <div>
                <label htmlFor="dis-reason" className="block text-xs font-semibold text-slate-600 mb-1">
                  Reason for Disruption
                </label>
                <input
                  id="dis-reason"
                  type="text"
                  value={disReason}
                  onChange={(e) => setDisReason(e.target.value)}
                  className="w-full text-xs px-3 py-2 border border-slate-300 rounded"
                />
              </div>

              <div className="flex space-x-3 pt-2">
                <button
                  type="submit"
                  className="flex-1 py-2 px-3 bg-rose-600 text-white rounded font-semibold text-xs shadow-sm hover:bg-rose-700"
                >
                  Confirm & Replan
                </button>
                <button
                  type="button"
                  onClick={() => setDisruptionModal(false)}
                  className="px-4 py-2 border border-slate-300 rounded font-semibold text-xs text-slate-700 hover:bg-slate-50"
                >
                  Cancel
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Reroute Modal */}
      {rerouteModal && (
        <div className="fixed inset-0 z-50 bg-slate-900/50 backdrop-blur-sm flex items-center justify-center p-4">
          <div className="bg-white rounded-2xl p-6 max-w-md w-full shadow-2xl border border-slate-200 space-y-4">
            <h3 className="text-base font-bold text-slate-900 flex items-center">
              <RotateCw className="w-5 h-5 mr-2 text-blue-600" />
              Reroute Active Journey
            </h3>
            <form onSubmit={handleReroute} className="space-y-3">
              <div>
                <label htmlFor="reroute-journey-id" className="block text-xs font-semibold text-slate-600 mb-1">
                  Journey ID (UUID)
                </label>
                <input
                  id="reroute-journey-id"
                  type="text"
                  required
                  placeholder="Enter Journey UUID"
                  value={targetJourneyId}
                  onChange={(e) => setTargetJourneyId(e.target.value)}
                  className="w-full text-xs px-3 py-2 border border-slate-300 rounded"
                />
              </div>

              <div>
                <label htmlFor="reroute-plan-version" className="block text-xs font-semibold text-slate-600 mb-1">
                  Expected Plan Version
                </label>
                <input
                  id="reroute-plan-version"
                  type="number"
                  min="1"
                  required
                  value={planVersion}
                  onChange={(e) => setPlanVersion(parseInt(e.target.value) || 1)}
                  className="w-full text-xs px-3 py-2 border border-slate-300 rounded"
                />
              </div>

              <div className="flex space-x-3 pt-2">
                <button
                  type="submit"
                  className="flex-1 py-2 px-3 bg-blue-600 text-white rounded font-semibold text-xs shadow-sm hover:bg-blue-700"
                >
                  Execute Reroute
                </button>
                <button
                  type="button"
                  onClick={() => setRerouteModal(false)}
                  className="px-4 py-2 border border-slate-300 rounded font-semibold text-xs text-slate-700 hover:bg-slate-50"
                >
                  Cancel
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Journey Detail Inspection Modal */}
      {selectedJourney && (
        <div className="fixed inset-0 z-50 bg-slate-900/50 backdrop-blur-sm flex items-center justify-center p-4">
          <div className="bg-white rounded-2xl p-6 max-w-2xl w-full shadow-2xl border border-slate-200 space-y-4 max-h-[85vh] overflow-y-auto">
            <div className="flex items-center justify-between border-b border-slate-100 pb-3">
              <div>
                <h3 className="text-base font-bold text-slate-900">
                  Journey Plan: <span className="font-mono text-xs text-slate-600">{selectedJourney.journeyId}</span>
                </h3>
                <span className="text-xs text-slate-400">
                  Plan Version: v{selectedJourney.planVersion} • Route Mode: {selectedJourney.routeMode} • Status: {selectedJourney.status}
                </span>
              </div>
              <button
                onClick={() => setSelectedJourney(null)}
                className="p-1.5 text-slate-400 hover:text-slate-700 rounded-lg"
              >
                <XCircle className="w-5 h-5" />
              </button>
            </div>

            {/* Stops */}
            <div>
              <h4 className="text-xs font-bold uppercase text-slate-600 mb-2">Ordered Stops ({selectedJourney.orderedStops?.length || 0})</h4>
              <div className="space-y-1.5">
                {selectedJourney.orderedStops?.map((st) => (
                  <div key={st.stopId} className="p-2.5 bg-slate-50 rounded border border-slate-200 text-xs flex justify-between items-center">
                    <div>
                      <span className="font-bold text-slate-800">{st.sequence}. {st.stopType.toUpperCase()}</span>
                      <span className="text-slate-500 ml-2 font-mono">{st.locationId.slice(0, 8)}...</span>
                    </div>
                    <span className="text-slate-400 flex items-center text-[11px]">
                      <Clock className="w-3 h-3 mr-1" />
                      {new Date(st.estimatedAt).toLocaleTimeString()}
                    </span>
                  </div>
                ))}
              </div>
            </div>

            {/* Legs & Assignments */}
            <div>
              <h4 className="text-xs font-bold uppercase text-slate-600 mb-2">Transport Legs & Assignments ({selectedJourney.legs?.length || 0})</h4>
              <div className="space-y-1.5">
                {selectedJourney.legs?.map((l) => (
                  <div key={l.assignmentId} className="p-2.5 bg-slate-50 rounded border border-slate-200 text-xs flex justify-between items-center">
                    <div>
                      <span className="font-bold text-slate-800">Leg #{l.sequence}</span>
                      <span className="text-slate-500 ml-2">Status: <span className="font-semibold text-blue-600">{l.status}</span></span>
                      {l.workerId && <span className="text-slate-400 ml-2 font-mono">Worker: {l.workerId.slice(0, 8)}...</span>}
                    </div>
                  </div>
                ))}
              </div>
            </div>

            {/* Actions: Cancel */}
            <div className="pt-3 border-t border-slate-100 flex justify-end space-x-2">
              <button
                onClick={() => handleCancelJourney(selectedJourney.journeyId, selectedJourney.planVersion)}
                className="px-3 py-1.5 bg-rose-600 hover:bg-rose-700 text-white rounded text-xs font-semibold"
              >
                Cancel Journey
              </button>
              <button
                onClick={() => setSelectedJourney(null)}
                className="px-3 py-1.5 border border-slate-300 rounded text-xs text-slate-700"
              >
                Close
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

