import React, { useState, useEffect } from 'react';
import { api } from '../api/client';
import { OperationsLocation, OperationsConnection, SampleType } from '../types';
import {
  Users, MapPin, GitCommit, Settings, PlusCircle, Check,
  ToggleLeft, ToggleRight, RefreshCw, AlertCircle
} from 'lucide-react';

export const AdminManagementView: React.FC = () => {
  const [activeSection, setActiveSection] = useState<'users' | 'locations' | 'connections' | 'sampleTypes'>('users');
  const [locations, setLocations] = useState<OperationsLocation[]>([]);
  const [connections, setConnections] = useState<OperationsConnection[]>([]);
  const [loading, setLoading] = useState(false);
  const [actionMsg, setActionMsg] = useState<{ type: 'success' | 'error'; text: string } | null>(null);

  // New User Form State
  const [newUsername, setNewUsername] = useState('');
  const [newPassword, setNewPassword] = useState('');
  const [newFullName, setNewFullName] = useState('');
  const [newRole, setNewRole] = useState('collection_professional');
  const [newQual, setNewQual] = useState('QUAL_AMBER');

  // New Location Form State
  const [newLocName, setNewLocName] = useState('');
  const [newLocLat, setNewLocLat] = useState('12.9716');
  const [newLocLng, setNewLocLng] = useState('77.5946');
  const [isColPoint, setIsColPoint] = useState(true);
  const [isTransferPoint, setIsTransferPoint] = useState(true);
  const [isHub, setIsHub] = useState(false);
  const [isLab, setIsLab] = useState(false);

  // New Connection Form State
  const [fromLocId, setFromLocId] = useState('');
  const [toLocId, setToLocId] = useState('');
  const [travelMin, setTravelMin] = useState(25);
  const [costUnits, setCostUnits] = useState(2.5);
  const [connCooled, setConnCooled] = useState(true);

  // Sample Type Form State
  const [stName, setStName] = useState('');
  const [stContainer, setStContainer] = useState('standard_ambient');
  const [stMinTemp, setStMinTemp] = useState(15);
  const [stMaxTemp, setStMaxTemp] = useState(25);
  const [stCooled, setStCooled] = useState(false);
  const [stBatch, setStBatch] = useState(true);

  const fetchNetworkData = async () => {
    setLoading(true);
    try {
      const ops = await api.getOperationsState();
      setLocations(ops.locations || []);
      setConnections(ops.connections || []);
      if (ops.locations?.length > 1) {
        setFromLocId(ops.locations[0].locationId);
        setToLocId(ops.locations[1].locationId);
      }
    } catch (e) {
      console.error(e);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchNetworkData();
  }, []);

  const handleCreateUser = async (e: React.FormEvent) => {
    e.preventDefault();
    setActionMsg(null);
    try {
      const certs = newRole === 'collection_professional' ? [{ code: newQual, active: true }] : [];
      const quals = newRole === 'collection_professional' ? [newQual] : [];

      await api.createUser({
        username: newUsername,
        initialPassword: newPassword,
        fullName: newFullName || undefined,
        roles: [newRole],
        qualifications: quals,
        certifications: certs,
        active: true,
      });
      setActionMsg({ type: 'success', text: `User ${newUsername} created successfully!` });
      setNewUsername('');
      setNewPassword('');
      setNewFullName('');
    } catch (e: any) {
      setActionMsg({ type: 'error', text: e.message || 'Failed to create user' });
    }
  };

