                  value={stMinTemp}
                  onChange={(e) => setStMinTemp(parseFloat(e.target.value))}
                  required
                  className="w-full text-xs px-3 py-2 border border-slate-300 rounded"
                />
              </div>
              <div>
                <label htmlFor="st-max-temp" className="block text-xs font-semibold text-slate-600 mb-1">
                  Max Temperature (°C)
                </label>
                <input
                  id="st-max-temp"
                  type="number"
                  step="0.5"
                  value={stMaxTemp}
                  onChange={(e) => setStMaxTemp(parseFloat(e.target.value))}
                  required
                  className="w-full text-xs px-3 py-2 border border-slate-300 rounded"
                />
              </div>
            </div>

            <div className="flex space-x-6 text-xs">
              <label className="flex items-center space-x-2 cursor-pointer font-medium text-slate-700">
                <input type="checkbox" checked={stCooled} onChange={(e) => setStCooled(e.target.checked)} />
                <span>Requires Cooled Route Throughout</span>
              </label>
              <label className="flex items-center space-x-2 cursor-pointer font-medium text-slate-700">
                <input type="checkbox" checked={stBatch} onChange={(e) => setStBatch(e.target.checked)} />
                <span>Consolidation Batching Allowed</span>
              </label>
            </div>

            <button type="submit" className="py-2 px-4 bg-blue-600 hover:bg-blue-700 text-white rounded text-xs font-bold">
              Save Sample Type
            </button>
          </form>
        </div>
      )}
    </div>
  );
};

