import React, { useState, useEffect } from 'react';
import { api } from '../api/client';
import { OperationsLocation, OperationsConnection, SampleType } from '../types';
import {
  Users, MapPin, GitCommit, Settings, PlusCircle, Check,
  ToggleLeft, ToggleRight, RefreshCw, AlertCircle
} from 'lucide-react';

export const AdminManagementView: React.FC = () => {
  const [activeSection, setActiveSection] = useState<'users' | 'locations' | 'connections' | 'sampleTypes'>('users');
  const [locations, setLocations] = useState<OperationsLocation[]>([]);
  const [connections, setConnections] = useState<OperationsConnection[]>([]);
  const [loading, setLoading] = useState(false);
  const [actionMsg, setActionMsg] = useState<{ type: 'success' | 'error'; text: string } | null>(null);

  // New User Form State
  const [newUsername, setNewUsername] = useState('');
  const [newPassword, setNewPassword] = useState('');
  const [newFullName, setNewFullName] = useState('');
  const [newRole, setNewRole] = useState('collection_professional');
  const [newQual, setNewQual] = useState('QUAL_AMBER');

  // New Location Form State
  const [newLocName, setNewLocName] = useState('');
  const [newLocLat, setNewLocLat] = useState('12.9716');
  const [newLocLng, setNewLocLng] = useState('77.5946');
  const [isColPoint, setIsColPoint] = useState(true);
  const [isTransferPoint, setIsTransferPoint] = useState(true);
  const [isHub, setIsHub] = useState(false);
  const [isLab, setIsLab] = useState(false);

  // New Connection Form State
  const [fromLocId, setFromLocId] = useState('');
  const [toLocId, setToLocId] = useState('');
  const [travelMin, setTravelMin] = useState(25);
  const [costUnits, setCostUnits] = useState(2.5);
  const [connCooled, setConnCooled] = useState(true);

  // Sample Type Form State
  const [stName, setStName] = useState('');
  const [stContainer, setStContainer] = useState('standard_ambient');
  const [stMinTemp, setStMinTemp] = useState(15);
  const [stMaxTemp, setStMaxTemp] = useState(25);
  const [stCooled, setStCooled] = useState(false);
  const [stBatch, setStBatch] = useState(true);

  const fetchNetworkData = async () => {
    setLoading(true);
    try {
      const ops = await api.getOperationsState();
      setLocations(ops.locations || []);
      setConnections(ops.connections || []);
      if (ops.locations?.length > 1) {
        setFromLocId(ops.locations[0].locationId);
        setToLocId(ops.locations[1].locationId);
      }
    } catch (e) {
      console.error(e);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchNetworkData();
  }, []);

  const handleCreateUser = async (e: React.FormEvent) => {
    e.preventDefault();
    setActionMsg(null);
    try {
      const certs = newRole === 'collection_professional' ? [{ code: newQual, active: true }] : [];
      const quals = newRole === 'collection_professional' ? [newQual] : [];

      await api.createUser({
        username: newUsername,
        initialPassword: newPassword,
        fullName: newFullName || undefined,
        roles: [newRole],
        qualifications: quals,
        certifications: certs,
        active: true,
      });
      setActionMsg({ type: 'success', text: `User ${newUsername} created successfully!` });
      setNewUsername('');
      setNewPassword('');
      setNewFullName('');
    } catch (e: any) {
      setActionMsg({ type: 'error', text: e.message || 'Failed to create user' });
    }
  };

  const handleCreateLocation = async (e: React.FormEvent) => {
    e.preventDefault();
    setActionMsg(null);
    try {
      await api.createLocation({
        name: newLocName,
        coordinate: { latitude: parseFloat(newLocLat), longitude: parseFloat(newLocLng) },
        coverageKm: 5.0,
        handlingMinutes: 15,
        active: true,
        functions: {
          collection_point: isColPoint,
          transfer_point: isTransferPoint,
          hub: isHub,
          laboratory: isLab,
        },
      });
      setActionMsg({ type: 'success', text: `Location ${newLocName} created!` });
      setNewLocName('');
      await fetchNetworkData();
    } catch (e: any) {
      setActionMsg({ type: 'error', text: e.message || 'Failed to create location' });
    }
  };

  const handleToggleLocationStatus = async (locationId: string, currentActive: boolean) => {
    try {
      await api.setLocationStatus(locationId, !currentActive);
      await fetchNetworkData();
    } catch (e: any) {
      setActionMsg({ type: 'error', text: e.message || 'Failed to toggle location status' });
    }
  };

  const handleToggleFunctionStatus = async (locationId: string, func: string, currentActive: boolean) => {
    try {
      await api.setLocationFunctionStatus(locationId, func, !currentActive);
      await fetchNetworkData();
    } catch (e: any) {
      setActionMsg({ type: 'error', text: e.message || 'Failed to toggle function' });
    }
  };

  const handleCreateConnection = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!fromLocId || !toLocId) return;
    setActionMsg(null);
    try {
      await api.createConnection({
        fromLocationId: fromLocId,
        toLocationId: toLocId,
        travelMinutes: travelMin,
        costUnits,
        cooled: connCooled,
        active: true,
      });
      setActionMsg({ type: 'success', text: 'Connection created successfully!' });
      await fetchNetworkData();
    } catch (e: any) {
      setActionMsg({ type: 'error', text: e.message || 'Failed to create connection' });
    }
  };

  const handleToggleConnectionStatus = async (connectionId: string, currentActive: boolean) => {
    try {
      await api.setConnectionStatus(connectionId, !currentActive);
      await fetchNetworkData();
    } catch (e: any) {
      setActionMsg({ type: 'error', text: e.message || 'Failed to toggle connection' });
    }
  };

  const handleCreateSampleType = async (e: React.FormEvent) => {
    e.preventDefault();
    setActionMsg(null);
    try {
      await api.createSampleType({
        name: stName,
        qualifiedCollectorRequired: true,
        requiredQualification: `QUAL_${stName.toUpperCase()}`,
        containerType: stContainer,
        temperatureMinC: stMinTemp,
        temperatureMaxC: stMaxTemp,
        incompatibleSampleTypes: [],
        requiresCooledRoute: stCooled,
        batchingAllowed: stBatch,
      });
      setActionMsg({ type: 'success', text: `Sample Type ${stName} created successfully!` });
      setStName('');
    } catch (e: any) {
      setActionMsg({ type: 'error', text: e.message || 'Failed to create sample type' });
    }
  };

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="bg-white p-5 rounded-xl border border-slate-200 shadow-sm flex items-center justify-between">
        <div className="flex items-center space-x-3">
          <div className="w-10 h-10 rounded-lg bg-blue-100 text-blue-700 flex items-center justify-center font-bold">
            <Settings className="w-6 h-6" />
          </div>
          <div>
            <h2 className="text-base font-bold text-slate-900">Administrator Management Console</h2>
            <p className="text-xs text-slate-500">Configure users, professional qualifications, network nodes, connections, and sample handling</p>
          </div>
        </div>
        <button
          onClick={fetchNetworkData}
          disabled={loading}
          className="inline-flex items-center px-3 py-1.5 border border-slate-300 rounded-md text-xs font-medium text-slate-700 bg-white hover:bg-slate-50 shadow-sm"
        >
          <RefreshCw className={`w-3.5 h-3.5 mr-1.5 ${loading ? 'animate-spin' : ''}`} />
          Refresh
        </button>
      </div>

      {actionMsg && (
        <div
          className={`p-3 rounded-lg border text-xs flex items-center space-x-2 ${
            actionMsg.type === 'success'
              ? 'bg-emerald-50 border-emerald-200 text-emerald-800'
              : 'bg-red-50 border-red-200 text-red-800'
          }`}
        >
          {actionMsg.type === 'success' ? <Check className="w-4 h-4" /> : <AlertCircle className="w-4 h-4" />}
          <span>{actionMsg.text}</span>
        </div>
      )}

      {/* Navigation Pill Buttons */}
      <div className="flex space-x-2 border-b border-slate-200 pb-3">
        <button
          onClick={() => setActiveSection('users')}
          className={`px-4 py-2 rounded-lg text-xs font-bold transition-colors flex items-center ${
            activeSection === 'users' ? 'bg-blue-600 text-white' : 'bg-white text-slate-600 border border-slate-200 hover:bg-slate-50'
          }`}
        >
          <Users className="w-3.5 h-3.5 mr-1.5" /> Users & Certifications
        </button>
        <button
          onClick={() => setActiveSection('locations')}
          className={`px-4 py-2 rounded-lg text-xs font-bold transition-colors flex items-center ${
            activeSection === 'locations' ? 'bg-blue-600 text-white' : 'bg-white text-slate-600 border border-slate-200 hover:bg-slate-50'
          }`}
        >
          <MapPin className="w-3.5 h-3.5 mr-1.5" /> Nodes & Laboratories
        </button>
        <button
          onClick={() => setActiveSection('connections')}
          className={`px-4 py-2 rounded-lg text-xs font-bold transition-colors flex items-center ${
            activeSection === 'connections' ? 'bg-blue-600 text-white' : 'bg-white text-slate-600 border border-slate-200 hover:bg-slate-50'
          }`}
        >
          <GitCommit className="w-3.5 h-3.5 mr-1.5" /> Network Connections
        </button>
        <button
          onClick={() => setActiveSection('sampleTypes')}
          className={`px-4 py-2 rounded-lg text-xs font-bold transition-colors flex items-center ${
            activeSection === 'sampleTypes' ? 'bg-blue-600 text-white' : 'bg-white text-slate-600 border border-slate-200 hover:bg-slate-50'
          }`}
        >
          <PlusCircle className="w-3.5 h-3.5 mr-1.5" /> Sample Types & Handling
        </button>
      </div>

      {/* SECTION 1: USERS & CERTIFICATIONS */}
      {activeSection === 'users' && (
        <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm space-y-4 max-w-2xl">
          <h3 className="text-sm font-bold text-slate-900 border-b border-slate-100 pb-2">Onboard New User / Worker</h3>
          <form onSubmit={handleCreateUser} className="space-y-4">
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
              <div>
                <label htmlFor="adm-username" className="block text-xs font-semibold text-slate-600 mb-1">
                  Username
                </label>
                <input
                  id="adm-username"
                  type="text"
                  required
                  value={newUsername}
                  onChange={(e) => setNewUsername(e.target.value)}
                  className="w-full text-xs px-3 py-2 border border-slate-300 rounded"
                />
              </div>
              <div>
                <label htmlFor="adm-password" className="block text-xs font-semibold text-slate-600 mb-1">
                  Initial Password
                </label>
                <input
                  id="adm-password"
                  type="password"
                  required
                  value={newPassword}
                  onChange={(e) => setNewPassword(e.target.value)}
                  className="w-full text-xs px-3 py-2 border border-slate-300 rounded"
                />
              </div>
            </div>

            <div>
              <label htmlFor="adm-fullname" className="block text-xs font-semibold text-slate-600 mb-1">
                Full Name
              </label>
              <input
                id="adm-fullname"
                type="text"
                value={newFullName}
                onChange={(e) => setNewFullName(e.target.value)}
                className="w-full text-xs px-3 py-2 border border-slate-300 rounded"
              />
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
              <div>
                <label htmlFor="adm-role" className="block text-xs font-semibold text-slate-600 mb-1">
                  Assigned Primary Role
                </label>
                <select
                  id="adm-role"
                  value={newRole}
                  onChange={(e) => setNewRole(e.target.value)}
                  className="w-full text-xs px-3 py-2 border border-slate-300 rounded bg-white"
                >
                  <option value="collection_professional">Certified Collection Professional</option>
                  <option value="delivery_partner">Relay Courier (Delivery Partner)</option>
                  <option value="node_handler">Node Handler</option>
                  <option value="laboratory_team">Laboratory Intake Operator</option>
                  <option value="dispatcher">Dispatcher</option>
                  <option value="requester">Requester</option>
                  <option value="administrator">Administrator</option>
                </select>
              </div>

              {newRole === 'collection_professional' && (
                <div>
                  <label htmlFor="adm-qual" className="block text-xs font-semibold text-slate-600 mb-1">
                    Professional Qualification
                  </label>
                  <select
                    id="adm-qual"
                    value={newQual}
                    onChange={(e) => setNewQual(e.target.value)}
                    className="w-full text-xs px-3 py-2 border border-slate-300 rounded bg-white"
                  >
                    <option value="QUAL_AMBER">QUAL_AMBER (Amber Certified)</option>
                    <option value="QUAL_INDIGO">QUAL_INDIGO (Indigo Certified)</option>
                    <option value="QUAL_FROST">QUAL_FROST (Frost Cold-Chain Certified)</option>
                    <option value="QUAL_PULSE">QUAL_PULSE (Pulse Rapid-Transit Certified)</option>
                  </select>
                </div>
              )}
            </div>

            <button
              type="submit"
              className="py-2 px-4 bg-blue-600 hover:bg-blue-700 text-white rounded text-xs font-bold shadow-sm"
            >
              Create & Onboard User
            </button>
          </form>
        </div>
      )}

      {/* SECTION 2: NODES & LABORATORIES */}
      {activeSection === 'locations' && (
        <div className="space-y-6">
          {/* Create Location Form */}
          <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm space-y-4 max-w-2xl">
            <h3 className="text-sm font-bold text-slate-900 border-b border-slate-100 pb-2">Add New Network Location / Node</h3>
            <form onSubmit={handleCreateLocation} className="space-y-4">
              <div>
                <label htmlFor="adm-loc-name" className="block text-xs font-semibold text-slate-600 mb-1">
                  Location Name
                </label>
                <input
                  id="adm-loc-name"
                  type="text"
                  required
                  placeholder="e.g. MG Road Collection Point"
                  value={newLocName}
                  onChange={(e) => setNewLocName(e.target.value)}
                  className="w-full text-xs px-3 py-2 border border-slate-300 rounded"
                />
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                <div>
                  <label htmlFor="adm-loc-lat" className="block text-xs font-semibold text-slate-600 mb-1">
                    Latitude
                  </label>
                  <input
                    id="adm-loc-lat"
                    type="number"
                    step="any"
                    value={newLocLat}
                    onChange={(e) => setNewLocLat(e.target.value)}
                    required
                    className="w-full text-xs px-3 py-2 border border-slate-300 rounded"
                  />
                </div>
                <div>
                  <label htmlFor="adm-loc-lng" className="block text-xs font-semibold text-slate-600 mb-1">
                    Longitude
                  </label>
                  <input
                    id="adm-loc-lng"
                    type="number"
                    step="any"
                    value={newLocLng}
                    onChange={(e) => setNewLocLng(e.target.value)}
                    required
                    className="w-full text-xs px-3 py-2 border border-slate-300 rounded"
                  />
                </div>
              </div>

              <div>
                <span className="block text-xs font-semibold text-slate-600 mb-2">Location Functions</span>
                <div className="grid grid-cols-2 sm:grid-cols-4 gap-2 text-xs">
                  <label className="flex items-center space-x-2 bg-slate-50 p-2 rounded border border-slate-200 cursor-pointer">
                    <input type="checkbox" checked={isColPoint} onChange={(e) => setIsColPoint(e.target.checked)} />
                    <span>Collection Point</span>
                  </label>
                  <label className="flex items-center space-x-2 bg-slate-50 p-2 rounded border border-slate-200 cursor-pointer">
                    <input type="checkbox" checked={isTransferPoint} onChange={(e) => setIsTransferPoint(e.target.checked)} />
                    <span>Transfer Point</span>
                  </label>
                  <label className="flex items-center space-x-2 bg-slate-50 p-2 rounded border border-slate-200 cursor-pointer">
                    <input type="checkbox" checked={isHub} onChange={(e) => setIsHub(e.target.checked)} />
                    <span>Hub</span>
                  </label>
                  <label className="flex items-center space-x-2 bg-slate-50 p-2 rounded border border-slate-200 cursor-pointer">
                    <input type="checkbox" checked={isLab} onChange={(e) => setIsLab(e.target.checked)} />
                    <span>Laboratory</span>
                  </label>
                </div>
              </div>

              <button type="submit" className="py-2 px-4 bg-blue-600 hover:bg-blue-700 text-white rounded text-xs font-bold">
                Create Location
              </button>
            </form>
          </div>

          {/* Locations Table with Dynamic Function Toggles */}
          <div className="bg-white p-5 rounded-xl border border-slate-200 shadow-sm space-y-4">
            <h3 className="text-sm font-bold text-slate-900">Manage Network Locations & Functions</h3>
            <div className="overflow-x-auto border border-slate-200 rounded-lg">
              <table className="min-w-full divide-y divide-slate-200 text-xs text-left">
                <thead className="bg-slate-50 text-slate-600 font-semibold uppercase text-[10px]">
                  <tr>
                    <th className="px-3 py-2">Location</th>
