import React, { useState, useEffect } from 'react';
import { api, clearToken, getToken } from './api/client';
import { Navbar } from './components/Navbar';
import { MapView } from './components/MapView';
import { AuditSearch } from './components/AuditSearch';
import { LoginView } from './views/LoginView';
import { RequesterView } from './views/RequesterView';
import { CollectorView } from './views/CollectorView';
import { CourierView } from './views/CourierView';
import { NodeHandlerView } from './views/NodeHandlerView';
import { LabIntakeView } from './views/LabIntakeView';
import { DispatcherMonitorView } from './views/DispatcherMonitorView';
import { AdminManagementView } from './views/AdminManagementView';
import { User, OperationsLocation, OperationsConnection } from './types';
import { Loader2 } from 'lucide-react';

export const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);
  const [activeTab, setActiveTab] = useState('dashboard');

  // Network state for map tab
  const [locations, setLocations] = useState<OperationsLocation[]>([]);
  const [connections, setConnections] = useState<OperationsConnection[]>([]);
  const [workers, setWorkers] = useState<any[]>([]);
  const [samples, setSamples] = useState<any[]>([]);

  const loadBootstrap = async () => {
    const token = getToken();
    if (!token) {
      setCurrentUser(null);
      setLoading(false);
      return;
    }

    try {
      const res = await api.getBootstrap();
      setCurrentUser(res.user);
      if (res.operations) {
        setLocations(res.operations.locations || []);
        setConnections(res.operations.connections || []);
        setWorkers(res.operations.workers || []);
        setSamples(res.operations.samples || []);
      }
    } catch (e) {
      clearToken();
      setCurrentUser(null);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadBootstrap();
  }, []);

  const handleRoleChanged = (newRole: string) => {
    if (currentUser) {
      setCurrentUser({ ...currentUser, activeRole: newRole });
      setActiveTab('dashboard');
    }
  };

  const handleSignOut = () => {
    clearToken();
    setCurrentUser(null);
    setActiveTab('dashboard');
  };

  if (loading) {
    return (
      <div className="min-h-screen bg-slate-900 flex items-center justify-center text-white">
        <div className="flex items-center space-x-3 text-sm font-semibold">
          <Loader2 className="w-5 h-5 animate-spin text-blue-500" />
          <span>Loading Clinical Logistics System...</span>
        </div>
      </div>
    );
  }

  if (!currentUser) {
    return <LoginView onLoginSuccess={(u) => setCurrentUser(u)} />;
  }

  const renderDashboard = () => {
    switch (currentUser.activeRole) {
      case 'requester':
        return <RequesterView />;
      case 'collection_professional':
        return <CollectorView />;
      case 'delivery_partner':
        return <CourierView />;
      case 'node_handler':
        return <NodeHandlerView />;
      case 'laboratory_team':
        return <LabIntakeView />;
      case 'dispatcher':
      case 'administrator':
        return <DispatcherMonitorView />;
      default:
        return <RequesterView />;
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 text-slate-900 flex flex-col">
      <Navbar
        user={currentUser}
        activeTab={activeTab}
        onTabChange={setActiveTab}
        onRoleChanged={handleRoleChanged}
        onSignOut={handleSignOut}
      />

      <main className="flex-1 max-w-7xl w-full mx-auto px-4 sm:px-6 lg:px-8 py-6">
        {activeTab === 'dashboard' && renderDashboard()}
        {activeTab === 'map' && (
          <div className="bg-white p-5 rounded-xl border border-slate-200 shadow-sm space-y-4">
            <h2 className="text-base font-bold text-slate-900">Bangalore Transport & Node Live Map</h2>
            <MapView locations={locations} connections={connections} workers={workers} samples={samples} />
          </div>
        )}
        {activeTab === 'audit' && <AuditSearch />}
        {activeTab === 'admin' && currentUser.activeRole === 'administrator' && <AdminManagementView />}
      </main>

      <footer className="bg-white border-t border-slate-200 py-4 text-center text-xs text-slate-400">
        Lab Sample Pickup & Delivery System • Bangalore Logistics Center
      </footer>
    </div>
  );
};
export default App;

