        {activeTab === 'dashboard' && renderDashboard()}
        {activeTab === 'map' && (
          <div className="bg-white p-5 rounded-xl border border-slate-200 shadow-sm space-y-4">
            <h2 className="text-base font-bold text-slate-900">Bangalore Transport & Node Live Map</h2>
            <MapView locations={locations} connections={connections} workers={workers} samples={samples} />
          </div>
        )}
        {activeTab === 'audit' && <AuditSearch />}
        {activeTab === 'admin' && currentUser.activeRole === 'administrator' && <AdminManagementView />}
      </main>

      <footer className="bg-white border-t border-slate-200 py-4 text-center text-xs text-slate-400">
        Lab Sample Pickup & Delivery System • Bangalore Logistics Center
      </footer>
    </div>
  );
};
export default App;

