package services

import (
	"database/sql"
	"encoding/json"
	"errors"
	"fmt"
	"labsystem/internal/models"
	"time"

	"github.com/google/uuid"
	"github.com/lib/pq"
)

var (
	ErrHandlingMismatch     = errors.New("handling_mismatch")
	ErrInvalidOrigin        = errors.New("invalid_origin")
	ErrInvalidCollectionTime = errors.New("invalid_collection_window")
	ErrInvalidDeadline      = errors.New("invalid_deadline")
	ErrNoValidRoute         = errors.New("no_valid_route")
	ErrStalePlan            = errors.New("stale_plan")
	ErrInactivePlan         = errors.New("inactive_plan")
	ErrIncompatibleBatch    = errors.New("incompatible_batch")
	ErrPulseNoBatch         = errors.New("pulse_no_batch")
	ErrCapacityExhausted    = errors.New("capacity_exhausted")
	ErrDeadlineExceeded     = errors.New("deadline_exceeded")
	ErrCompletedWorkImmutable = errors.New("completed_work_immutable")
)

type JourneyService struct {
