			if err := legRows.Scan(&leg.AssignmentID, &leg.Sequence, &leg.Status, &fromLoc, &toLoc, &wID, &sID, &kind); err == nil {
				leg.Assignment_ID = leg.AssignmentID
				if fromLoc.Valid {
