				}
				if wID.Valid {
					leg.WorkerID = &wID.String
					leg.Worker_ID = &wID.String
					assignedWorkers = append(assignedWorkers, wID.String)
				}
				if sID.Valid {
					leg.SampleID = &sID.String
				}
				jp.Legs = append(jp.Legs, leg)

				if kind == "collection" {
					if jp.CollectionAssignmentID == nil {
						jp.CollectionAssignmentID = &leg.AssignmentID
					}
					jp.CollectionAssignmentIDs = append(jp.CollectionAssignmentIDs, leg.AssignmentID)
				} else if kind == "node" {
					jp.NodeAssignmentIDs = append(jp.NodeAssignmentIDs, leg.AssignmentID)
				} else if kind == "laboratory" {
					jp.LaboratoryAssignmentIDs = append(jp.LaboratoryAssignmentIDs, leg.AssignmentID)
				} else if kind == "transport" {
					if jp.FirstTransportAssignmentID == nil {
						jp.FirstTransportAssignmentID = &leg.AssignmentID
					}
					jp.FinalTransportAssignmentID = &leg.AssignmentID
				}
			}
		}
	}
	if jp.Legs == nil {
		jp.Legs = []models.JourneyLeg{}
	}
	jp.AssignedWorkerIDs = assignedWorkers

	return &jp, nil
}

