package services

import (
	"database/sql"
	"encoding/json"
	"errors"
	"fmt"
	"labsystem/internal/models"
	"time"

	"github.com/google/uuid"
	"github.com/lib/pq"
	"golang.org/x/crypto/bcrypt"
)

var (
	ErrInvalidCredentials = errors.New("invalid_credentials")
	ErrRoleNotHeld        = errors.New("role_not_held")
	ErrUserNotFound       = errors.New("not_found")
	ErrUsernameExists     = errors.New("username_exists")
	ErrUnauthorized       = errors.New("unauthorized")
	ErrForbidden          = errors.New("forbidden")
)

type AuthService struct {
	DB           *sql.DB
	AuditService *AuditService
	EventService *EventService
}

func NewAuthService(db *sql.DB, audit *AuditService, events *EventService) *AuthService {
	return &AuthService{
		DB:           db,
		AuditService: audit,
		EventService: events,
	}
}

type AuthUser struct {
	ID                 string
	Username           string
	Email              *string
	FullName           *string
	Phone              *string
	Roles              []string
	ActiveRole         string
	Qualifications     []string
	Certifications     []models.Certification
	Active             bool
	AssignedLocationID *string
	CapacityUnits      int
	Available          bool
	LatestLocation     *models.Coordinate
	LocationRecordedAt *time.Time
}

func (s *AuthService) Authenticate(username, password string) (string, *AuthUser, error) {
	var u AuthUser
	var passwordHash string
	var certsRaw []byte
	var roles pq.StringArray
	var quals pq.StringArray
	var activeRole sql.NullString
	var assignedLoc sql.NullString
	var email sql.NullString
	var fullName sql.NullString
	var phone sql.NullString
	var latestLocRaw []byte
	var locRecordedAt sql.NullTime

	err := s.DB.QueryRow(`
		SELECT id, username, password_hash, email, full_name, phone, roles, active_role, qualifications, certifications, active, assigned_location_id, capacity_units, available, latest_location, location_recorded_at
		FROM users
