	if !held {
		s.AuditService.LogAudit(u.ID, u.ActiveRole, "role.select", "user", u.ID, false, map[string]interface{}{
			"attemptedRole": newRole,
			"heldRoles":     u.Roles,
			"error":         "role_not_held",
		})
		return "", nil, ErrRoleNotHeld
	}

