		Username:       username,
		Email:          email,
		FullName:       fullName,
		Phone:          phone,
		Roles:          roles,
		Qualifications: quals,
		Certifications: certs,
		Active:         active,
	}, nil
}

func (s *AuthService) UpdateUserAccess(actor *AuthUser, targetUserID string, roles []string, quals []string, certs []models.Certification, active bool, assignedLoc *string) (*models.User, error) {
	if actor.ActiveRole != "administrator" {
		return nil, ErrForbidden
	}

	if quals == nil {
		quals = []string{}
	}
	if certs == nil {
		certs = []models.Certification{}
	}
	certsJSON, _ := json.Marshal(certs)

	res, err := s.DB.Exec(`
		UPDATE users
		SET roles = $1, qualifications = $2, certifications = $3::jsonb, active = $4, assigned_location_id = $5, updated_at = NOW()
		WHERE id = $6
	`, pq.Array(roles), pq.Array(quals), string(certsJSON), active, assignedLoc, targetUserID)
	if err != nil {
		return nil, err
	}
	rowsAffected, _ := res.RowsAffected()
	if rowsAffected == 0 {
		return nil, ErrUserNotFound
	}

	var username string
	var email, fullName, phone sql.NullString
	_ = s.DB.QueryRow(`SELECT username, email, full_name, phone FROM users WHERE id = $1`, targetUserID).Scan(&username, &email, &fullName, &phone)

	var emailPtr, fullNamePtr, phonePtr *string
	if email.Valid {
		emailPtr = &email.String
	}
	if fullName.Valid {
		fullNamePtr = &fullName.String
	}
	if phone.Valid {
		phonePtr = &phone.String
	}

	s.AuditService.LogAudit(actor.ID, actor.ActiveRole, "user.update_access", "user", targetUserID, true, map[string]interface{}{
		"roles":  roles,
		"quals":  quals,
		"active": active,
	})

	s.EventService.Broadcast("user.updated", "user", targetUserID, map[string]interface{}{
		"userId": targetUserID,
		"roles":  roles,
		"active": active,
	})

	return &models.User{
		UserID:         targetUserID,
		Username:       username,
		Email:          emailPtr,
		FullName:       fullNamePtr,
		Phone:          phonePtr,
		Roles:          roles,
		Qualifications: quals,
		Certifications: certs,
		Active:         active,
	}, nil
}

func (s *AuthService) GetUser(userID string) (*models.User, error) {
	var u models.User
	var email, fullName, phone sql.NullString
	var roles, quals pq.StringArray
	var certsRaw []byte

	err := s.DB.QueryRow(`
		SELECT id, username, email, full_name, phone, roles, qualifications, certifications, active
		FROM users
		WHERE id = $1
	`, userID).Scan(&u.UserID, &u.Username, &email, &fullName, &phone, &roles, &quals, &certsRaw, &u.Active)

	if err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return nil, ErrUserNotFound
		}
		return nil, err
	}

	u.Roles = []string(roles)
	u.Qualifications = []string(quals)
	if email.Valid {
		u.Email = &email.String
	}
	if fullName.Valid {
		u.FullName = &fullName.String
	}
	if phone.Valid {
		u.Phone = &phone.String
	}
	_ = json.Unmarshal(certsRaw, &u.Certifications)
	if u.Certifications == nil {
		u.Certifications = []models.Certification{}
	}

	return &u, nil
}

