package services

import (
	"database/sql"
	"errors"
	"fmt"
	"labsystem/internal/models"
	"time"

	"github.com/google/uuid"
)

var (
	ErrNotCurrentHolder     = errors.New("not_current_holder")
	ErrPendingHandoffExists = errors.New("pending_handoff_exists")
	ErrHandoffNotFound      = errors.New("not_found")
	ErrCustodyConflict      = errors.New("custody_conflict")
)

type HandoffService struct {
	DB           *sql.DB
	AuditService *AuditService
	EventService *EventService
}

func NewHandoffService(db *sql.DB, audit *AuditService, events *EventService) *HandoffService {
	return &HandoffService{
		DB:           db,
		AuditService: audit,
		EventService: events,
	}
}

type HandoffResult struct {
	HandoffID        string `json:"handoffId"`
	SenderID         string `json:"senderId"`
	ReceiverID       string `json:"receiverId"`
	CurrentHolderID  string `json:"currentHolderId"`
	Status           string `json:"status"`
	SenderConfirmed   bool   `json:"senderConfirmed"`
	ReceiverConfirmed bool   `json:"receiverConfirmed"`
}

func (s *HandoffService) InitiateHandoff(sampleID, fromAssignmentID, toAssignmentID, senderID, receiverID string, initiatedAt time.Time) (*HandoffResult, error) {
	// Check current holder of sample
	var currentHolder sql.NullString
	var sampleStatus string
	err := s.DB.QueryRow(`SELECT current_holder_id, status FROM samples WHERE id = $1`, sampleID).Scan(&currentHolder, &sampleStatus)
	if err != nil {
		return nil, ErrHandoffNotFound
	}

	if currentHolder.Valid && currentHolder.String != senderID {
		return nil, ErrNotCurrentHolder
	}

	// Check if pending handoff already exists
	var pendingCount int
	_ = s.DB.QueryRow(`SELECT COUNT(*) FROM handoffs WHERE sample_id = $1 AND status = 'pending'`, sampleID).Scan(&pendingCount)
	if pendingCount > 0 {
		return nil, ErrPendingHandoffExists
	}

	handoffID := uuid.New().String()
	_, err = s.DB.Exec(`
		INSERT INTO handoffs (id, sample_id, from_assignment_id, to_assignment_id, sender_id, receiver_id, status, sender_confirmed, receiver_confirmed, current_holder_id, initiated_at)
		VALUES ($1, $2, $3, $4, $5, $6, 'pending', true, false, $7, $8)
	`, handoffID, sampleID, fromAssignmentID, toAssignmentID, senderID, receiverID, senderID, initiatedAt)
	if err != nil {
		return nil, fmt.Errorf("failed creating handoff: %w", err)
	}

	s.AuditService.LogTimeline("handoff.initiated", senderID, "sender", "sample", sampleID, true, map[string]interface{}{
		"handoffId":  handoffID,
		"senderId":   senderID,
		"receiverId": receiverID,
	})

	s.AuditService.LogAudit(senderID, "sender", "handoff.initiate", "handoff", handoffID, true, map[string]interface{}{
		"sampleId":   sampleID,
		"receiverId": receiverID,
	})

	s.EventService.Broadcast("handoff.initiated", "handoff", handoffID, map[string]interface{}{
		"handoffId":  handoffID,
		"sampleId":   sampleID,
		"senderId":   senderID,
		"receiverId": receiverID,
	})

	return &HandoffResult{
		HandoffID:         handoffID,
		SenderID:          senderID,
		ReceiverID:        receiverID,
		CurrentHolderID:   senderID,
		Status:            "pending",
		SenderConfirmed:   true,
		ReceiverConfirmed: false,
	}, nil
}

func (s *HandoffService) ConfirmHandoff(handoffID string, confirmationSide string, actorID string, confirmedAt time.Time) (*HandoffResult, error) {
	var sampleID, senderID, receiverID, status, currentHolderID string
	var senderConf, receiverConf bool
	var toAssignmentID sql.NullString

	err := s.DB.QueryRow(`
		SELECT sample_id, sender_id, receiver_id, status, sender_confirmed, receiver_confirmed, current_holder_id, to_assignment_id
		FROM handoffs
		WHERE id = $1
	`, handoffID).Scan(&sampleID, &senderID, &receiverID, &status, &senderConf, &receiverConf, &currentHolderID, &toAssignmentID)

	if err != nil {
		return nil, ErrHandoffNotFound
	}

	if status == "confirmed" {
		return &HandoffResult{
			HandoffID:         handoffID,
			SenderID:          senderID,
			ReceiverID:        receiverID,
			CurrentHolderID:   currentHolderID,
			Status:            "confirmed",
			SenderConfirmed:   senderConf,
			ReceiverConfirmed: receiverConf,
		}, nil
	}

	if confirmationSide == "sender" {
		senderConf = true
	} else if confirmationSide == "receiver" {
		receiverConf = true
	} else {
		return nil, fmt.Errorf("invalid_confirmation_side")
	}

	finalStatus := "pending"
	newHolderID := currentHolderID

	if senderConf && receiverConf {
		finalStatus = "confirmed"
		newHolderID = receiverID

		// Update sample holder
		_, err = s.DB.Exec(`
			UPDATE samples
			SET current_holder_id = $1, status = 'in_transit', updated_at = NOW()
			WHERE id = $2
		`, newHolderID, sampleID)
		if err != nil {
			return nil, err
		}

		if toAssignmentID.Valid {
			_, _ = s.DB.Exec(`UPDATE assignments SET status = 'in_progress', updated_at = NOW() WHERE id = $1`, toAssignmentID.String)
		}

		s.AuditService.LogTimeline("custody.transferred", actorID, confirmationSide, "sample", sampleID, true, map[string]interface{}{
			"handoffId":       handoffID,
			"previousHolder":  senderID,
			"newHolder":       receiverID,
			"confirmedAt":     models.FormatTime(confirmedAt),
		})

		s.AuditService.LogAudit(actorID, confirmationSide, "handoff.confirm_complete", "handoff", handoffID, true, map[string]interface{}{
			"sampleId":        sampleID,
			"currentHolderId": receiverID,
		})
	}

	_, err = s.DB.Exec(`
		UPDATE handoffs
		SET status = $1, sender_confirmed = $2, receiver_confirmed = $3, current_holder_id = $4, confirmed_at = $5, updated_at = NOW()
		WHERE id = $6
	`, finalStatus, senderConf, receiverConf, newHolderID, confirmedAt, handoffID)
	if err != nil {
		return nil, err
	}

	s.EventService.Broadcast("handoff.confirmed", "handoff", handoffID, map[string]interface{}{
		"handoffId":       handoffID,
		"status":          finalStatus,
		"currentHolderId": newHolderID,
	})

	return &HandoffResult{
		HandoffID:         handoffID,
		SenderID:          senderID,
		ReceiverID:        receiverID,
		CurrentHolderID:   newHolderID,
		Status:            finalStatus,
		SenderConfirmed:   senderConf,
		ReceiverConfirmed: receiverConf,
	}, nil
}

