import json

def verify_contract_parity():
    with open("/workspace/contracts/openapi.contract.json") as f:
        contract = json.load(f)

    with open("/workspace/app-setup/openapi.json") as f:
        app_spec = json.load(f)

    contract_paths = contract.get("paths", {})
    app_paths = app_spec.get("paths", {})

    print(f"Contract path count: {len(contract_paths)}")
    print(f"App spec path count: {len(app_paths)}")

    missing_paths = []
    missing_ops = []

    for path, path_obj in contract_paths.items():
        if path not in app_paths:
            missing_paths.append(path)
            continue
        for method, op in path_obj.items():
            if method not in app_paths[path]:
                missing_ops.append((path, method))
            else:
                contract_op_id = op.get("operationId")
                app_op_id = app_paths[path][method].get("operationId")
                if contract_op_id != app_op_id:
                    print(f"OpID mismatch at {method.upper()} {path}: contract={contract_op_id}, app={app_op_id}")

    if missing_paths:
        print("Missing paths:", missing_paths)
    if missing_ops:
        print("Missing operations:", missing_ops)

    if not missing_paths and not missing_ops:
        print("✓ 100% OpenAPI Path & Operation Parity Verified!")

if __name__ == "__main__":
    verify_contract_parity()

